/* "Sobre a matéria" — a página de livro-texto de cada questão de prev.
   Chave "fonte#numero" (a mesma da entrada); HTML em linhas, uma tag de
   bloco por linha (montar.js tira as quebras). Seis partes na ordem:
   Objetivos de aprendizagem · Termos-chave · O essencial · Ponto clínico
   (div.ponto) · Resumo · Verifique o que aprendeu. As regras estão em
   verificar.js. Escrito à mão. */
module.exports = {
"susp2026#81": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar os atributos da Atenção Primária segundo Starfield.</li>
<li>Explicar o apoio matricial e o papel das equipes multiprofissionais (eMulti).</li>
<li>Distinguir o que é da equipe de Saúde da Família e o que é da regulação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Atributos essenciais</dt>
<dd>Acesso de primeiro contato, longitudinalidade, integralidade e coordenação do cuidado.</dd>
<dt>Atributos derivados</dt>
<dd>Orientação familiar, orientação comunitária e competência cultural.</dd>
<dt>Apoio matricial</dt>
<dd>Suporte técnico-pedagógico e assistencial de especialistas às equipes, sem tirar delas o cuidado.</dd>
<dt>eMulti</dt>
<dd>Equipe multiprofissional na APS (2023), sucessora do NASF-AB, que faz o matriciamento.</dd>
</dl>
<h4>O essencial</h4>
<p>A Atenção Primária é a porta de entrada preferencial do SUS e se define pelos <strong>atributos de Starfield</strong>: <strong>acesso de primeiro contato</strong> (a equipe é procurada primeiro e resolve a maioria dos problemas), <strong>longitudinalidade</strong> (vínculo ao longo do tempo com a mesma equipe), <strong>integralidade</strong> (oferta de tudo o que a população precisa, do preventivo ao paliativo, com arranjos para o que não oferece) e <strong>coordenação</strong> (a equipe organiza o cuidado que acontece em outros pontos da rede). A esses se somam os derivados: orientação familiar, orientação comunitária e competência cultural. A Estratégia Saúde da Família, com território e população <strong>adscritos</strong>, é o modelo prioritário para concretizá-los.</p>
<p>O <strong>apoio matricial</strong> é o instrumento da integralidade: especialistas (psicólogo, nutricionista, fisioterapeuta, farmacêutico, psiquiatra, entre outros) apoiam as equipes de referência com discussão de casos, atendimento compartilhado, consultorias e educação permanente, <strong>ampliando a capacidade clínica</strong> da equipe em vez de receber encaminhamentos. Foi criado com os NASF em 2008; a Portaria 635/2023 reorganizou o arranjo como <strong>eMulti</strong>, financiada por equipe, vinculada a um conjunto de equipes de Saúde da Família.</p>
<p>O que não é da equipe: a <strong>regulação</strong> do acesso à atenção especializada e hospitalar é função dos complexos reguladores do gestor, embora a equipe coordene o cuidado e acione a regulação. A adscrição não é restrição de acesso: o usuário fora de área é acolhido e orientado. E a integralidade não significa que a unidade faça tudo, mas que garanta o caminho para o que não faz.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um caso de saúde mental leve chega, a resposta da integralidade não é encaminhar ao CAPS, é discutir com a eMulti, fazer o atendimento compartilhado e seguir como equipe de referência. O matriciamento é o oposto do encaminhamento.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Starfield: primeiro contato, longitudinalidade, integralidade, coordenação; derivados: família, comunidade, cultura.</li>
<li>Apoio matricial (eMulti, ex-NASF) amplia a capacidade clínica da equipe: integralidade.</li>
<li>Adscrição é responsabilidade pelo território, não barreira.</li>
<li>Regulação é do gestor; a equipe coordena e aciona.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual atributo o matriciamento fortalece e por quê? <details><summary>Resposta</summary>A integralidade, porque amplia o que a equipe de referência resolve, sem transferir o cuidado.</details></li>
<li>O que substituiu o NASF-AB e quando? <details><summary>Resposta</summary>As equipes multiprofissionais (eMulti), pela Portaria GM/MS 635 de 2023.</details></li>
</ol>
`,
"susp2026#82": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar os critérios do rastreamento de aneurisma de aorta abdominal.</li>
<li>Conhecer os critérios do rastreamento de câncer de pulmão e os limites de carga e abstinência.</li>
<li>Escolher o rastreamento certo pelo perfil exato do paciente.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Rastreamento</dt>
<dd>Teste em assintomáticos para detectar doença em fase pré-clínica em quem se beneficia do tratamento precoce.</dd>
<dt>Anos-maço</dt>
<dd>Maços por dia multiplicados pelos anos de fumo; 15 anos-maço já contam para a aorta.</dd>
<dt>Recomendação B da USPSTF</dt>
<dd>Benefício líquido moderado; o rastreamento deve ser oferecido.</dd>
<dt>Tomografia de baixa dose</dt>
<dd>Exame anual de rastreamento de câncer de pulmão em fumantes pesados de 50 a 80 anos.</dd>
</dl>
<h4>O essencial</h4>
<p>Rastrear é buscar doença em quem não tem sintomas, e só vale quando o teste é acurado, a doença tem fase pré-clínica detectável e tratá-la cedo muda o desfecho. Por isso cada rastreamento tem <strong>critérios estritos</strong> de idade, sexo e exposição, e o exercício clínico é encaixar o paciente neles.</p>
<p>O <strong>aneurisma de aorta abdominal</strong> mata por rotura, e a <strong>ultrassonografia abdominal única</strong> em <strong>homens de 65 a 75 anos que já fumaram</strong> (100 cigarros na vida ou mais) reduz a mortalidade específica: recomendação B da USPSTF. Homens da mesma faixa que nunca fumaram podem ser rastreados seletivamente (história familiar); mulheres não têm indicação de rotina. O tempo desde que parou de fumar não importa: quem fumou 15 anos-maço e parou há 30 anos ainda faz o ultrassom.</p>
<p>O <strong>câncer de pulmão</strong> tem regras diferentes: <strong>tomografia de baixa dose anual</strong> em adultos de <strong>50 a 80 anos</strong> com <strong>20 anos-maço ou mais</strong>, que fumam ou <strong>pararam há menos de 15 anos</strong>. Quem parou há 30 anos ou fumou menos que a carga mínima não se beneficia, porque o risco já caiu. Os demais rastreamentos do homem dessa idade seguem as regras próprias: colorretal de 45 a 75 anos, pressão arterial, glicemia e lipídios; o PSA é decisão compartilhada, e no Brasil não é rastreamento populacional.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de pedir a tomografia de pulmão, calcule os anos-maço e a data em que parou; antes de pedir o ultrassom de aorta, pergunte só "já fumou?". Os dois rastreamentos parecem irmãos, mas os critérios são diferentes, e a prova cobra a diferença.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Aorta abdominal: ultrassom único, homens de 65 a 75 anos que já fumaram, sem limite de abstinência.</li>
<li>Pulmão: tomografia de baixa dose anual, 50 a 80 anos, 20 anos-maço ou mais, fumante ou parou há menos de 15 anos.</li>
<li>Mulheres: sem rastreamento de rotina da aorta.</li>
<li>Colorretal 45 a 75 anos; PSA por decisão compartilhada.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Homem de 66 anos, 15 anos-maço, parou há 30 anos: que rastreamento cabe? <details><summary>Resposta</summary>Ultrassonografia de aorta abdominal; a tomografia de pulmão não, pela carga menor que 20 anos-maço e abstinência maior que 15 anos.</details></li>
<li>Quais são os três critérios do rastreamento de câncer de pulmão? <details><summary>Resposta</summary>50 a 80 anos, 20 anos-maço ou mais, e fumar atualmente ou ter parado há menos de 15 anos.</details></li>
</ol>
`,
"susp2026#83": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reproduzir a sequência dos passos da investigação de surto.</li>
<li>Explicar por que confirmar o surto e o diagnóstico vem antes de qualquer hipótese.</li>
<li>Reconhecer os erros de pular etapas.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Surto</dt>
<dd>Número de casos acima do esperado para o lugar e o período, em área restrita.</dd>
<dt>Série histórica</dt>
<dd>Registros dos mesmos períodos em anos anteriores, que definem o esperado.</dd>
<dt>Definição de caso</dt>
<dd>Critérios clínicos, laboratoriais, de tempo, lugar e pessoa que dizem quem entra na contagem.</dd>
<dt>Epidemiologia descritiva</dt>
<dd>Distribuição dos casos por tempo (curva epidêmica), lugar e pessoa, que gera as hipóteses.</dd>
</dl>
<h4>O essencial</h4>
<p>A investigação de surto segue uma <strong>sequência</strong> que existe para não desperdiçar recursos e não perseguir fantasmas. Primeiro, <strong>preparar</strong> o trabalho de campo. Segundo, <strong>confirmar a existência do surto</strong>: comparar o número de casos com o <strong>esperado</strong>, pela série histórica do mesmo período e local, e checar se o aumento não é artefato (mudança de notificação, novo laboratório, mais procura por outro motivo). Terceiro, <strong>verificar o diagnóstico</strong>: revisar prontuários e resultados, examinar pacientes, garantir que os casos são a mesma doença. Só então vêm a <strong>definição de caso</strong>, a <strong>busca ativa</strong> e a contagem, a <strong>epidemiologia descritiva</strong> (tempo, lugar, pessoa), a <strong>formulação de hipóteses</strong>, o <strong>teste das hipóteses</strong> com estudo analítico (caso-controle ou coorte), os estudos complementares de laboratório e ambiente, as <strong>medidas de controle</strong> e a comunicação dos achados.</p>
<p>As medidas de controle podem e devem ser antecipadas quando há risco evidente (retirar um alimento suspeito, isolar uma fonte de água), mas a investigação formal não começa pelo estudo analítico nem pela intervenção ampla: sem confirmar que há surto e que os casos são de fato gastroenterite da mesma causa, o caso-controle compara coisas diferentes e o controle pode mirar a fonte errada.</p>
<p>A curva epidêmica diz muito: fonte comum pontual produz um pico único com casos dentro de um período de incubação; fonte contínua, um platô; transmissão pessoa a pessoa, ondas sucessivas. A definição de caso pode ter graus (suspeito, provável, confirmado) e é ajustada durante a investigação.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>O aumento de gastroenterites numa UPA depois de um feriado pode ser só o feriado. Antes de mobilizar a vigilância inteira, abra a série histórica, leia os prontuários e ligue para o laboratório. Confirmar e verificar leva um dia e evita semanas de investigação errada.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Sequência: preparar, confirmar o surto, verificar o diagnóstico, definir caso, buscar casos, descrever, hipóteses, testar, controlar, comunicar.</li>
<li>Confirmar o surto: comparar com a série histórica e afastar artefatos.</li>
<li>Verificar o diagnóstico: prontuários, exames, pacientes.</li>
<li>Controle imediato só diante de risco evidente; estudo analítico só depois das hipóteses.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os dois primeiros passos após a notificação de um possível surto? <details><summary>Resposta</summary>Confirmar a existência do surto pela comparação com o esperado e verificar o diagnóstico dos casos.</details></li>
<li>O que uma curva epidêmica com um único pico sugere? <details><summary>Resposta</summary>Fonte comum pontual, com os casos distribuídos dentro de um período de incubação.</details></li>
</ol>
`,
"susp2026#84": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conduzir a exposição à varicela na gestante: sorologia antes da imunoglobulina.</li>
<li>Conhecer as indicações e o prazo da imunoglobulina antivaricela-zóster.</li>
<li>Saber por que a vacina é contraindicada na gestação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Suscetível</dt>
<dd>Sem história confiável de varicela, sem vacinação e com IgG negativa.</dd>
<dt>Imunoglobulina antivaricela-zóster (VZIG)</dt>
<dd>Anticorpos passivos que atenuam a doença se dados em até 96 horas, aceitos até 10 dias, após o contato.</dd>
<dt>Contato significativo</dt>
<dd>Domiciliar, face a face por 5 minutos ou mais, ou mesmo ambiente por 1 hora ou mais.</dd>
<dt>Síndrome da varicela congênita</dt>
<dd>Lesões cutâneas cicatriciais, hipoplasia de membros, lesões oculares e neurológicas, na infecção até 20 semanas.</dd>
</dl>
<h4>O essencial</h4>
<p>A varicela na gestação é perigosa para dois: para a mãe, pela pneumonia varicelosa, mais grave no terceiro trimestre; para o feto, pela <strong>síndrome da varicela congênita</strong> quando a infecção ocorre até 20 semanas, e pela varicela neonatal grave quando a mãe adoece entre 5 dias antes e 2 dias depois do parto. A maioria das adultas brasileiras é imune, por doença na infância ou vacina, e por isso a primeira pergunta diante de uma exposição é <strong>ela é suscetível?</strong></p>
<p>A história de varicela prévia confiável ou de duas doses de vacina define imunidade. Sem essa história, colhe-se <strong>sorologia IgG</strong> para o vírus varicela-zóster, com resultado em 24 a 48 horas, o que cabe na janela da profilaxia. IgG positiva: imune, sem conduta. IgG negativa: <strong>suscetível</strong>, e a gestante recebe <strong>imunoglobulina antivaricela-zóster</strong>, idealmente em até <strong>96 horas</strong> do contato, aceita até 10 dias, disponível nos CRIE. A imunoglobulina reduz a gravidade materna; o efeito sobre a infecção fetal é incerto. Se não houver imunoglobulina, o aciclovir a partir do 7º dia do contato é opção discutida. Se a gestante já tem a doença, recebe aciclovir, oral nos casos leves e venoso na pneumonia.</p>
<p>A <strong>vacina</strong> contra varicela é de vírus vivo atenuado e é <strong>contraindicada na gestação</strong>; a suscetível é vacinada no puerpério. A exposição também é a hora de orientar isolamento do caso índice até as lesões formarem crostas e de vacinar os contatos suscetíveis não gestantes em até 5 dias.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Não pule a sorologia para "garantir": a imunoglobulina é escassa, cara e desnecessária em quem tem IgG positiva, e o resultado chega a tempo. E nunca vacine a gestante; anote a suscetibilidade e vacine depois do parto.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Primeiro: história e sorologia IgG para saber se é suscetível.</li>
<li>Suscetível: imunoglobulina em até 96 horas (até 10 dias).</li>
<li>Vacina viva: contraindicada na gestação; vacinar no puerpério.</li>
<li>Doença na gestante: aciclovir; risco fetal até 20 semanas e periparto.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Gestante sem história de varicela expõe-se ao sobrinho doente: qual é o primeiro passo? <details><summary>Resposta</summary>Colher sorologia IgG para varicela-zóster; se negativa, imunoglobulina em até 96 horas.</details></li>
<li>Por que não vacinar a gestante exposta? <details><summary>Resposta</summary>A vacina é de vírus vivo atenuado, contraindicada na gestação.</details></li>
</ol>
`,
"susp2026#85": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir viés de confusão e distingui-lo de viés de seleção e de aferição.</li>
<li>Explicar por que os estudos observacionais de tratamento são vulneráveis à confusão.</li>
<li>Separar precisão (intervalo de confiança) de validade (ausência de viés).</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Confusão</dt>
<dd>Distorção por uma terceira variável associada à exposição e ao desfecho, que não está no caminho causal.</dd>
<dt>Confusão por indicação</dt>
<dd>Quem recebe o tratamento difere de quem não recebe por gravidade ou prognóstico.</dd>
<dt>Viés de seleção</dt>
<dd>Distorção pela forma como os participantes entram ou saem do estudo.</dd>
<dt>Precisão</dt>
<dd>Quanto o acaso afeta a estimativa; um intervalo de confiança estreito é preciso, não necessariamente válido.</dd>
</dl>
<h4>O essencial</h4>
<p>Um estudo pode errar por <strong>acaso</strong> ou por <strong>viés</strong>. O acaso é medido pelo intervalo de confiança e diminui com o tamanho da amostra; o viés é um erro sistemático que não diminui com mais pacientes. Os três grandes vieses: <strong>seleção</strong> (quem entrou no estudo não representa a população, ou casos e controles vieram de fontes diferentes), <strong>aferição ou informação</strong> (exposição ou desfecho medidos de forma diferente entre os grupos, como o viés de memória) e <strong>confusão</strong>.</p>
<p>A <strong>confusão</strong> acontece quando uma terceira variável está ligada tanto à exposição quanto ao desfecho e não é consequência da exposição. Em estudos observacionais de <strong>tratamento</strong>, o problema é quase inevitável: o médico escolhe quem recebe a droga nova, e escolhe pela gravidade, pela idade, pelo acesso, pelas comorbidades. Se quem recebeu o tratamento novo tinha doença menos grave, o tratamento parecerá melhor sem sê-lo: é a <strong>confusão por indicação</strong>. Um caso-controle retrospectivo de centro único, sem randomização, com o tratamento decidido pelos médicos, tem essa fragilidade no núcleo.</p>
<p>As defesas contra a confusão: no desenho, a <strong>randomização</strong> (que distribui os confundidores conhecidos e desconhecidos) e a restrição ou o pareamento; na análise, a estratificação, o ajuste multivariado e o escore de propensão, que só funcionam para confundidores medidos. Um intervalo de confiança estreito e um p pequeno dizem que o resultado não é acaso, mas nada dizem sobre confusão: <strong>precisão não é validade</strong>.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao ler um estudo observacional que mostra que uma droga "reduziu a mortalidade", pergunte primeiro quem decidiu quem tomaria a droga e por quê. Se a resposta é "o médico", a confusão por indicação está na mesa, por mais estreito que seja o intervalo.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Acaso: intervalo de confiança; viés: erro sistemático, não corrigido pelo tamanho.</li>
<li>Confusão: terceira variável ligada à exposição e ao desfecho, fora do caminho causal.</li>
<li>Estudos observacionais de tratamento: confusão por indicação.</li>
<li>Defesas: randomização, pareamento, estratificação, ajuste, escore de propensão.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que é confusão por indicação? <details><summary>Resposta</summary>Distorção porque quem recebe o tratamento difere em gravidade ou prognóstico de quem não recebe, por decisão clínica.</details></li>
<li>Um intervalo de confiança estreito afasta viés? <details><summary>Resposta</summary>Não; ele reflete precisão (pouco acaso), não validade.</details></li>
</ol>
`,
"susp2026#86": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar os pontos de corte brasileiros do diabetes na primeira consulta de pré-natal.</li>
<li>Diferenciar diabetes gestacional de diabetes prévio diagnosticado na gestação.</li>
<li>Iniciar o tratamento: dieta, atividade física e monitorização.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Diabetes mellitus gestacional</dt>
<dd>Hiperglicemia detectada na gestação que não atinge os critérios de diabetes franco.</dd>
<dt>Diabetes prévio (overt)</dt>
<dd>Glicemia de jejum de 126 mg/dL ou mais, ou glicemia ao acaso de 200 ou mais com sintomas, na gestação.</dd>
<dt>TOTG 75 g</dt>
<dd>Teste de tolerância entre 24 e 28 semanas para quem teve jejum abaixo de 92 na primeira consulta.</dd>
<dt>Automonitorização</dt>
<dd>Glicemias capilares em jejum e pós-prandiais que guiam a necessidade de insulina.</dd>
</dl>
<h4>O essencial</h4>
<p>O protocolo brasileiro (OPAS, Ministério da Saúde, FEBRASGO e SBD, 2017) começa pela <strong>glicemia de jejum na primeira consulta</strong>, antes de 20 semanas. <strong>Abaixo de 92 mg/dL</strong>: normal, e a gestante faz o <strong>TOTG de 75 g entre 24 e 28 semanas</strong> (jejum 92, 1 hora 180, 2 horas 153; um valor alterado fecha o diagnóstico). <strong>De 92 a 125 mg/dL</strong>: <strong>diabetes mellitus gestacional já diagnosticado</strong>, sem necessidade de repetir nem de fazer o TOTG. <strong>126 mg/dL ou mais</strong> (ou glicemia ao acaso de 200 ou mais com sintomas): <strong>diabetes prévio</strong> diagnosticado na gestação, que tem risco maior de malformações e exige avaliação de órgãos-alvo.</p>
<p>O diagnóstico na primeira consulta leva ao <strong>tratamento imediato</strong>: orientação alimentar com nutricionista, atividade física regular, ganho de peso adequado e <strong>automonitorização</strong> da glicemia capilar (jejum e pós-prandiais), com metas de jejum abaixo de 95 e 1 hora pós-prandial abaixo de 140. Se em 1 a 2 semanas as metas não forem atingidas com dieta e exercício, ou se houver crescimento fetal excessivo, inicia-se <strong>insulina</strong>, o fármaco de escolha; a metformina é opção em situações específicas. O pré-natal passa a ser de alto risco compartilhado, com ultrassonografias para crescimento e vigilância do bem-estar fetal no terceiro trimestre.</p>
<p>Os riscos que o tratamento reduz: macrossomia, distocia de ombro, pré-eclâmpsia, cesárea, hipoglicemia neonatal e, para a mãe, diabetes tipo 2 no futuro, o que exige reclassificação com TOTG 6 semanas após o parto.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Jejum de 96 na primeira consulta não é "limítrofe, repetir": é diabetes gestacional pela regra brasileira, e cada semana de atraso é uma semana de hiperglicemia fetal. Diagnostique, explique, marque a nutricionista e entregue o glicosímetro na mesma consulta.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Primeira consulta: jejum abaixo de 92 normal; 92 a 125 diabetes gestacional; 126 ou mais, diabetes prévio.</li>
<li>Normais fazem TOTG 75 g entre 24 e 28 semanas (92/180/153).</li>
<li>Tratamento imediato: dieta, exercício, automonitorização; insulina se as metas não vêm.</li>
<li>Reclassificar com TOTG 6 semanas após o parto.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Glicemia de jejum de 98 mg/dL com 10 semanas: qual é o diagnóstico e a conduta? <details><summary>Resposta</summary>Diabetes mellitus gestacional; iniciar dieta, atividade física e automonitorização de imediato, sem TOTG.</details></li>
<li>Quando a insulina entra? <details><summary>Resposta</summary>Quando as metas glicêmicas não são atingidas em 1 a 2 semanas de medidas não farmacológicas ou há crescimento fetal excessivo.</details></li>
</ol>
`,
"susp2026#87": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Nomear os nove pontos de vista de Bradford Hill.</li>
<li>Explicar por que a temporalidade é o único critério indispensável.</li>
<li>Conhecer as críticas modernas ao uso dos critérios como lista de verificação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Temporalidade</dt>
<dd>A causa precede o efeito; sem isso não há causalidade possível.</dd>
<dt>Força da associação</dt>
<dd>Magnitude do risco relativo; associações fortes são menos explicáveis por viés.</dd>
<dt>Gradiente biológico</dt>
<dd>Relação dose-resposta entre exposição e desfecho.</dd>
<dt>Plausibilidade e coerência</dt>
<dd>Compatibilidade com o conhecimento biológico e com a história natural da doença.</dd>
</dl>
<h4>O essencial</h4>
<p>Em 1965, Austin Bradford Hill propôs <strong>nove pontos de vista</strong> para julgar se uma associação observada é causal, no auge do debate sobre tabaco e câncer de pulmão: <strong>força</strong> da associação, <strong>consistência</strong> (reprodução em diferentes populações e desenhos), <strong>especificidade</strong> (uma causa, um efeito), <strong>temporalidade</strong>, <strong>gradiente biológico</strong> (dose-resposta), <strong>plausibilidade</strong>, <strong>coerência</strong>, <strong>experimento</strong> (a remoção da exposição reduz o efeito) e <strong>analogia</strong>. Ele mesmo escreveu que nenhum deles era prova e que não se deveria exigir todos.</p>
<p>A leitura moderna, de Rothman e outros, hierarquiza: a <strong>temporalidade é o único critério logicamente necessário</strong>, porque uma causa não pode vir depois do efeito. Os demais são apoios de peso variável. A <strong>especificidade</strong> é o mais fraco: o tabaco causa dezenas de doenças e nem por isso deixa de causá-las. A <strong>força</strong> ajuda, mas associações fracas podem ser causais (tabagismo passivo) e fortes podem ser confusão. A <strong>plausibilidade</strong> depende do conhecimento da época. O <strong>gradiente</strong> pode existir com confusão que também tem gradiente. A consistência falha quando o mesmo viés se repete.</p>
<p>A inferência causal contemporânea usa modelos explícitos: o <strong>modelo de causas suficientes e componentes</strong> de Rothman (a "torta causal", em que a maioria das causas não é necessária nem suficiente), os <strong>diagramas causais</strong> (DAGs) para identificar confusão, e o <strong>contrafactual</strong> (o que teria acontecido sem a exposição), que fundamenta o ensaio randomizado. Os critérios de Hill continuam úteis como roteiro de raciocínio, não como lista de verificação.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Diante de um novo fator de risco publicado, pergunte primeiro se a exposição foi medida antes do desfecho. Se um estudo transversal mede os dois ao mesmo tempo, o mais elegante dos critérios de Hill não salva a inferência: sem temporalidade não há causa.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Nove pontos de vista: força, consistência, especificidade, temporalidade, gradiente, plausibilidade, coerência, experimento, analogia.</li>
<li>Temporalidade é o único indispensável; especificidade é o mais fraco.</li>
<li>Nenhum é prova; Hill não pedia todos.</li>
<li>Modelos modernos: causas componentes, diagramas causais, contrafactual.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual critério de Hill é logicamente necessário e por quê? <details><summary>Resposta</summary>A temporalidade, porque a causa deve preceder o efeito.</details></li>
<li>Por que a especificidade é considerada o critério mais fraco? <details><summary>Resposta</summary>Porque uma causa pode produzir muitos efeitos e um efeito ter muitas causas, sem que isso negue a causalidade.</details></li>
</ol>
`,
"susp2026#88": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir pré-diabetes pelos critérios de glicemia, TOTG e hemoglobina glicada.</li>
<li>Reconhecer o risco cardiovascular e a neuropatia já presentes no pré-diabetes.</li>
<li>Indicar a prevenção do diabetes: estilo de vida e metformina em quem se beneficia.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Pré-diabetes</dt>
<dd>Jejum de 100 a 125 mg/dL, 2 horas do TOTG de 140 a 199, ou hemoglobina glicada de 5,7 a 6,4%.</dd>
<dt>Glicemia de jejum alterada</dt>
<dd>Jejum entre 100 e 125 mg/dL; marca resistência hepática à insulina.</dd>
<dt>Tolerância diminuída à glicose</dt>
<dd>2 horas do TOTG entre 140 e 199; marca resistência muscular e maior risco cardiovascular.</dd>
<dt>Neuropatia de fibras finas</dt>
<dd>Lesão precoce das fibras sensitivas finas, com dor e parestesias, já no pré-diabetes.</dd>
</dl>
<h4>O essencial</h4>
<p>O pré-diabetes é a faixa entre o normal e o diabetes, e não é uma condição benigna de espera. Metade dos pacientes progride para diabetes em 10 anos sem intervenção, e o dano já começa antes: a hiperglicemia intermitente e a resistência à insulina, com a dislipidemia, a hipertensão e a obesidade que a acompanham, elevam o <strong>risco cardiovascular</strong> (infarto, AVC, morte cardiovascular), e a <strong>neuropatia periférica</strong>, sobretudo de fibras finas, pode surgir com parestesias e dor nos pés antes que a glicemia cruze 126.</p>
<p>As complicações microvasculares clássicas seguem outra lógica: a <strong>retinopatia</strong> e a <strong>nefropatia</strong> com albuminúria franca dependem de anos de hiperglicemia sustentada e são marcas do diabetes estabelecido; no pré-diabetes são raras. Por isso o rastreamento oftalmológico anual e a albuminúria começam ao diagnóstico do diabetes, enquanto o risco cardiovascular e os pés merecem atenção desde o pré-diabetes.</p>
<p>A intervenção que muda a história é o <strong>estilo de vida</strong>: perda de 5 a 7% do peso, 150 minutos semanais de atividade moderada e dieta com menos ultraprocessados reduzem a progressão em quase 60%. A <strong>metformina</strong> é considerada em quem tem maior risco: IMC de 35 ou mais, menos de 60 anos, diabetes gestacional prévio ou glicada em ascensão. Trata-se também a pressão e o colesterol pelo risco global, e rastreia-se o diabetes anualmente.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>No paciente com pré-diabetes que quer "fazer tudo certo", a consulta rende mais nos pés e no coração do que nos olhos: examine a sensibilidade com monofilamento, estratifique o risco cardiovascular, trate a pressão e o LDL, e prescreva a caminhada com dia e hora.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Pré-diabetes: jejum 100 a 125, TOTG 140 a 199, glicada 5,7 a 6,4%.</li>
<li>Já eleva o risco cardiovascular e pode causar neuropatia periférica.</li>
<li>Retinopatia e nefropatia são do diabetes estabelecido.</li>
<li>Estilo de vida reduz a progressão em quase 60%; metformina nos de maior risco.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que complicações já podem estar presentes no pré-diabetes? <details><summary>Resposta</summary>Doença cardiovascular e neuropatia periférica, sobretudo de fibras finas.</details></li>
<li>Quando considerar metformina no pré-diabetes? <details><summary>Resposta</summary>IMC de 35 ou mais, idade abaixo de 60, diabetes gestacional prévio ou glicada em ascensão.</details></li>
</ol>
`,
"susp2026#89": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Escolher o teste estatístico pelo tipo de variável, número de grupos e pareamento.</li>
<li>Situar o teste t de Student para amostras independentes nesse mapa.</li>
<li>Reconhecer quando usar as versões não paramétricas.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Variável contínua</dt>
<dd>Medida numérica (dor em escala, pressão, peso); comparada por médias ou medianas.</dd>
<dt>Amostras independentes</dt>
<dd>Grupos formados por indivíduos diferentes, sem pareamento; cada um contribui com uma medida.</dd>
<dt>Amostras pareadas</dt>
<dd>Mesmos indivíduos medidos duas vezes, ou pares emparelhados; compara-se a diferença dentro do par.</dd>
<dt>Teste não paramétrico</dt>
<dd>Usa postos em vez de valores; não exige distribuição normal (Mann-Whitney, Wilcoxon, Kruskal-Wallis).</dd>
</dl>
<h4>O essencial</h4>
<p>A escolha do teste responde a três perguntas. <strong>Que tipo de variável é o desfecho?</strong> Contínua (média), ordinal (postos) ou categórica (proporções). <strong>Quantos grupos?</strong> Dois ou mais. <strong>Os grupos são independentes ou pareados?</strong> Com as respostas, o mapa é direto.</p>
<p>Desfecho <strong>contínuo com distribuição aproximadamente normal</strong>: dois grupos independentes, <strong>teste t para amostras independentes</strong>; dois grupos pareados (antes e depois no mesmo paciente), <strong>teste t pareado</strong>; três ou mais grupos, <strong>ANOVA</strong> (com medidas repetidas se pareados). Desfecho contínuo <strong>sem normalidade</strong> ou ordinal: <strong>Mann-Whitney</strong> para dois independentes, <strong>Wilcoxon</strong> para pareados, <strong>Kruskal-Wallis</strong> para três ou mais. Desfecho <strong>categórico</strong>: <strong>qui-quadrado</strong> (ou exato de Fisher com frequências pequenas) para grupos independentes, <strong>McNemar</strong> para pareados. Correlação entre duas contínuas: Pearson (normal) ou Spearman (postos); regressão para ajustar por covariáveis.</p>
<p>Uma escala de dor pontuada de 0 a 10, em dois grupos de pacientes diferentes (cirurgia versus fisioterapia), sem pareamento, com amostras razoáveis e distribuição aceitável, é o caso típico do <strong>t para amostras independentes</strong>; se a distribuição for muito assimétrica ou a amostra pequena, o Mann-Whitney é a versão robusta. O erro comum é usar o t pareado em grupos independentes, ou o qui-quadrado numa variável contínua transformada em categorias sem motivo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de olhar o p, olhe o desenho: quem são os grupos, o que foi medido e como. Dois grupos de pessoas diferentes com uma medida numérica cada um é o t independente; a mesma pessoa medida antes e depois é o t pareado. A prova gosta de trocar esses dois.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Três perguntas: tipo de variável, número de grupos, independentes ou pareados.</li>
<li>Contínua normal: t independente, t pareado, ANOVA.</li>
<li>Sem normalidade ou ordinal: Mann-Whitney, Wilcoxon, Kruskal-Wallis.</li>
<li>Categórica: qui-quadrado ou Fisher; McNemar se pareado.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Dor em escala numérica, dois grupos de pacientes diferentes, sem pareamento: qual teste? <details><summary>Resposta</summary>Teste t para amostras independentes; Mann-Whitney se a distribuição não for normal.</details></li>
<li>Qual é a versão não paramétrica do t pareado? <details><summary>Resposta</summary>O teste de Wilcoxon para amostras pareadas.</details></li>
</ol>
`,
"susp2026#90": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a aterosclerose subclínica como marcador de alto risco cardiovascular.</li>
<li>Definir a meta de LDL para cada categoria de risco.</li>
<li>Hierarquizar as condutas: estatina de alta intensidade antes de qualquer outra medida.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Aterosclerose subclínica</dt>
<dd>Placa carotídea, escore de cálcio coronariano elevado ou índice tornozelo-braço baixo em assintomático.</dd>
<dt>Estatina de alta intensidade</dt>
<dd>Rosuvastatina 20 a 40 mg ou atorvastatina 40 a 80 mg, que reduzem o LDL em 50% ou mais.</dd>
<dt>Meta de LDL</dt>
<dd>Abaixo de 70 mg/dL no alto risco e abaixo de 50 no muito alto risco, pela diretriz brasileira.</dd>
<dt>Ezetimiba</dt>
<dd>Inibidor da absorção intestinal de colesterol, associado quando a estatina máxima não atinge a meta.</dd>
</dl>
<h4>O essencial</h4>
<p>A estratificação de risco cardiovascular começa pelas calculadoras, mas a diretriz brasileira de dislipidemias reclassifica por achados que dispensam cálculo: a presença de <strong>aterosclerose subclínica</strong>, como <strong>placa na carótida</strong> ao ultrassom, escore de cálcio acima de 100 ou índice tornozelo-braço abaixo de 0,9, coloca o paciente em <strong>alto risco</strong>, no mesmo patamar do diabético com fatores de risco ou do portador de doença renal crônica. Doença aterosclerótica clínica (infarto, AVC, revascularização) é <strong>muito alto risco</strong>.</p>
<p>A categoria define a <strong>meta de LDL</strong>: abaixo de 130 no baixo risco, 100 no intermediário, <strong>70 no alto</strong> e <strong>50 no muito alto</strong>. Para chegar lá, a primeira e mais importante conduta é a <strong>estatina de alta intensidade</strong>, titulada até a dose máxima tolerada (rosuvastatina 40 mg, atorvastatina 80 mg); se a meta não vem, associa-se <strong>ezetimiba</strong>, e depois um inibidor de PCSK9. A estatina reduz eventos de forma proporcional à queda do LDL, e é o tratamento com maior evidência de benefício na prevenção primária de alto risco.</p>
<p>As outras medidas seguem na fila, cada uma com seu lugar: controle da pressão com meta abaixo de 130/80, tratamento do pré-diabetes com estilo de vida (e metformina se indicada), cessação do tabagismo, atividade física. O ácido acetilsalicílico na prevenção primária perdeu espaço: só em casos selecionados de alto risco com baixo risco de sangramento, por decisão compartilhada. Trocar anti-hipertensivo ou iniciar aspirina antes de otimizar a estatina inverte a hierarquia.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Placa carotídea no laudo do ultrassom que ninguém leu é um paciente de alto risco sem tratamento. Quando ela aparece, a pergunta não é "que exame mais", é "qual estatina, em que dose, com que meta". Rosuvastatina 40 e LDL abaixo de 70 são a resposta padrão.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Placa carotídea, cálcio acima de 100 ou ITB abaixo de 0,9: alto risco.</li>
<li>Metas de LDL: 130, 100, 70 e 50 conforme o risco.</li>
<li>Estatina de alta intensidade até a dose máxima; depois ezetimiba; depois PCSK9.</li>
<li>Aspirina em prevenção primária só em casos selecionados.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que a placa carotídea muda na estratificação? <details><summary>Resposta</summary>Reclassifica o paciente como alto risco, com meta de LDL abaixo de 70 mg/dL.</details></li>
<li>Qual é a sequência para atingir a meta de LDL? <details><summary>Resposta</summary>Estatina de alta intensidade na dose máxima tolerada, depois ezetimiba, depois inibidor de PCSK9.</details></li>
</ol>
`,
"susp2026#92": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir os quatro níveis de prevenção com exemplos.</li>
<li>Explicar a prevenção quaternária como proteção contra a medicalização.</li>
<li>Classificar intervenções de um plano de saúde ocupacional por nível.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Prevenção primária</dt>
<dd>Evitar que a doença apareça: promoção da saúde e proteção específica.</dd>
<dt>Prevenção secundária</dt>
<dd>Detectar e tratar cedo: rastreamento e diagnóstico precoce.</dd>
<dt>Prevenção terciária</dt>
<dd>Reduzir dano e reabilitar em quem já tem a doença.</dd>
<dt>Prevenção quaternária</dt>
<dd>Proteger o paciente de intervenções médicas excessivas ou desnecessárias.</dd>
</dl>
<h4>O essencial</h4>
<p>Leavell e Clark organizaram a prevenção segundo a história natural da doença: a <strong>primária</strong> age antes da doença, por <strong>promoção da saúde</strong> (educação, condições de trabalho, lazer) e <strong>proteção específica</strong> (vacinas, equipamentos de proteção, flúor); a <strong>secundária</strong> age na fase pré-clínica ou inicial, por <strong>diagnóstico precoce</strong> e rastreamento, e por tratamento que limita o dano; a <strong>terciária</strong> age na doença estabelecida, com <strong>reabilitação</strong> e prevenção de complicações.</p>
<p>Marc Jamoulle acrescentou a <strong>prevenção quaternária</strong>, definida pelo cruzamento entre o que o médico vê (doença ou não) e o que o paciente sente (doente ou não): quando o paciente se sente doente e o médico não encontra doença, o risco é o <strong>excesso de investigação, diagnóstico e tratamento</strong>. A prevenção quaternária é o conjunto de ações para <strong>proteger as pessoas de intervenções médicas que provavelmente causam mais dano que benefício</strong>: evitar rastreamentos sem evidência, rótulos diagnósticos apressados, polifarmácia, e criar mecanismos que revisem a prescrição.</p>
<p>Num plano contra o burnout de residentes, os níveis se distribuem: reorganizar escalas, limitar horas e criar espaços de apoio é primária; rastrear sintomas com escala validada é secundária; tratar e reabilitar o residente adoecido, com afastamento e retorno gradual, é terciária; e uma política de <strong>revisão por pares das prescrições de psicofármacos</strong>, que exija olhar as causas organizacionais antes de medicar o sofrimento, é quaternária, porque impede que um problema institucional seja convertido em diagnóstico individual e receita.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Toda vez que a resposta ao sofrimento de um grupo é uma prescrição individual, pergunte se o problema não está na organização. A prevenção quaternária começa com a pergunta "essa intervenção vai ajudar ou só vai medicalizar?" antes de assinar.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Primária: promoção e proteção específica antes da doença.</li>
<li>Secundária: rastreamento e diagnóstico precoce; terciária: reabilitação.</li>
<li>Quaternária: proteger de intervenções desnecessárias e da medicalização.</li>
<li>Revisar prescrições e olhar causas organizacionais é quaternária.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Rastrear burnout com uma escala validada é que nível de prevenção? <details><summary>Resposta</summary>Secundária: detecção precoce em quem ainda não tem o quadro estabelecido.</details></li>
<li>O que define a prevenção quaternária? <details><summary>Resposta</summary>Ações que protegem as pessoas de intervenções médicas excessivas ou desnecessárias, evitando a medicalização.</details></li>
</ol>
`,
"susp2026#93": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar o princípio do rastreamento pelo órgão presente na pessoa trans.</li>
<li>Conhecer as recomendações de rastreamento de mama, colo e próstata conforme a anatomia e a hormonização.</li>
<li>Oferecer cuidado inclusivo sem omitir exames por causa da identidade de gênero.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Homem transgênero</dt>
<dd>Pessoa designada mulher ao nascer que se identifica como homem; pode ou não usar testosterona e fazer cirurgias.</dd>
<dt>Rastreamento pelo órgão</dt>
<dd>Se o órgão existe, rastreia-se pelas regras da população geral para aquele órgão.</dd>
<dt>Mastectomia masculinizadora</dt>
<dd>Retira a maior parte do tecido mamário, mas não todo; o rastreamento vira exame clínico.</dd>
<dt>Hormonização</dt>
<dd>Uso de testosterona ou estrogênio para afirmação de gênero; altera alguns riscos, mas não elimina órgãos.</dd>
</dl>
<h4>O essencial</h4>
<p>A saúde da pessoa trans na atenção primária segue um princípio simples que os guias da WPATH e do Ministério da Saúde repetem: <strong>rastreia-se o que existe</strong>. A identidade de gênero define o nome, o pronome e o respeito no atendimento; a <strong>anatomia presente</strong> e a <strong>história de hormonização</strong> definem os exames. A omissão de rastreamentos por constrangimento, do paciente ou do profissional, é uma das principais causas de diagnóstico tardio nessa população.</p>
<p>Um <strong>homem trans</strong> que não fez mastectomia tem mamas e faz <strong>mamografia</strong> pelas regras da mulher cisgênero: no Brasil, bienal dos 50 aos 69 anos; a testosterona não elimina o risco. Se fez mastectomia masculinizadora, resta tecido residual, e o rastreamento passa a ser o exame clínico. Se tem colo do útero, faz <strong>citologia</strong> dos 25 aos 64 anos, com o cuidado de avisar o laboratório sobre a atrofia induzida pela testosterona, que aumenta resultados insatisfatórios; a autocoleta de HPV é uma boa opção. A <strong>mulher trans</strong> em estrogênio há anos desenvolve tecido mamário e é candidata a mamografia a partir dos 50, com decisão compartilhada; mantém a próstata, e o rastreamento segue a discussão do homem cisgênero.</p>
<p>O tabagismo, a depressão e o uso de testosterona somam riscos cardiovasculares que merecem atenção; a densidade óssea entra em quem fez gonadectomia sem reposição adequada. Pressão, lipídios, glicemia e vacinas seguem as regras gerais.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Pergunte, com naturalidade, quais órgãos a pessoa tem e que cirurgias fez, explique que os exames dependem disso e registre no prontuário. Um homem trans de 51 anos com mamas faz mamografia; não pedir é negligência disfarçada de respeito.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Identidade define o tratamento respeitoso; anatomia define os rastreamentos.</li>
<li>Homem trans com mamas: mamografia dos 50 aos 69; com colo: citologia dos 25 aos 64.</li>
<li>Mulher trans em estrogênio: mamografia a partir dos 50; próstata mantida.</li>
<li>Riscos cardiovasculares e ósseos conforme hormonização e cirurgias.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Homem trans de 51 anos em testosterona, sem mastectomia: que rastreamento está indicado? <details><summary>Resposta</summary>Mamografia, pelas regras da população com mamas; a testosterona não elimina o risco.</details></li>
<li>Que cuidado ter na citologia do colo em homem trans? <details><summary>Resposta</summary>Avisar o laboratório sobre a atrofia por testosterona e considerar a autocoleta de HPV.</details></li>
</ol>
`,
"susp2026#94": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Avaliar o idoso que caiu: risco, causas e o que fazer primeiro.</li>
<li>Indicar o exercício multicomponente como a intervenção de maior evidência.</li>
<li>Reconhecer as armadilhas: metas pressóricas agressivas, hipoglicemiantes, vacinas vivas.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Idoso caidor</dt>
<dd>Quem caiu no último ano, ou tem medo de cair, ou instabilidade na marcha e no equilíbrio.</dd>
<dt>Exercício multicomponente</dt>
<dd>Programa que combina força, equilíbrio, marcha e flexibilidade, 2 a 3 vezes por semana.</dd>
<dt>Timed Up and Go</dt>
<dd>Teste de levantar, andar 3 metros e voltar; mais de 12 segundos indica risco de queda.</dd>
<dt>Hipotensão ortostática</dt>
<dd>Queda de 20 mmHg na sistólica ou 10 na diastólica ao levantar; causa comum de queda medicamentosa.</dd>
</dl>
<h4>O essencial</h4>
<p>Cair depois dos 65 anos não é acidente banal: um terço dos idosos cai a cada ano, e a queda é a principal causa de fratura, internação e perda de autonomia. As diretrizes mundiais de 2022 mandam perguntar sobre quedas em toda consulta e, diante de uma queda, avaliar o <strong>risco</strong> (marcha e equilíbrio com o Timed Up and Go, força, visão, cognição, pés e calçados, ambiente doméstico), as <strong>causas</strong> (hipotensão ortostática, arritmia, hipoglicemia, polifarmácia, sobretudo psicotrópicos e hipotensores) e a <strong>osteoporose</strong> (densitometria e vitamina D em quem fraturou ou tem risco).</p>
<p>A intervenção com <strong>maior evidência</strong> para reduzir quedas é o <strong>exercício multicomponente</strong>: fortalecimento muscular, treino de equilíbrio e de marcha, progressivo, ao menos 2 a 3 vezes por semana, por meses, em grupo ou domiciliar (tai chi é uma forma validada). A ele se somam a revisão de medicamentos com desprescrição do que causa tontura, a correção da visão, a adaptação do ambiente (barras, iluminação, tapetes), o tratamento da osteoporose e a vitamina D em quem tem deficiência.</p>
<p>As <strong>armadilhas</strong> no idoso caidor com hipertensão e diabetes: perseguir pressão abaixo de 130 num idoso frágil aumenta hipotensão e quedas; a meta é individualizada, e a ortostática se mede sempre. Trocar uma sulfonilureia por outra mantém o risco de hipoglicemia; o caminho é reduzir a intensidade do controle glicêmico ou trocar de classe. A vacina de herpes-zóster indicada é a <strong>recombinante</strong>; a atenuada é contraindicada em imunossuprimidos e foi substituída. A osteoartrite de joelhos não é motivo para repouso: é motivo para fortalecer.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Depois de uma queda, meça a pressão deitado e em pé, faça o Timed Up and Go no corredor, revise a lista de remédios linha por linha e encaminhe para o grupo de exercício antes de qualquer outra prescrição. Esse é o pacote que reduz a próxima queda.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Toda consulta: perguntar sobre quedas; após queda: marcha, equilíbrio, causas, osteoporose.</li>
<li>Exercício multicomponente (força, equilíbrio, marcha) é a intervenção de maior evidência.</li>
<li>Revisar medicamentos, visão, ambiente, vitamina D, osteoporose.</li>
<li>Evitar metas pressóricas agressivas, sulfonilureias e vacina viva de zóster.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual intervenção tem a melhor evidência para prevenir quedas? <details><summary>Resposta</summary>O exercício multicomponente com fortalecimento, equilíbrio e treino de marcha, 2 a 3 vezes por semana.</details></li>
<li>Que exame simples avalia o risco de queda no consultório? <details><summary>Resposta</summary>O Timed Up and Go; mais de 12 segundos indica risco, junto da medida da pressão em ortostase.</details></li>
</ol>
`,
"susp2026#95": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Classificar a pressão arterial pela diretriz brasileira de 2020.</li>
<li>Explicar por que a intensidade da prevenção depende do risco cardiovascular global.</li>
<li>Prescrever as medidas não farmacológicas com metas concretas.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Pré-hipertensão</dt>
<dd>Sistólica de 130 a 139 ou diastólica de 85 a 89 mmHg, pela diretriz brasileira de 2020.</dd>
<dt>Risco cardiovascular global</dt>
<dd>Probabilidade de evento em 10 anos, estimada por escores que somam idade, sexo, pressão, lipídios, tabaco e diabetes.</dd>
<dt>Estratificação</dt>
<dd>Classificação em baixo, intermediário ou alto risco, que define metas e intensidade do tratamento.</dd>
<dt>Atividade física recomendada</dt>
<dd>150 a 300 minutos semanais de intensidade moderada, ou 75 a 150 de vigorosa, mais fortalecimento.</dd>
</dl>
<h4>O essencial</h4>
<p>A diretriz brasileira de 2020 classifica: <strong>ótima</strong> abaixo de 120/80, <strong>normal</strong> de 120 a 129 e 80 a 84, <strong>pré-hipertensão</strong> de 130 a 139 e 85 a 89, e hipertensão a partir de 140/90, em estágios 1, 2 e 3. A pré-hipertensão não é doença, mas prediz hipertensão e já se associa a mais eventos, sobretudo quando vem com outros fatores: sedentarismo, dieta de ultraprocessados, sobrepeso, tabagismo, história familiar, dislipidemia e glicemia alterada.</p>
<p>O que decide a <strong>intensidade</strong> da intervenção não é um número isolado, é o <strong>risco cardiovascular global</strong>: um homem de 48 anos com pré-hipertensão, sedentário, com dislipidemia e pai infartado precoce pode ter risco intermediário ou alto, e é isso que define se a meta é só estilo de vida ou se entram estatina e, no futuro, anti-hipertensivo. A estratificação usa ferramentas validadas (escore de risco global, calculadoras da diretriz de prevenção) e é o primeiro passo, antes de qualquer prescrição.</p>
<p>Na pré-hipertensão, o tratamento é <strong>não farmacológico</strong> e tem metas mensuráveis: perda de peso (cada 1 kg reduz cerca de 1 mmHg), dieta DASH ou mediterrânea com menos de 2 g de sódio, <strong>150 minutos</strong> semanais de atividade moderada (a OMS recomenda 150 a 300, mais fortalecimento duas vezes por semana), redução do álcool, cessação do tabagismo e sono adequado. Anti-hipertensivo entra na pré-hipertensão só em alto risco com doença cardiovascular ou diabetes com lesão de órgão-alvo, por decisão individualizada. Reavaliação em meses, com medida residencial ou monitorização ambulatorial para afastar a hipertensão do avental branco.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de dizer "é só pré-hipertensão", some os fatores e calcule o risco: o número da pressão é um, o paciente é outro. E prescreva o exercício como remédio: tipo, dias, minutos e data de retorno, senão a recomendação vira conselho.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Pré-hipertensão: 130 a 139 por 85 a 89 mmHg; hipertensão a partir de 140/90.</li>
<li>A estratificação do risco global decide a intensidade da prevenção.</li>
<li>Não farmacológico com metas: peso, dieta com pouco sódio, 150 minutos semanais, álcool, tabaco.</li>
<li>Anti-hipertensivo na pré-hipertensão só em alto risco selecionado.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Como se classifica uma pressão de 134 por 86 mmHg? <details><summary>Resposta</summary>Pré-hipertensão pela diretriz brasileira de 2020.</details></li>
<li>O que define a intensidade da intervenção preventiva? <details><summary>Resposta</summary>O risco cardiovascular global estratificado por ferramenta validada, não o valor isolado da pressão.</details></li>
</ol>
`,
"susp2026#96": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Hierarquizar o tratamento da obesidade: dieta, exercício, fármaco, cirurgia.</li>
<li>Prescrever o exercício com metas de minutos para perda e manutenção do peso.</li>
<li>Conhecer os critérios para fármaco e para cirurgia bariátrica.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Obesidade</dt>
<dd>IMC de 30 ou mais; graus I (30 a 34,9), II (35 a 39,9) e III (40 ou mais).</dd>
<dt>Perda clinicamente significativa</dt>
<dd>5 a 10% do peso em 6 meses, suficiente para melhorar pressão, glicemia e lipídios.</dd>
<dt>Manutenção do peso</dt>
<dd>Fase em que o exercício é decisivo: 200 a 300 minutos semanais evitam a recuperação.</dd>
<dt>Farmacoterapia da obesidade</dt>
<dd>IMC de 30 ou mais, ou 27 com comorbidade, após falha das medidas de estilo de vida.</dd>
</dl>
<h4>O essencial</h4>
<p>A obesidade é doença crônica, recidivante, e o tratamento é escalonado. A base é a <strong>mudança de estilo de vida</strong>: dieta com déficit de 500 a 1.000 kcal/dia, ajustada à preferência e à cultura do paciente, e <strong>atividade física</strong>. O exercício, sozinho, emagrece pouco; seu papel maior é <strong>preservar massa magra</strong>, melhorar o risco cardiometabólico e, sobretudo, <strong>manter o peso perdido</strong>. A recomendação para perda é de ao menos 150 minutos semanais de intensidade moderada; para evitar a recuperação do peso, a meta sobe para <strong>200 a 300 minutos</strong> semanais, com fortalecimento duas vezes por semana.</p>
<p>Quem já ajustou a dieta, mas ainda não tem exercício estruturado, tem um degrau claro a subir antes de qualquer remédio: um <strong>programa de exercício de intensidade moderada com meta de minutos</strong>, progressivo, acompanhado. A terapia comportamental (automonitorização, metas, resolução de problemas) potencializa os dois.</p>
<p>A <strong>farmacoterapia</strong> entra com IMC de 30 ou mais, ou de 27 com comorbidade, após 3 a 6 meses de estilo de vida sem resposta, e sempre junto dele: agonistas do GLP-1 (liraglutida, semaglutida), tirzepatida, orlistate, sibutramina com restrições. A <strong>cirurgia bariátrica</strong> tem critérios: IMC de 40 ou mais, ou de 35 com comorbidade, após falha de tratamento clínico documentado por 2 anos, com avaliação multiprofissional (o SUS segue esses critérios; as sociedades já discutem IMC de 30 a 35 com diabetes não controlado). Nenhum degrau elimina o anterior: dieta e exercício continuam depois do fármaco e depois da cirurgia.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Um paciente que "já faz dieta" e recupera peso a cada tentativa não precisa de mais dieta: precisa de exercício com dias, minutos e progressão, e de um retorno em que a pergunta seja "quantos minutos você fez esta semana?". O fármaco vem depois, e a cirurgia tem critérios.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Escalonado: dieta, exercício, fármaco, cirurgia; cada degrau soma ao anterior.</li>
<li>Exercício: 150 minutos para perder, 200 a 300 para manter; preserva massa magra.</li>
<li>Fármaco: IMC 30, ou 27 com comorbidade, após falha do estilo de vida.</li>
<li>Cirurgia: IMC 40, ou 35 com comorbidade, após 2 anos de tratamento clínico.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a meta de exercício para evitar a recuperação do peso? <details><summary>Resposta</summary>De 200 a 300 minutos semanais de intensidade moderada.</details></li>
<li>Quais são os critérios de IMC para a cirurgia bariátrica? <details><summary>Resposta</summary>IMC de 40 ou mais, ou de 35 com comorbidade, após falha do tratamento clínico.</details></li>
</ol>
`,
"susp2026#97": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a síndrome colinérgica da intoxicação por organofosforados e carbamatos.</li>
<li>Explicar o mecanismo: inibição da acetilcolinesterase.</li>
<li>Conhecer o exame confirmatório e os antídotos.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Acetilcolinesterase</dt>
<dd>Enzima que degrada a acetilcolina na sinapse; inibida pelos organofosforados (irreversível) e carbamatos (reversível).</dd>
<dt>Síndrome muscarínica</dt>
<dd>Sialorreia, lacrimejamento, broncorreia, broncoespasmo, bradicardia, miose, vômitos, diarreia, incontinência.</dd>
<dt>Síndrome nicotínica</dt>
<dd>Fasciculações, fraqueza, paralisia respiratória, taquicardia e hipertensão.</dd>
<dt>Pralidoxima</dt>
<dd>Oxima que reativa a enzima antes do envelhecimento da ligação; usada com a atropina.</dd>
</dl>
<h4>O essencial</h4>
<p>Organofosforados e carbamatos <strong>inibem a acetilcolinesterase</strong>, e a acetilcolina se acumula em todas as sinapses colinérgicas. O resultado é a <strong>síndrome colinérgica</strong>: efeitos <strong>muscarínicos</strong> (secreções em excesso, broncoespasmo, bradicardia, miose, cólicas, diarreia), <strong>nicotínicos</strong> (fasciculações, fraqueza, paralisia da musculatura respiratória) e <strong>centrais</strong> (agitação, confusão, convulsões, coma). A morte vem por insuficiência respiratória: broncorreia, broncoespasmo e paralisia somados. A exposição ocupacional crônica, com equipamento de proteção inadequado, produz quadros subagudos com sintomas inespecíficos, e a intoxicação aguda pode seguir uma aplicação sem proteção.</p>
<p>O diagnóstico é clínico, e a confirmação laboratorial é a <strong>dosagem da atividade da colinesterase</strong>, plasmática (butirilcolinesterase, mais sensível e precoce) e <strong>eritrocitária</strong> (mais específica da exposição), que se espera <strong>reduzida</strong>; a comparação com um valor basal do trabalhador, quando existe, é ideal.</p>
<p>O tratamento começa pela <strong>descontaminação</strong> (retirar roupas, lavar a pele) com proteção da equipe, e pelo <strong>suporte respiratório</strong>. Os antídotos: <strong>atropina</strong>, em doses repetidas e crescentes até secar as secreções brônquicas (a meta é a ausculta limpa, não a midríase nem a frequência cardíaca), e <strong>pralidoxima</strong>, que reativa a enzima nos organofosforados se dada antes do envelhecimento da ligação, nas primeiras horas. Benzodiazepínico para convulsões. Nos carbamatos a ligação é reversível e o quadro é mais curto; a oxima é discutível. A intoxicação por agrotóxico é de notificação compulsória, e o caso ocupacional aciona a vigilância em saúde do trabalhador.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Trabalhador rural com sudorese, sialorreia, miose e sibilos depois de aplicar veneno: atropine até o pulmão ficar limpo, sem medo da dose, e peça a colinesterase eritrocitária para documentar.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Inibição da acetilcolinesterase: acúmulo de acetilcolina, síndrome colinérgica.</li>
<li>Muscarínico (secreções, miose, bradicardia), nicotínico (fasciculações, paralisia), central (convulsões).</li>
<li>Exame: atividade da colinesterase plasmática e eritrocitária reduzida.</li>
<li>Descontaminação, suporte, atropina até secar secreções, pralidoxima precoce; notificar.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a meta clínica da atropinização? <details><summary>Resposta</summary>Secar as secreções brônquicas e limpar a ausculta, não a midríase nem a frequência cardíaca.</details></li>
<li>Que exame confirma a intoxicação por organofosforados? <details><summary>Resposta</summary>A dosagem da atividade da acetilcolinesterase plasmática e eritrocitária, reduzida.</details></li>
</ol>
`,
"susp2026#98": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Separar o eixo dispneia do eixo exacerbação no manejo do DPOC pelo GOLD.</li>
<li>Indicar a reabilitação pulmonar no paciente sintomático apesar da broncodilatação.</li>
<li>Reconhecer o que não fazer: corticoide inalatório e oxigênio fora de critério.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Grupos A, B e E do GOLD</dt>
<dd>A: poucos sintomas e poucas exacerbações; B: muitos sintomas; E: exacerbações frequentes ou graves.</dd>
<dt>Broncodilatação dupla</dt>
<dd>LABA mais LAMA em um único dispositivo, base do tratamento do sintomático.</dd>
<dt>Reabilitação pulmonar</dt>
<dd>Programa de exercício supervisionado, educação e suporte por 6 a 12 semanas, que melhora dispneia e capacidade.</dd>
<dt>Oxigenoterapia domiciliar</dt>
<dd>Indicada com PaO2 de 55 ou menos, ou 59 com cor pulmonale ou policitemia, em repouso.</dd>
</dl>
<h4>O essencial</h4>
<p>O GOLD organiza o DPOC em dois eixos independentes: o dos <strong>sintomas</strong> (dispneia pelo mMRC ou CAT) e o das <strong>exacerbações</strong>. O tratamento inicial do grupo B (sintomático, sem exacerbações) é a <strong>broncodilatação dupla</strong> com LABA e LAMA; o do grupo E (exacerbador) é a dupla, com corticoide inalatório associado se a eosinofilia é de 300 ou mais. O corticoide inalatório não trata dispneia e aumenta pneumonia; fora do critério de exacerbações com eosinófilos, não se prescreve.</p>
<p>Quando o paciente já usa a dupla broncodilatação com técnica correta e <strong>continua dispneico</strong>, sem exacerbações, o próximo passo do eixo dispneia não é mais fármaco: é a <strong>reabilitação pulmonar</strong>. Ela combina exercício aeróbico e de força supervisionado, educação, fisioterapia respiratória, nutrição e apoio psicossocial por 6 a 12 semanas, e é a intervenção que mais melhora a dispneia, a tolerância ao exercício e a qualidade de vida no DPOC sintomático, além de reduzir internações após exacerbação. Está indicada no grupo B e no E, e é subutilizada.</p>
<p>Completam o cuidado a <strong>cessação do tabagismo</strong> (a única medida que muda a queda da função), as vacinas (influenza, pneumocócica, covid-19, dTpa, zóster), a avaliação de comorbidades (cardiopatia, osteoporose, depressão) e a <strong>oxigenoterapia domiciliar</strong> só com hipoxemia grave em repouso confirmada por gasometria, não pela dispneia. Teofilina e mucolíticos têm papel marginal.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de trocar o inalador do paciente que "não melhora", veja-o usar o dispositivo e conte as exacerbações do ano. Sem exacerbações e com técnica boa, a receita seguinte é o encaminhamento à reabilitação pulmonar, e a caminhada diária enquanto a vaga não sai.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Dois eixos: sintomas (B) e exacerbações (E); LABA mais LAMA é a base.</li>
<li>Corticoide inalatório só no exacerbador com eosinófilos de 300 ou mais.</li>
<li>Dispneia persistente com broncodilatação otimizada: reabilitação pulmonar.</li>
<li>Tabagismo, vacinas, comorbidades; oxigênio só com PaO2 de 55 ou menos.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Paciente em LABA mais LAMA, com técnica correta, sem exacerbações e ainda dispneico: qual é o próximo passo? <details><summary>Resposta</summary>Encaminhar à reabilitação pulmonar.</details></li>
<li>Quando o corticoide inalatório entra no DPOC? <details><summary>Resposta</summary>No exacerbador frequente ou grave, sobretudo com eosinófilos de 300 ou mais; nunca para dispneia isolada.</details></li>
</ol>
`,
"susp2026#99": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conduzir a profilaxia pós-exposição à hepatite A dentro da janela de 14 dias.</li>
<li>Decidir entre vacina e imunoglobulina pelo perfil do contato.</li>
<li>Identificar quem já é imune e não precisa de profilaxia.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Janela de 14 dias</dt>
<dd>Prazo após a exposição em que vacina ou imunoglobulina ainda previnem a doença.</dd>
<dt>Vacina inativada da hepatite A</dt>
<dd>Profilaxia de escolha para contatos saudáveis de 1 a 40 anos; uma dose protege.</dd>
<dt>Imunoglobulina humana</dt>
<dd>Anticorpos passivos para menores de 1 ano, imunodeprimidos, hepatopatas e maiores de 40 quando a vacina não é possível.</dd>
<dt>Imunidade prévia</dt>
<dd>Anti-HAV IgG positivo, doença documentada ou vacinação completa: sem necessidade de profilaxia.</dd>
</dl>
<h4>O essencial</h4>
<p>A hepatite A tem transmissão fecal-oral e incubação de 15 a 50 dias, e os contatos de um caso (domiciliares, sexuais, de creche, de surto alimentar) podem ser protegidos se a profilaxia for feita em até <strong>14 dias</strong> da última exposição. Depois disso, não há benefício, apenas vigilância clínica.</p>
<p>Dentro da janela, a escolha segue o perfil. A <strong>vacina</strong> inativada, em dose única, é a profilaxia de escolha para contatos <strong>saudáveis de 1 a 40 anos</strong>: é tão eficaz quanto a imunoglobulina, protege por muito mais tempo e é mais fácil de obter; recomenda-se completar o esquema com a segunda dose 6 meses depois. A <strong>imunoglobulina humana</strong> (0,1 mL/kg intramuscular) é reservada aos <strong>menores de 1 ano</strong>, aos <strong>imunodeprimidos</strong>, aos <strong>hepatopatas crônicos</strong> e aos <strong>maiores de 40 anos</strong>, sobretudo acima de 60, com comorbidades ou quando a vacina não estiver disponível; nesses, a vacina pode ser dada junto, em local diferente. Gestantes podem receber a vacina.</p>
<p>Antes de qualquer conduta, pergunta-se se o contato já é <strong>imune</strong>: doença documentada, vacinação completa ou <strong>anti-HAV IgG positivo</strong> dispensam a profilaxia. Não se deve, porém, atrasar a profilaxia à espera da sorologia quando o prazo está no fim: em adultos jovens nascidos em áreas endêmicas a chance de imunidade é alta, e a sorologia pode ser colhida no mesmo dia da vacina. Profissionais de saúde e de creche expostos seguem a mesma regra dos demais contatos, e a notificação do caso índice é obrigatória.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Contato de hepatite A que chega no 10º dia recebe a vacina naquela consulta, e a sorologia sai junto, não antes. Se a IgG vier positiva, nada se perdeu; se vier negativa, a proteção já começou. O que não pode acontecer é passar o 14º dia esperando resultado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Profilaxia em até 14 dias da exposição.</li>
<li>Vacina para saudáveis de 1 a 40 anos; imunoglobulina para menores de 1 ano, imunodeprimidos, hepatopatas e maiores de 40 selecionados.</li>
<li>Imunes (doença, vacina, IgG positivo) não precisam de profilaxia.</li>
<li>Não atrasar a vacina esperando sorologia.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Mulher saudável de 32 anos exposta há 5 dias: qual é a profilaxia? <details><summary>Resposta</summary>Uma dose da vacina inativada contra hepatite A, com sorologia no mesmo dia se desejado.</details></li>
<li>Quem recebe imunoglobulina em vez de vacina? <details><summary>Resposta</summary>Menores de 1 ano, imunodeprimidos, hepatopatas crônicos e maiores de 40 anos selecionados.</details></li>
</ol>
`,
"susp2026#100": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer os sistemas de informação do SUS e a pergunta que cada um responde.</li>
<li>Escolher a fonte certa para auditar o pré-natal, o nascimento, a internação e o óbito.</li>
<li>Reconhecer os limites de cada sistema.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>e-SUS APS</dt>
<dd>Prontuário eletrônico e coleta de dados da atenção primária; registra cada consulta, exame e procedimento da equipe.</dd>
<dt>SINAN</dt>
<dd>Sistema de agravos de notificação: doenças e agravos de notificação compulsória, como sífilis gestacional e congênita.</dd>
<dt>SINASC e SIM</dt>
<dd>Nascidos vivos (declaração de nascido vivo) e mortalidade (declaração de óbito).</dd>
<dt>SIH-SUS</dt>
<dd>Internações hospitalares pagas pelo SUS, via AIH: diagnóstico, procedimento, tempo de internação.</dd>
</dl>
<h4>O essencial</h4>
<p>Cada sistema de informação do SUS nasce de um documento e responde a uma pergunta. O <strong>SINASC</strong> nasce da declaração de nascido vivo: quantos nasceram, onde, com que peso, idade gestacional, tipo de parto, escolaridade da mãe e número de consultas de pré-natal declarado. O <strong>SIM</strong> nasce da declaração de óbito: quem morreu, de quê, onde; é a base dos indicadores de mortalidade infantil e materna. O <strong>SINAN</strong> nasce da ficha de notificação: doenças e agravos de notificação compulsória, com investigação; é onde a sífilis na gestante e a sífilis congênita são registradas. O <strong>SIH-SUS</strong> nasce da autorização de internação hospitalar: internações, diagnósticos, procedimentos e custos. O <strong>SIA-SUS</strong> registra a produção ambulatorial. O <strong>SI-PNI</strong>, as vacinas. O <strong>CNES</strong>, os estabelecimentos e profissionais.</p>
<p>O <strong>e-SUS APS</strong> é diferente: é o <strong>prontuário eletrônico</strong> da atenção primária, com o registro de cada atendimento, exame solicitado e resultado, procedimento e visita. Por isso é a fonte para <strong>auditar a qualidade e a frequência do pré-natal</strong> de uma gestante ou de uma equipe: quantas consultas, em que idade gestacional começou, quais exames foram pedidos e quando, se a sífilis foi tratada e o parceiro também. O SINASC diz o número de consultas declarado no nascimento, mas não o conteúdo; o SINAN diz que a sífilis foi notificada, mas não o cuidado prestado. O SisPreNatal foi absorvido pelo e-SUS APS.</p>
<p>Uma sífilis congênita evitável costuma revelar falhas em vários sistemas ao mesmo tempo: pré-natal tardio e incompleto (e-SUS APS), sífilis gestacional não notificada (SINAN), parto registrado sem tratamento adequado (SINASC), internação do recém-nascido (SIH) e, no pior caso, óbito (SIM). A avaliação de caso cruza todos.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando a vigilância pergunta "o que aconteceu no pré-natal dessa gestante", a resposta está no prontuário eletrônico da unidade, não na declaração de nascido vivo. Registre bem o que faz: o e-SUS APS é a memória do cuidado e a prova de que ele existiu.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>SINASC: nascidos vivos; SIM: óbitos; SINAN: agravos notificáveis; SIH: internações; SIA: ambulatório.</li>
<li>e-SUS APS: prontuário da atenção primária; audita o conteúdo do pré-natal.</li>
<li>SINASC informa o número de consultas declarado, não a qualidade.</li>
<li>Sífilis gestacional e congênita vão ao SINAN.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual sistema permite auditar quais exames foram pedidos no pré-natal e quando? <details><summary>Resposta</summary>O e-SUS APS, prontuário eletrônico da atenção primária.</details></li>
<li>Onde a sífilis congênita é registrada? <details><summary>Resposta</summary>No SINAN, por notificação compulsória com investigação.</details></li>
</ol>
`,
"susp2021#10": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir acidente de trabalho grave e sua notificação compulsória ao SINAN.</li>
<li>Saber que a notificação independe de vínculo empregatício.</li>
<li>Distinguir a notificação em saúde (SINAN) da comunicação previdenciária (CAT).</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Acidente de trabalho grave</dt>
<dd>Acidente com morte, mutilação, internação ou envolvendo menor de 18 anos, relacionado ao trabalho.</dd>
<dt>Notificação compulsória</dt>
<dd>Obrigação legal de comunicar agravos da lista nacional à vigilância, pelo SINAN.</dd>
<dt>CAT</dt>
<dd>Comunicação de Acidente de Trabalho à Previdência, para benefícios do segurado; não substitui o SINAN.</dd>
<dt>Trabalhador informal</dt>
<dd>Quem trabalha sem carteira ou contrato; tem os mesmos direitos à atenção e à vigilância no SUS.</dd>
</dl>
<h4>O essencial</h4>
<p>A saúde do trabalhador é campo de atuação do SUS pela Lei 8.080, e abrange <strong>todos os que trabalham</strong>, formais ou informais, urbanos ou rurais, com ou sem carteira. A vigilância se alimenta da notificação, e a <strong>Lista Nacional de Notificação Compulsória</strong> inclui o <strong>acidente de trabalho grave</strong> (com morte, mutilação, internação ou em menor de 18 anos), o acidente com exposição a material biológico, as intoxicações exógenas, as doenças relacionadas ao trabalho (LER/DORT, pneumoconioses, dermatoses, perda auditiva, câncer e transtornos mentais ocupacionais) e outros agravos.</p>
<p>Um ferimento por arma de fogo sofrido por um segurança durante o serviço é acidente de trabalho típico; se ele foi internado ou operado, é <strong>grave</strong> e vai ao <strong>SINAN</strong> pela ficha própria, preenchida pelo serviço de saúde que atendeu. O <strong>vínculo empregatício não é condição</strong>: o trabalhador que fazia um bico é notificado do mesmo modo, porque a notificação serve à vigilância (conhecer onde e como as pessoas se ferem trabalhando) e não a um benefício. Além disso, a violência sofrida no trabalho também é registrada como violência interpessoal.</p>
<p>A <strong>CAT</strong> é outro instrumento, previdenciário: comunica o acidente ao INSS para garantir auxílio e estabilidade ao segurado, e é emitida pelo empregador ou, na falta dele, pelo médico, pelo sindicato ou pelo próprio trabalhador. Ela vale para quem tem cobertura previdenciária, e sua ausência nunca dispensa o SINAN. O CEREST (Centro de Referência em Saúde do Trabalhador) apoia a investigação e a intervenção nos ambientes de trabalho.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Todo paciente que dá entrada ferido deve ouvir a pergunta "isso aconteceu no trabalho?". A resposta positiva gera a ficha do SINAN na hora, independentemente de carteira assinada; a CAT vem depois, para quem tem direito. Deixar de notificar o informal apaga da vigilância justamente quem mais se acidenta.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Acidente de trabalho grave (morte, mutilação, internação, menor de 18) é de notificação compulsória ao SINAN.</li>
<li>Notifica-se com ou sem vínculo empregatício.</li>
<li>CAT é previdenciária e não substitui o SINAN.</li>
<li>Saúde do trabalhador no SUS abrange formais e informais; CEREST apoia.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um trabalhador informal ferido no serviço e internado deve ser notificado? <details><summary>Resposta</summary>Sim, ao SINAN como acidente de trabalho grave; o vínculo não é condição.</details></li>
<li>Qual é a diferença entre SINAN e CAT? <details><summary>Resposta</summary>O SINAN é a notificação à vigilância em saúde; a CAT é a comunicação à Previdência para benefícios do segurado.</details></li>
</ol>
`,
"susp2021#11": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer os sinais de violência contra a pessoa idosa.</li>
<li>Saber que a suspeita, e não só a confirmação, é de notificação compulsória.</li>
<li>Conhecer os fluxos: SINAN, Conselho do Idoso, Ministério Público e rede de proteção.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Violência interpessoal</dt>
<dd>Física, psicológica, sexual, negligência, abandono ou financeira, praticada por outra pessoa.</dd>
<dt>Ficha de notificação de violência (VIVA)</dt>
<dd>Instrumento do SINAN para violência interpessoal e autoprovocada, preenchido na suspeita.</dd>
<dt>Estatuto da Pessoa Idosa</dt>
<dd>Lei 10.741/2003; o artigo 19 obriga profissionais de saúde a comunicar casos suspeitos ou confirmados.</dd>
<dt>Negligência</dt>
<dd>Omissão de cuidados básicos (alimentação, higiene, medicação) por quem tem o dever de prestá-los.</dd>
</dl>
<h4>O essencial</h4>
<p>A violência contra a pessoa idosa é frequente, silenciosa e quase sempre praticada por familiares e cuidadores. Os sinais: lesões em estágios diferentes de cicatrização ou incompatíveis com a explicação, demora em procurar atendimento, desnutrição e desidratação sem causa, úlceras de pressão negligenciadas, medicação mal administrada, medo ou apatia na presença do cuidador, isolamento, retirada de dinheiro e bens. Idosos dependentes, com demência ou Parkinson avançado, que moram com familiares sobrecarregados, são os de maior risco.</p>
<p>A regra é que a <strong>suspeita basta</strong>. A Lista Nacional de Notificação Compulsória inclui a violência interpessoal e autoprovocada, e a ficha do SINAN (VIVA) é preenchida pelo serviço de saúde diante de <strong>caso suspeito ou confirmado</strong>; a notificação é sigilosa, não é denúncia policial e não exige prova. Para a pessoa idosa há reforço legal: o <strong>Estatuto da Pessoa Idosa</strong> obriga o profissional de saúde a comunicar a suspeita à autoridade policial, ao Ministério Público, ao Conselho do Idoso ou ao Conselho Municipal, e a omissão é infração. A notificação ao SINAN e a comunicação ao órgão de proteção são atos distintos e complementares.</p>
<p>Notificar não encerra o cuidado: a equipe avalia o risco imediato, protege a vítima (internação social ou acolhimento se necessário), envolve a assistência social, o CRAS ou CREAS, orienta e apoia o cuidador sobrecarregado, e mantém o vínculo com a família, porque na maioria dos casos o idoso continuará morando com quem o agride.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando a suspeita surge, converse com o idoso a sós, com perguntas abertas e sem julgamento, documente as lesões e preencha a ficha antes de a família ir embora. Notificar na suspeita protege o paciente e protege você; esperar a certeza é esperar a próxima lesão.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Sinais: lesões inexplicadas, desnutrição, negligência, medo do cuidador, perdas financeiras.</li>
<li>Suspeita basta: notificar ao SINAN como violência interpessoal (ficha VIVA).</li>
<li>Estatuto da Pessoa Idosa obriga a comunicar a suspeita aos órgãos de proteção.</li>
<li>Depois: proteger, acionar a rede, apoiar o cuidador, manter o vínculo.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>É preciso confirmar os maus-tratos antes de notificar? <details><summary>Resposta</summary>Não; a suspeita é suficiente para a notificação ao SINAN e para a comunicação aos órgãos de proteção.</details></li>
<li>Que lei obriga o profissional de saúde a comunicar a violência contra o idoso? <details><summary>Resposta</summary>O Estatuto da Pessoa Idosa, Lei 10.741/2003, no artigo 19.</details></li>
</ol>
`,
"susp2021#13": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir acolhimento como postura e prática de escuta, não como triagem.</li>
<li>Aplicar o acolhimento em saúde mental na atenção primária.</li>
<li>Diferenciar acolhimento de classificação de risco e de encaminhamento.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Acolhimento</dt>
<dd>Escuta qualificada da demanda, com responsabilização e resposta, em qualquer momento do encontro.</dd>
<dt>Classificação de risco</dt>
<dd>Ferramenta que ordena o atendimento pela gravidade; complementa o acolhimento, não o substitui.</dd>
<dt>Vínculo</dt>
<dd>Relação de confiança e continuidade entre usuário e equipe, base do cuidado longitudinal.</dd>
<dt>Corresponsabilização</dt>
<dd>A equipe assume o cuidado do problema junto com o usuário, em vez de transferi-lo.</dd>
</dl>
<h4>O essencial</h4>
<p>Na Política Nacional de Humanização, o <strong>acolhimento</strong> é uma diretriz que atravessa todo o serviço: receber cada pessoa com <strong>escuta qualificada</strong>, reconhecer sua demanda, avaliar riscos e vulnerabilidades e dar uma resposta, responsabilizando-se pelo seguimento. Não é uma sala, um profissional nem uma etapa de triagem; é uma postura de toda a equipe, em todos os encontros. A classificação de risco é uma ferramenta que pode fazer parte dele, mas acolher não é classificar.</p>
<p>Em <strong>saúde mental</strong> o acolhimento ganha centralidade porque o sofrimento psíquico costuma chegar disfarçado de queixas físicas, de "nervoso", de insônia, de pedidos de remédio ou de atestado. O Caderno de Atenção Básica 34 descreve o acolhimento como <strong>um espaço de escuta ao usuário e à família</strong>, em que se sintam seguros para expressar aflições, dúvidas e angústias, sabendo que a equipe vai ouvir e se responsabilizar. Esse espaço, por si, já é terapêutico: reduz a ansiedade, cria vínculo e muitas vezes dispensa o encaminhamento.</p>
<p>O que o acolhimento <strong>não é</strong>: triagem para decidir quem "é da saúde mental" e vai ao CAPS; consulta rápida para fechar diagnóstico psiquiátrico; porta de encaminhamento automático ao especialista; distribuição de senhas. A atenção primária é responsável pelo cuidado dos transtornos mentais comuns e do uso de substâncias em seu território, com apoio matricial da eMulti e do CAPS, e encaminha só os casos graves ou de risco, mantendo-se corresponsável.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando alguém chega "só para pegar o remédio para os nervos", a pergunta "como você está?" com a porta fechada e cinco minutos de silêncio vale mais que a renovação da receita. Acolher é ouvir antes de decidir para onde a pessoa vai, e quase sempre ela fica.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Acolhimento: escuta qualificada, avaliação de risco e responsabilização, por toda a equipe, em todo encontro.</li>
<li>Em saúde mental: espaço de escuta ao usuário e à família, terapêutico por si.</li>
<li>Não é triagem, diagnóstico rápido nem encaminhamento automático.</li>
<li>Atenção primária cuida dos transtornos comuns com apoio matricial; CAPS para os graves.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que diferencia acolhimento de triagem? <details><summary>Resposta</summary>Triagem ordena e distribui; acolhimento escuta, avalia e se responsabiliza pela resposta, com vínculo.</details></li>
<li>Quem cuida dos transtornos mentais comuns no território? <details><summary>Resposta</summary>A equipe de atenção primária, com apoio matricial da eMulti e do CAPS.</details></li>
</ol>
`,
"susp2021#15": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar os princípios e diretrizes da Política Nacional de Atenção Integral à Saúde da Mulher.</li>
<li>Explicar o conceito de gênero como construção social adotado pela política.</li>
<li>Distinguir a PNAISM do PAISM que a antecedeu.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PNAISM</dt>
<dd>Política Nacional de Atenção Integral à Saúde da Mulher, de 2004, do Ministério da Saúde.</dd>
<dt>PAISM</dt>
<dd>Programa de Assistência Integral à Saúde da Mulher, de 1984, que rompeu com o foco materno-infantil.</dd>
<dt>Gênero</dt>
<dd>Construção social sobreposta a um corpo sexuado; organiza papéis, poder e desigualdades.</dd>
<dt>Integralidade</dt>
<dd>Atenção a todas as necessidades da mulher em todos os ciclos de vida, não só na reprodução.</dd>
</dl>
<h4>O essencial</h4>
<p>Até os anos 1980 a saúde da mulher no Brasil era saúde materno-infantil: a mulher importava enquanto gestante e mãe. O <strong>PAISM</strong>, em 1984, influenciado pelo movimento feminista e pela reforma sanitária, propôs a <strong>integralidade</strong>: atenção em todas as fases da vida, incluindo planejamento reprodutivo, climatério, câncer, DST e saúde mental, com a mulher como sujeito e não como meio. Foi um marco, mas de implantação parcial.</p>
<p>A <strong>PNAISM</strong>, de 2004, retomou e ampliou o PAISM como política de Estado, com princípios explícitos: <strong>humanização</strong> e qualidade da atenção; <strong>integralidade</strong> e promoção da saúde; <strong>gênero como construção social sobreposta a um corpo sexuado</strong>, isto é, papéis, expectativas e desigualdades atribuídos socialmente ao sexo biológico, que produzem adoecimento e desigualdade de acesso; <strong>transversalidade</strong> (a perspectiva de gênero deve atravessar todas as áreas, não ficar num programa à parte); e atenção às mulheres em suas diversidades: negras, indígenas, rurais, lésbicas, em situação de prisão, com deficiência, em situação de violência. A política incorporou a atenção humanizada ao abortamento previsto em lei e às mulheres em situação de abortamento, a saúde sexual e reprodutiva com direitos, e a redução da mortalidade materna como prioridade.</p>
<p>Os direitos sexuais e reprodutivos, a autonomia sobre o corpo e a participação social das mulheres na formulação das políticas são a base ética da PNAISM; a diferença para o PAISM não é o conteúdo assistencial, é o estatuto de política nacional com marco conceitual de gênero e diversidade.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ler a PNAISM na prática é perguntar, em cada consulta, o que a organização social do gênero está fazendo com a saúde daquela mulher: sobrecarga de cuidado, violência, renda menor, menos tempo para si. A integralidade começa por enxergar isso, não só o útero.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>PAISM (1984): integralidade contra o modelo materno-infantil; PNAISM (2004): política nacional.</li>
<li>Princípios: humanização, integralidade, gênero como construção social, transversalidade, diversidade.</li>
<li>Gênero: construção social sobreposta a um corpo sexuado.</li>
<li>Direitos sexuais e reprodutivos e redução da mortalidade materna como eixos.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Como a PNAISM define gênero? <details><summary>Resposta</summary>Como uma construção social sobreposta a um corpo sexuado.</details></li>
<li>O que o PAISM rompeu em 1984? <details><summary>Resposta</summary>O modelo materno-infantil, propondo integralidade da atenção à mulher em todos os ciclos de vida.</details></li>
</ol>
`,
"susp2021#18": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever a natureza deliberativa e permanente dos conselhos de saúde.</li>
<li>Reproduzir a composição paritária: 50% usuários, 25% trabalhadores, 25% gestores e prestadores.</li>
<li>Distinguir conselhos de conferências de saúde.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Conselho de saúde</dt>
<dd>Órgão colegiado, permanente e deliberativo do SUS em cada esfera de governo.</dd>
<dt>Conferência de saúde</dt>
<dd>Reunião a cada 4 anos para avaliar a situação e propor diretrizes; propositiva, não deliberativa.</dd>
<dt>Paridade</dt>
<dd>Usuários com metade dos assentos; a outra metade dividida entre trabalhadores, gestores e prestadores.</dd>
<dt>Controle social</dt>
<dd>Participação da sociedade na formulação, na execução e na fiscalização das políticas de saúde.</dd>
</dl>
<h4>O essencial</h4>
<p>A participação da comunidade é diretriz constitucional do SUS, regulamentada pela <strong>Lei 8.142/1990</strong>, que cria duas instâncias colegiadas em cada esfera: a <strong>conferência de saúde</strong>, convocada a cada 4 anos (ou extraordinariamente), que avalia a situação de saúde e <strong>propõe diretrizes</strong> para a política; e o <strong>conselho de saúde</strong>, órgão <strong>permanente e deliberativo</strong>, que atua na formulação de estratégias e no <strong>controle da execução</strong> da política, inclusive nos aspectos econômicos e financeiros, e cujas decisões são homologadas pelo chefe do poder executivo.</p>
<p>A <strong>composição</strong> é paritária por força da lei e da Resolução CNS 453/2012: <strong>50% de usuários</strong>, <strong>25% de trabalhadores de saúde</strong> e <strong>25% de gestores e prestadores de serviço</strong>, com representação de governo, prestadores públicos e privados. O presidente é eleito entre os conselheiros (não é o secretário por direito), as reuniões são públicas e mensais, e o conselho aprova o plano de saúde, o relatório de gestão e acompanha o Fundo de Saúde. Conselho e conferência existem nas três esferas: nacional, estadual e municipal, e a existência do conselho é condição para o repasse de recursos federais.</p>
<p>O <strong>caráter deliberativo</strong> significa que o conselho decide, não apenas opina: suas resoluções vinculam o gestor, que pode devolvê-las com justificativa, mas não ignorá-las. Isso o distingue de comissões consultivas e do papel das conferências. O Decreto 9.759/2019, que extinguiu colegiados federais, preservou os conselhos criados por lei, como o Conselho Nacional de Saúde.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>O plano municipal que muda a cobertura da sua unidade passou pelo conselho; a ata está pública. Conhecer o conselheiro usuário do território é uma forma prática de levar problemas de acesso e de estrutura para onde eles são decididos.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Lei 8.142/1990: conferência (a cada 4 anos, propõe) e conselho (permanente, delibera).</li>
<li>Paridade: 50% usuários, 25% trabalhadores, 25% gestores e prestadores.</li>
<li>Conselho aprova plano e relatório de gestão e controla a execução, inclusive financeira.</li>
<li>Presidente eleito entre os conselheiros; reuniões públicas.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a composição de um conselho de saúde? <details><summary>Resposta</summary>Metade de usuários, um quarto de trabalhadores de saúde e um quarto de gestores e prestadores.</details></li>
<li>O que distingue o conselho da conferência? <details><summary>Resposta</summary>O conselho é permanente e deliberativo; a conferência é periódica (4 anos) e propositiva.</details></li>
</ol>
`,
"susp2021#19": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir incidência, prevalência, letalidade e mortalidade.</li>
<li>Aplicar a relação prevalência igual a incidência vezes duração.</li>
<li>Prever o efeito de uma doença curta e letal sobre cada medida.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Incidência</dt>
<dd>Casos novos por população em risco num período; mede o risco de adoecer.</dd>
<dt>Prevalência</dt>
<dd>Casos existentes (novos e antigos) por população num momento; mede a carga da doença.</dd>
<dt>Letalidade</dt>
<dd>Óbitos pela doença entre os doentes; mede a gravidade.</dd>
<dt>Mortalidade</dt>
<dd>Óbitos pela doença na população total; mede o impacto na comunidade.</dd>
</dl>
<h4>O essencial</h4>
<p>As medidas de frequência respondem a perguntas diferentes. A <strong>incidência</strong> conta quem <strong>adoeceu</strong> no período entre os que podiam adoecer: é a medida do risco e a que estudos de coorte estimam. A <strong>prevalência</strong> conta quem <strong>está doente</strong> num instante, casos novos e antigos, entre toda a população: é a medida da carga, útil para planejar serviços, e a que os estudos transversais estimam. A <strong>letalidade</strong> divide os óbitos pela doença pelo número de doentes: diz quão grave é a doença para quem a tem. A <strong>mortalidade</strong> divide os mesmos óbitos pela população inteira: diz quanto a doença pesa na comunidade.</p>
<p>A ligação entre as duas primeiras é a <strong>duração</strong>: em estado estável, <strong>prevalência ≈ incidência × duração média</strong>. Doenças crônicas de longa duração acumulam casos e têm prevalência alta mesmo com incidência modesta (diabetes, hipertensão). Doenças <strong>agudas e curtas</strong>, que curam ou matam em pouco tempo, têm prevalência baixa por mais alta que seja a incidência, porque os casos não se acumulam. Uma doença aguda que <strong>mata rápido, com alta letalidade</strong>, tem duração mínima e, portanto, <strong>baixa prevalência</strong>; sua letalidade é alta por definição, e sua mortalidade depende da incidência (pode ser alta ou baixa).</p>
<p>O mesmo raciocínio explica paradoxos: um tratamento que prolonga a vida sem curar <strong>aumenta</strong> a prevalência; uma vacina que reduz a incidência reduz a prevalência; melhorar a sobrevida reduz a letalidade e pode não mudar a incidência. Confundir letalidade com mortalidade é o erro clássico: raiva tem letalidade próxima de 100% e mortalidade baixíssima.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao ler "a prevalência de X aumentou", pergunte se as pessoas estão adoecendo mais ou vivendo mais com a doença. Para a gestão, prevalência dimensiona leitos e insumos; para a prevenção, incidência diz se a intervenção funcionou.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Incidência: casos novos, risco; prevalência: casos existentes, carga.</li>
<li>Prevalência ≈ incidência × duração.</li>
<li>Doença aguda, curta e letal: prevalência baixa, letalidade alta.</li>
<li>Letalidade é entre os doentes; mortalidade é na população.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que uma doença que mata em dias tem prevalência baixa? <details><summary>Resposta</summary>Porque a prevalência depende da duração, e os casos não se acumulam quando a doença termina rápido.</details></li>
<li>Um tratamento que prolonga a vida sem curar faz o quê com a prevalência? <details><summary>Resposta</summary>Aumenta, porque aumenta a duração média da doença.</details></li>
</ol>
`,
"unesp2026#81": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Situar a política de saúde brasileira de 1974 a 1979 no contexto da ditadura.</li>
<li>Explicar a criação do Inamps e a dicotomia entre saúde pública e assistência médica previdenciária.</li>
<li>Reconhecer os embriões da reforma sanitária no fim da década.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Inamps</dt>
<dd>Instituto Nacional de Assistência Médica da Previdência Social, criado em 1977, que comprava serviços médicos para os segurados.</dd>
<dt>SINPAS</dt>
<dd>Sistema Nacional de Previdência e Assistência Social (Lei 6.439/1977), que reorganizou a previdência em institutos.</dd>
<dt>Modelo médico-assistencial privatista</dt>
<dd>Financiamento público da previdência comprando serviços do setor privado, com foco curativo e hospitalar.</dd>
<dt>Dicotomia saúde pública/assistência médica</dt>
<dd>Ministério da Saúde cuidava das campanhas e da prevenção; a Previdência, da assistência aos segurados.</dd>
</dl>
<h4>O essencial</h4>
<p>Durante a ditadura civil-militar, a saúde se organizou em dois mundos. O <strong>Ministério da Saúde</strong>, com orçamento pequeno, cuidava da <strong>saúde pública</strong>: campanhas, vigilância, endemias. A <strong>Previdência Social</strong>, financiada pelas contribuições de empregados e empregadores, cuidava da <strong>assistência médica</strong> dos trabalhadores formais, comprando serviços de hospitais e clínicas privadas. Quem não tinha carteira dependia da filantropia. É a <strong>dicotomia</strong> que a reforma sanitária vai denunciar.</p>
<p>O período de <strong>1974 a 1979</strong> (governo Geisel e início de Figueiredo) consolidou esse modelo em plena crise do "milagre": o II PND ampliou gastos sociais; a Lei 6.229/1975 desenhou um Sistema Nacional de Saúde que reafirmou a divisão; e a Lei 6.439/1977 criou o <strong>SINPAS</strong>, separando a previdência em institutos, entre eles o <strong>Inamps</strong>, responsável pela assistência médica dos segurados, que se tornou o maior comprador de serviços privados do país e o símbolo do modelo médico-assistencial privatista, com fraudes e desigualdade de acesso.</p>
<p>No mesmo período nasceram os contrapontos: o movimento sanitário nos departamentos de medicina preventiva, o CEBES (1976) e a ABRASCO (1979), o Programa de Interiorização das Ações de Saúde e Saneamento (PIASS, 1976), primeira expansão da atenção primária ao Nordeste, e o I Simpósio de Política Nacional de Saúde na Câmara (1979), em que a proposta de um sistema único e universal foi apresentada. A crise financeira da previdência nos anos 1980 abriu caminho às AIS, ao SUDS e, em 1988, ao SUS, quando o Inamps foi absorvido e depois extinto (1993).</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um paciente idoso conta que "antigamente só quem tinha carteira era atendido", ele está descrevendo o Inamps. O SUS universal é a resposta histórica a essa lembrança.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Anos 1970: saúde pública no Ministério, assistência médica na Previdência, para segurados.</li>
<li>1975: Sistema Nacional de Saúde; 1977: SINPAS e criação do Inamps.</li>
<li>Inamps comprava serviços privados: modelo médico-assistencial privatista.</li>
<li>Contrapontos: CEBES, ABRASCO, PIASS; caminho para AIS, SUDS e SUS.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que o Inamps fazia e a quem servia? <details><summary>Resposta</summary>Prestava e comprava assistência médica para os segurados da Previdência, sobretudo do setor privado.</details></li>
<li>Qual era a dicotomia da política de saúde dos anos 1970? <details><summary>Resposta</summary>Saúde pública a cargo do Ministério da Saúde e assistência médica a cargo da Previdência, restrita aos contribuintes.</details></li>
</ol>
`,
"unesp2026#82": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Distinguir o texto do artigo 196 da Constituição do artigo 2º da Lei 8.080.</li>
<li>Explicar como a Lei Orgânica desdobra o direito constitucional à saúde.</li>
<li>Conhecer a estrutura das leis 8.080 e 8.142 de 1990.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Artigo 196 da Constituição</dt>
<dd>"A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas…"</dd>
<dt>Lei 8.080/1990</dt>
<dd>Lei Orgânica da Saúde: organização, direção, competências e funcionamento do SUS.</dd>
<dt>Lei 8.142/1990</dt>
<dd>Participação da comunidade (conferências e conselhos) e transferências de recursos.</dd>
<dt>Determinantes e condicionantes</dt>
<dd>Alimentação, moradia, saneamento, trabalho, renda, educação, lazer, acesso a bens e serviços (art. 3º da 8.080).</dd>
</dl>
<h4>O essencial</h4>
<p>A Constituição de 1988 inaugura o direito à saúde no <strong>artigo 196</strong>: "A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação".</p>
<p>A <strong>Lei 8.080</strong>, de 19 de setembro de 1990, regulamenta esse direito. Seu <strong>artigo 2º</strong> repete o princípio e o desdobra: "A saúde é um direito fundamental do ser humano, devendo o Estado prover as condições indispensáveis ao seu pleno exercício. § 1º <strong>O dever do Estado de garantir a saúde consiste na formulação e execução de políticas econômicas e sociais que visem à redução de riscos de doenças e de outros agravos</strong> e no estabelecimento de condições que assegurem acesso universal e igualitário às ações e aos serviços para a sua promoção, proteção e recuperação. § 2º O dever do Estado não exclui o das pessoas, da família, das empresas e da sociedade". O artigo 3º lista os determinantes e condicionantes; o 4º define o SUS; o 5º, seus objetivos; o 7º, os princípios e diretrizes (universalidade, integralidade, equidade, descentralização, participação, entre outros).</p>
<p>A confusão de prova está no vocabulário parecido: a Constituição fala em "políticas sociais e econômicas que visem à redução do risco de doença"; a Lei 8.080 fala em "formulação e execução de políticas econômicas e sociais que visem à redução de riscos de doenças", com a expressão "o dever do Estado de garantir a saúde consiste", que só existe na lei. A Lei 8.142 completa o marco com conselhos, conferências e repasse de recursos.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um paciente diz que a saúde é "dever do Estado", ele cita a Constituição; quando um gestor fala que o dever "consiste na formulação e execução de políticas", ele cita a Lei 8.080.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Art. 196 da Constituição: saúde é direito de todos e dever do Estado.</li>
<li>Art. 2º da Lei 8.080: o dever consiste na formulação e execução de políticas econômicas e sociais.</li>
<li>Art. 3º: determinantes; art. 7º: princípios e diretrizes do SUS.</li>
<li>Lei 8.142: participação da comunidade e financiamento.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Onde está a frase "o dever do Estado de garantir a saúde consiste na formulação e execução de políticas econômicas e sociais"? <details><summary>Resposta</summary>No artigo 2º, parágrafo 1º, da Lei 8.080/1990.</details></li>
<li>O que a Lei 8.142 acrescentou? <details><summary>Resposta</summary>As conferências e os conselhos de saúde e as regras de transferência de recursos.</details></li>
</ol>
`,
"unesp2026#84": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Listar a composição mínima da equipe de Saúde da Família pela PNAB de 2017.</li>
<li>Distinguir os profissionais obrigatórios dos que podem ser vinculados.</li>
<li>Situar saúde bucal, endemias e eMulti em relação à equipe.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Equipe de Saúde da Família (eSF)</dt>
<dd>Médico, enfermeiro, auxiliar ou técnico de enfermagem e agentes comunitários de saúde: o núcleo.</dd>
<dt>Equipe de Saúde Bucal</dt>
<dd>Cirurgião-dentista e auxiliar ou técnico em saúde bucal, vinculados à eSF, em modalidade I ou II.</dd>
<dt>Agente de combate às endemias</dt>
<dd>Profissional da vigilância que pode integrar a equipe, com atuação no território.</dd>
<dt>Carga horária</dt>
<dd>40 horas semanais para todos, com a possibilidade de médicos em arranjos de 20, 30 ou 40 horas.</dd>
</dl>
<h4>O essencial</h4>
<p>A Política Nacional de Atenção Básica (Portaria 2.436/2017) define a <strong>composição mínima</strong> da equipe de Saúde da Família: <strong>médico</strong> (preferencialmente de família e comunidade), <strong>enfermeiro</strong> (preferencialmente especialista em saúde da família), <strong>auxiliar ou técnico de enfermagem</strong> e <strong>agentes comunitários de saúde</strong>, em número definido pela vulnerabilidade do território (até 750 pessoas por agente e cobertura de 100% em áreas de risco). Cada equipe é referência para 2.000 a 3.500 pessoas.</p>
<p>A esse núcleo <strong>podem ser vinculados</strong>: o <strong>cirurgião-dentista</strong> e o <strong>auxiliar ou técnico em saúde bucal</strong>, que compõem a equipe de Saúde Bucal (modalidade I: dentista e auxiliar ou técnico; modalidade II: dentista, técnico e auxiliar), e o <strong>agente de combate às endemias</strong>, integrando vigilância e atenção primária no território. As <strong>equipes multiprofissionais</strong> (eMulti, antigo NASF) não fazem parte da eSF: apoiam várias equipes por matriciamento. A equipe de Atenção Primária (eAP) é um arranjo alternativo, sem agentes obrigatórios, com médico e enfermeiro em cargas de 20 ou 30 horas.</p>
<p>A distinção importa nas provas e na gestão: sem médico, enfermeiro, técnico e agentes não há equipe de Saúde da Família nem financiamento dela; sem dentista ou agente de endemias, há. O agente comunitário deve morar na área, e a PNAB de 2017 permitiu que exerça atividades como aferir pressão e glicemia capilar, com supervisão.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Numa unidade nova, o primeiro mapa é o da equipe: quem é núcleo, quem é vinculado, quem é apoio. O médico que sabe que o agente de endemias pode ser da equipe e que a eMulti não é conserta fluxos errados de encaminhamento desde a primeira semana.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Mínimo: médico, enfermeiro, auxiliar ou técnico de enfermagem, agentes comunitários.</li>
<li>Vinculados: dentista, auxiliar ou técnico em saúde bucal, agente de combate às endemias.</li>
<li>eMulti apoia várias equipes; não compõe a eSF.</li>
<li>2.000 a 3.500 pessoas por equipe; até 750 por agente.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais profissionais são obrigatórios na equipe de Saúde da Família? <details><summary>Resposta</summary>Médico, enfermeiro, auxiliar ou técnico de enfermagem e agentes comunitários de saúde.</details></li>
<li>O dentista faz parte do núcleo mínimo? <details><summary>Resposta</summary>Não; compõe a equipe de Saúde Bucal, vinculada à eSF.</details></li>
</ol>
`,
"unesp2026#86": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer a lógica de distribuição e controle da declaração de óbito.</li>
<li>Saber quem pode receber o formulário e a quem é vedado.</li>
<li>Entender por que o médico, e não a funerária, atesta a morte.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Declaração de óbito (DO)</dt>
<dd>Documento padronizado em três vias, numerado, que atesta a morte e alimenta o SIM.</dd>
<dt>Portaria 116/2009</dt>
<dd>Regulamenta a coleta de dados, o fluxo e a distribuição da DO e da declaração de nascido vivo.</dd>
<dt>Serviço de verificação de óbito (SVO)</dt>
<dd>Esclarece causas de morte natural sem assistência ou sem diagnóstico definido.</dd>
<dt>Instituto médico-legal (IML)</dt>
<dd>Atesta as mortes por causas externas ou suspeitas.</dd>
</dl>
<h4>O essencial</h4>
<p>A declaração de óbito é ao mesmo tempo um documento legal (permite o sepultamento e o registro civil) e a fonte das estatísticas de mortalidade. Por isso o Ministério da Saúde controla sua impressão, numeração e <strong>distribuição</strong>: os formulários são fornecidos pelas secretarias de saúde <strong>a quem atesta a morte</strong>: estabelecimentos de saúde, institutos médico-legais, serviços de verificação de óbito, cartórios de registro civil (para as localidades sem médico) e médicos cadastrados. É <strong>vedada a distribuição a empresas funerárias</strong> e a qualquer estabelecimento que não faça o atestado, para impedir que o documento circule sem o ato médico que lhe dá sentido.</p>
<p>Quem preenche depende da morte. Morte <strong>natural com assistência</strong>: o médico que acompanhava, ou o do estabelecimento. Morte natural <strong>sem assistência</strong> ou sem causa definida: o <strong>SVO</strong> onde existe; sem SVO, o médico do serviço público ou, na falta, qualquer médico da localidade, e, sem médico, duas testemunhas no cartório. Morte por <strong>causa externa</strong> (acidente, violência, suspeita): o <strong>IML</strong>, sempre, mesmo que o óbito tenha ocorrido no hospital dias depois do evento. A DO tem três vias: a primeira vai à secretaria de saúde (SIM), a segunda ao cartório com a família, a terceira fica no estabelecimento.</p>
<p>O médico é obrigado a fornecer a DO quando é o responsável, não pode cobrar por ela nem assinar em branco, e deve preencher a causa básica com cuidado, pois é ela que a estatística usa. Dados incompletos ou "parada cardiorrespiratória" como causa desqualificam o registro.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Se uma funerária oferece "resolver a declaração", a resposta é não: o formulário só sai da secretaria para quem atesta, e assinar sem ter examinado o corpo ou conhecido o caso é infração ética e crime. Na dúvida sobre causa externa, o caminho é o IML.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>DO: documento legal e fonte do SIM; distribuição controlada pela secretaria de saúde.</li>
<li>Recebem: estabelecimentos de saúde, IML, SVO, cartórios sem médico, médicos cadastrados.</li>
<li>Vedado: empresas funerárias e quem não atesta.</li>
<li>Causa externa: IML; natural sem assistência: SVO; com assistência: o médico.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>A quem é vedada a distribuição da declaração de óbito? <details><summary>Resposta</summary>Às empresas funerárias e a qualquer estabelecimento que não atesta a morte.</details></li>
<li>Quem atesta uma morte por acidente ocorrida no hospital dias depois? <details><summary>Resposta</summary>O IML, porque a causa é externa.</details></li>
</ol>
`,
"unesp2026#89": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir infectividade, patogenicidade e virulência.</li>
<li>Diferenciar virulência (propriedade do agente) de letalidade (indicador).</li>
<li>Aplicar as definições a exemplos clássicos.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Infectividade</dt>
<dd>Capacidade de alojar-se e multiplicar-se no hospedeiro; medida pela taxa de ataque secundário.</dd>
<dt>Patogenicidade</dt>
<dd>Capacidade de produzir doença entre os infectados; proporção de infectados que adoecem.</dd>
<dt>Virulência</dt>
<dd>Capacidade de produzir casos graves ou fatais entre os doentes.</dd>
<dt>Imunogenicidade</dt>
<dd>Capacidade de induzir imunidade duradoura no hospedeiro.</dd>
</dl>
<h4>O essencial</h4>
<p>A epidemiologia das doenças infecciosas descreve o agente por propriedades que respondem a perguntas em cadeia. <strong>Infectividade</strong>: dado o contato, o agente consegue se instalar e multiplicar? O sarampo e a varicela têm infectividade altíssima; a hanseníase, baixa. <strong>Patogenicidade</strong>: dada a infecção, aparece doença? O sarampo adoece quase todos os infectados; a poliomielite paralisa uma minoria, e a maioria dos infectados é assintomática. <strong>Virulência</strong>: dada a doença, ela é grave? A raiva e o Ebola são virulentos; o resfriado comum, não. <strong>Imunogenicidade</strong>: a infecção deixa imunidade duradoura? Sarampo sim; gonorreia não. A <strong>dose infectante</strong> e o <strong>poder invasivo</strong> completam o retrato.</p>
<p>A virulência é uma <strong>propriedade</strong> do agente, que depende também do hospedeiro e das condições; a <strong>letalidade</strong> é o <strong>indicador</strong> que a mede em uma população: óbitos dividido por casos. Um mesmo agente pode ter letalidade diferente em lugares com acesso diferente a tratamento, sem que a virulência tenha mudado. Da mesma forma, a taxa de ataque secundário mede a infectividade e a proporção de doença clínica mede a patogenicidade.</p>
<p>Essas propriedades orientam o controle: alta infectividade pede vacinação em massa e altas coberturas (sarampo); baixa patogenicidade com alta infectividade cria muitos portadores assintomáticos que transmitem (pólio, hepatite A na criança); alta virulência com baixa infectividade permite isolamento eficaz (Ebola). O poder imunogênico define se a vacina ou a infecção natural protegem por toda a vida.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao explicar a um paciente por que a criança sem sintomas pode transmitir pólio, a resposta é patogenicidade baixa com infectividade alta. Ao explicar por que a raiva exige profilaxia mesmo com risco pequeno, a resposta é virulência máxima. Nomear a propriedade organiza a conduta.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Infectividade: instalar-se e multiplicar; patogenicidade: adoecer; virulência: gravidade.</li>
<li>Virulência é propriedade; letalidade é o indicador (óbitos/casos).</li>
<li>Sarampo: tudo alto; pólio: infectividade alta, patogenicidade baixa; raiva: virulência máxima.</li>
<li>As propriedades definem a estratégia de controle.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual propriedade descreve a capacidade de alojar-se e multiplicar-se no hospedeiro? <details><summary>Resposta</summary>A infectividade.</details></li>
<li>Qual é a diferença entre virulência e letalidade? <details><summary>Resposta</summary>Virulência é a propriedade do agente de causar doença grave; letalidade é o indicador que a mede, óbitos entre os doentes.</details></li>
</ol>
`,
"unesp2026#91": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer o estudo de coorte pela direção, pela medida e pelo caráter observacional.</li>
<li>Calcular e interpretar incidência e risco relativo.</li>
<li>Comparar coorte com caso-controle, transversal e ensaio clínico.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Coorte</dt>
<dd>Grupo definido pela exposição, seguido no tempo para medir a incidência do desfecho.</dd>
<dt>Risco relativo</dt>
<dd>Incidência nos expostos dividida pela incidência nos não expostos; medida direta de risco.</dd>
<dt>Coorte histórica (retrospectiva)</dt>
<dd>Exposição e desfecho já ocorreram, mas o desenho parte da exposição registrada no passado.</dd>
<dt>Perda de seguimento</dt>
<dd>Principal ameaça da coorte; perdas diferenciais distorcem a incidência.</dd>
</dl>
<h4>O essencial</h4>
<p>O estudo de <strong>coorte</strong> parte da <strong>exposição</strong>: identifica pessoas expostas e não expostas a um fator suposto como causa, todas sem a doença no início, e as <strong>segue no tempo</strong> para contar quem adoece. Por isso produz <strong>incidências</strong> e, delas, o <strong>risco relativo</strong> e o risco atribuível, medidas <strong>diretas</strong> de risco. É <strong>observacional</strong>: o pesquisador não decide quem se expõe, ao contrário do ensaio clínico, em que a exposição (o tratamento) é alocada por randomização. Pode ser prospectiva (segue a partir de agora) ou histórica (reconstrói a partir de registros), mas a lógica é sempre da causa para o efeito.</p>
<p>Suas forças: estabelece a <strong>temporalidade</strong>, mede incidência, estuda vários desfechos de uma mesma exposição e serve para exposições raras. Suas fraquezas: é cara e demorada, inadequada para doenças raras e vulnerável à <strong>perda de seguimento</strong> e à confusão, que se controla por pareamento e análise ajustada.</p>
<p>O <strong>caso-controle</strong> faz o caminho inverso: parte do <strong>desfecho</strong> (casos e controles) e olha para trás em busca da exposição; não mede incidência, estima o risco pela <strong>razão de chances</strong>, é rápido e barato e serve a doenças raras, ao custo de vieses de seleção e de memória. O <strong>transversal</strong> mede exposição e desfecho ao mesmo tempo, dá prevalência e não estabelece temporalidade. O <strong>ecológico</strong> compara populações, não indivíduos. O <strong>ensaio clínico randomizado</strong> é experimental e é o único que controla confundidores desconhecidos.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Para reconhecer o desenho numa prova, faça duas perguntas: o estudo começa pela exposição ou pela doença? O pesquisador escolheu quem se expõe? Exposição sem escolha é coorte; doença é caso-controle; escolha é ensaio. A medida confirma: incidência e risco relativo são da coorte.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Coorte: parte da exposição, segue no tempo, mede incidência e risco relativo; observacional.</li>
<li>Forças: temporalidade, vários desfechos, exposições raras; fraquezas: custo, tempo, perdas.</li>
<li>Caso-controle: parte do desfecho, razão de chances, doenças raras.</li>
<li>Transversal: prevalência; ensaio clínico: exposição alocada por randomização.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que medida de associação a coorte produz e por quê? <details><summary>Resposta</summary>O risco relativo, porque mede a incidência nos expostos e nos não expostos.</details></li>
<li>O que diferencia a coorte do ensaio clínico? <details><summary>Resposta</summary>Na coorte a exposição é observada; no ensaio ela é alocada pelo pesquisador, em geral por randomização.</details></li>
</ol>
`,
"unesp2026#92": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Listar as situações em que a vacinação é adiada.</li>
<li>Reconhecer as falsas contraindicações, que não justificam adiar.</li>
<li>Aplicar os intervalos entre imunoglobulina e vacinas de vírus vivo.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Adiamento</dt>
<dd>Postergar a dose por uma condição transitória que pode reduzir a resposta ou confundir a avaliação de eventos adversos.</dd>
<dt>Contraindicação</dt>
<dd>Condição em que a vacina não deve ser dada: anafilaxia prévia, imunodeficiência grave para vacinas vivas, gestação para vacinas vivas.</dd>
<dt>Falsa contraindicação</dt>
<dd>Situação em que se deixa de vacinar sem motivo: resfriado, desnutrição, prematuridade, antibiótico, história familiar de reação.</dd>
<dt>Interferência por anticorpos passivos</dt>
<dd>Imunoglobulinas e hemoderivados neutralizam o vírus vacinal atenuado por semanas a meses.</dd>
</dl>
<h4>O essencial</h4>
<p>O Manual de Normas e Procedimentos para Vacinação distingue três situações. As <strong>contraindicações</strong> verdadeiras são poucas: reação anafilática a dose anterior ou a componente, imunodeficiência grave e gestação para as vacinas de vírus vivo, encefalopatia nos 7 dias após vacina com componente pertussis. As situações de <strong>adiamento</strong> são transitórias: <strong>doença aguda febril grave</strong> (para não confundir a evolução da doença com evento adverso e não vacinar quem está em estresse imunológico); uso de <strong>corticoide em dose imunossupressora</strong> (2 mg/kg/dia de prednisona por 14 dias ou mais, ou 20 mg/dia no maior), com vacinas vivas adiadas até 1 mês após a suspensão; quimioterapia e outros imunossupressores; e a <strong>administração de imunoglobulina, sangue ou derivados</strong>, que exige intervalo antes das vacinas de vírus vivo injetáveis (tríplice viral, tetraviral, varicela), em geral de <strong>3 meses</strong> após imunoglobulina padrão e até 11 meses após imunoglobulina intravenosa em dose alta.</p>
<p>As <strong>falsas contraindicações</strong> são a causa mais comum de oportunidade perdida: doença aguda leve com febre baixa, resfriado, diarreia leve, uso de antibiótico, desnutrição, prematuridade e baixo peso (vacina-se pela idade cronológica, salvo BCG e hepatite B abaixo de 2 kg), internação hospitalar, alergia não anafilática, história familiar de reação, aleitamento, convalescença.</p>
<p>O intervalo entre vacinas vivas injetáveis diferentes é de 30 dias quando não aplicadas no mesmo dia; vacinas inativadas não exigem intervalo entre si nem com as vivas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Criança internada por bronquiolite leve, prematura, em uso de antibiótico, pode e deve ser vacinada antes da alta. Criança com febre alta e toxemia espera; criança que recebeu imunoglobulina espera pela tríplice viral.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Adiar: doença aguda febril grave, corticoide em dose imunossupressora, imunossupressores, imunoglobulina antes de vacinas vivas injetáveis.</li>
<li>Imunoglobulina: cerca de 3 meses antes de tríplice viral e varicela (até 11 após IGIV em dose alta).</li>
<li>Falsas contraindicações: resfriado, desnutrição, prematuridade, antibiótico, internação, aleitamento.</li>
<li>Vivas injetáveis diferentes: mesmo dia ou 30 dias de intervalo.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Cite duas situações de adiamento da vacinação. <details><summary>Resposta</summary>Doença aguda febril grave e uso recente de imunoglobulina antes de vacinas vivas injetáveis, como caxumba e rubéola.</details></li>
<li>Prematuridade adia a vacinação? <details><summary>Resposta</summary>Não; vacina-se pela idade cronológica, exceto BCG e hepatite B abaixo de 2 kg.</details></li>
</ol>
`,
"unesp2026#93": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conduzir o recém-nascido contato de mãe bacilífera: quimioprofilaxia primária antes da BCG.</li>
<li>Escolher o esquema: rifampicina por 4 meses ou isoniazida por 3 meses, sem prova tuberculínica.</li>
<li>Manter o aleitamento e notificar.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Quimioprofilaxia primária</dt>
<dd>Tratamento do recém-nascido exposto antes que se infecte, sem prova tuberculínica prévia.</dd>
<dt>BCG adiada</dt>
<dd>A vacina não é aplicada ao nascer no contato de bacilífero; aplica-se ao fim da profilaxia.</dd>
<dt>Bacilífera</dt>
<dd>Pessoa com tuberculose pulmonar ou laríngea com baciloscopia ou teste molecular positivos.</dd>
<dt>Aleitamento com máscara</dt>
<dd>A mãe amamenta usando máscara cirúrgica até deixar de ser bacilífera; o leite não transmite o bacilo.</dd>
</dl>
<h4>O essencial</h4>
<p>O recém-nascido de mãe com tuberculose bacilífera está exposto a um risco alto de infecção e de formas graves. O Manual de Recomendações para o Controle da Tuberculose orienta: <strong>não aplicar a BCG ao nascer</strong>, porque a vacina impediria a interpretação da prova tuberculínica e não protege de imediato; iniciar <strong>quimioprofilaxia primária</strong> com <strong>rifampicina por 4 meses</strong> (esquema preferencial atual) ou isoniazida por 3 meses; ao fim, <strong>aplicar a BCG</strong> se o recém-nascido estiver assintomático. Na versão anterior, a prova tuberculínica era feita ao fim da isoniazida para decidir entre BCG (negativa) e continuar até 6 meses (positiva); com a rifampicina por 4 meses, a recomendação é aplicar a BCG ao término, sem prova.</p>
<p>O recém-nascido é avaliado clinicamente antes e durante a profilaxia; qualquer sinal de doença (febre, baixo ganho de peso, hepatoesplenomegalia, desconforto respiratório) leva à investigação de tuberculose congênita ou perinatal e ao tratamento completo. A mãe em tratamento correto deixa de ser bacilífera em 2 a 3 semanas; até lá, amamenta com máscara, e a separação não é indicada. O <strong>aleitamento é mantido</strong>: os fármacos passam ao leite em quantidade sem risco.</p>
<p>A situação é <strong>notificada</strong> à vigilância como contato, o serviço registra a profilaxia e faz a busca de outros contatos domiciliares. Se a mãe tem tuberculose resistente, a decisão é da referência. Se a mãe é bacilífera no parto e não tratada, o caso é o mesmo, com investigação da mãe em paralelo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>A pergunta "posso amamentar?" recebe sim, com máscara nas primeiras semanas; a pergunta "meu bebê vai tomar a BCG?" recebe "vai, no fim da profilaxia". O que não pode acontecer é o bebê sair da maternidade com a BCG aplicada e sem a profilaxia.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Contato de mãe bacilífera: sem BCG ao nascer, quimioprofilaxia primária.</li>
<li>Rifampicina por 4 meses (ou isoniazida 3 meses); BCG ao fim, sem prova tuberculínica.</li>
<li>Aleitamento mantido, com máscara até a mãe deixar de ser bacilífera.</li>
<li>Notificar e buscar os outros contatos.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a BCG não é aplicada ao nascer no contato de bacilífera? <details><summary>Resposta</summary>Porque não protege de imediato e atrapalharia a avaliação; aplica-se ao fim da quimioprofilaxia.</details></li>
<li>A mãe em tratamento pode amamentar? <details><summary>Resposta</summary>Sim, com máscara enquanto for bacilífera; os fármacos no leite não oferecem risco.</details></li>
</ol>
`,
"unesp2026#94": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir Redes de Atenção à Saúde e linhas de cuidado.</li>
<li>Explicar a relação entre a estrutura integrada da rede e o percurso do usuário na linha.</li>
<li>Situar a atenção primária como coordenadora da rede.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Rede de Atenção à Saúde (RAS)</dt>
<dd>Arranjo organizativo de ações e serviços de diferentes densidades tecnológicas, integrados por sistemas de apoio e logística.</dd>
<dt>Linha de cuidado</dt>
<dd>Percurso assistencial pactuado para uma condição, com fluxos, protocolos e responsabilidades em cada ponto.</dd>
<dt>Ponto de atenção</dt>
<dd>Cada serviço da rede (unidade básica, ambulatório, hospital, CAPS) com sua função definida.</dd>
<dt>Condição crônica</dt>
<dd>Problema de saúde de longa duração que exige cuidado contínuo e coordenado; foco das redes.</dd>
</dl>
<h4>O essencial</h4>
<p>A Portaria 4.279/2010 define as <strong>Redes de Atenção à Saúde</strong> como arranjos organizativos de ações e serviços de saúde, de diferentes densidades tecnológicas, que, integrados por meio de sistemas de apoio técnico, logístico e de gestão, buscam garantir a <strong>integralidade do cuidado</strong>. A rede tem uma população definida, uma estrutura operacional (a atenção primária como centro de comunicação, os pontos de atenção secundários e terciários, os sistemas de apoio como laboratório e farmácia, os sistemas logísticos como regulação, prontuário e transporte, e o sistema de governança) e um modelo de atenção, voltado sobretudo às condições crônicas.</p>
<p>A <strong>linha de cuidado</strong> é o desenho do <strong>percurso do usuário</strong> dentro da rede para uma condição específica: da suspeita ao diagnóstico, do tratamento ao seguimento, com os fluxos, os protocolos clínicos, os critérios de encaminhamento e as responsabilidades de cada ponto pactuados. A linha de cuidado da gestante, do infarto, do AVC, do câncer de mama ou da saúde mental diz o que a unidade básica faz, quando e como encaminha, o que o hospital garante e como o paciente volta.</p>
<p>A relação entre os dois conceitos é de <strong>estrutura e trajeto</strong>: a rede é a organização integrada dos serviços; a linha de cuidado é o caminho que o usuário percorre por eles, orientado por protocolos. As redes temáticas do SUS (Rede Cegonha, de urgência, psicossocial, de cuidados à pessoa com deficiência, de doenças crônicas) organizam-se justamente por linhas de cuidado.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um paciente com dor torácica chega à unidade básica, a linha de cuidado do infarto diz o que fazer nos próximos 10 minutos e para onde ele vai; a rede de urgência garante que o SAMU, o hospital com hemodinâmica e o retorno à unidade existam. Conhecer as duas coisas é o que transforma protocolo em cuidado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>RAS: arranjo integrado de serviços de diferentes densidades, com apoio, logística e governança.</li>
<li>Linha de cuidado: percurso do usuário para uma condição, com fluxos e protocolos.</li>
<li>Rede é estrutura; linha é trajeto; a atenção primária coordena.</li>
<li>Redes temáticas do SUS se organizam por linhas de cuidado.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a relação entre rede de atenção e linha de cuidado? <details><summary>Resposta</summary>A rede integra os serviços; a linha de cuidado orienta o percurso do usuário por eles, com fluxos e protocolos.</details></li>
<li>Qual ponto coordena a rede? <details><summary>Resposta</summary>A atenção primária, como centro de comunicação e coordenadora do cuidado.</details></li>
</ol>
`,
"unesp2026#96": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Compreender a violência contra a mulher como questão de gênero e de determinantes sociais.</li>
<li>Descrever os eixos da Política Nacional de Enfrentamento à Violência contra as Mulheres.</li>
<li>Reconhecer o papel do setor saúde na rede intersetorial.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Violência de gênero</dt>
<dd>Violência dirigida à mulher por ser mulher, enraizada na desigualdade de poder entre os sexos.</dd>
<dt>Intersetorialidade</dt>
<dd>Ação articulada de saúde, assistência social, segurança, justiça, educação e trabalho.</dd>
<dt>Rede de enfrentamento</dt>
<dd>Conjunto de serviços e instituições que atuam na prevenção, na assistência e na responsabilização.</dd>
<dt>Lei Maria da Penha</dt>
<dd>Lei 11.340/2006; define as formas de violência doméstica e cria medidas protetivas.</dd>
</dl>
<h4>O essencial</h4>
<p>A Política Nacional de Enfrentamento à Violência contra as Mulheres (2011) parte de uma concepção: a violência não é um desvio individual nem um problema privado, é a expressão de <strong>relações desiguais de poder entre homens e mulheres</strong>, sustentadas por normas culturais, dependência econômica, racismo, precariedade de moradia e trabalho e falhas do Estado. Por reconhecer essas <strong>múltiplas determinantes sociais</strong>, a política define que o enfrentamento tem de ser <strong>intersetorial e multidisciplinar</strong>, em quatro eixos: <strong>prevenção</strong> (educação, mudança cultural), <strong>assistência</strong> (rede de atendimento humanizado), <strong>combate</strong> (responsabilização pela Lei Maria da Penha) e <strong>garantia de direitos</strong> (autonomia econômica, moradia, acesso à justiça).</p>
<p>A PNAISM incorpora a mesma leitura: a violência é um problema de saúde pública que adoece, mata e atravessa gerações, e o setor saúde é parte da rede, não seu centro. Cabe a ele acolher, identificar (a maioria das mulheres chega com queixas indiretas: dor crônica, depressão, lesões repetidas), cuidar das lesões físicas e psíquicas, oferecer profilaxias na violência sexual, <strong>notificar</strong> ao SINAN (obrigatório na suspeita, sigiloso, distinto da denúncia) e articular com a assistência social, as delegacias especializadas, os centros de referência, as casas-abrigo e a justiça, sempre respeitando a autonomia da mulher sobre os próprios passos.</p>
<p>O que a política afasta: reduzir a violência a patologia individual do agressor ou da vítima, esperar que a mulher "denuncie" como condição do cuidado, delegar tudo à polícia, ou tratar como assunto de família.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Uma mulher com dor crônica, insônia e consultas frequentes merece a pergunta, a sós: "alguém em casa faz você ter medo?". Se a resposta é sim, o plano se faz com ela: notificação, cuidado das lesões, contatos da rede, e o retorno marcado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Violência contra a mulher: questão de gênero e de determinantes sociais múltiplas.</li>
<li>Enfrentamento intersetorial e multidisciplinar: prevenção, assistência, combate, garantia de direitos.</li>
<li>Saúde acolhe, identifica, cuida, notifica e articula a rede; não substitui os outros setores.</li>
<li>Autonomia da mulher; a denúncia não é condição do cuidado.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a política define o enfrentamento como intersetorial? <details><summary>Resposta</summary>Porque a violência tem múltiplas determinantes sociais (gênero, economia, cultura, Estado) que nenhum setor resolve sozinho.</details></li>
<li>Quais são os quatro eixos da política? <details><summary>Resposta</summary>Prevenção, assistência, combate e garantia de direitos.</details></li>
</ol>
`,
"unesp2026#97": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Calcular a letalidade e distingui-la do coeficiente de mortalidade.</li>
<li>Calcular a mortalidade proporcional e o coeficiente de mortalidade específico.</li>
<li>Escolher o denominador certo para cada indicador.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Letalidade</dt>
<dd>Óbitos pela doença dividido pelo número de casos da doença, em porcentagem.</dd>
<dt>Coeficiente de mortalidade específico</dt>
<dd>Óbitos pela doença dividido pela população exposta, por 100 mil, no período.</dd>
<dt>Mortalidade proporcional</dt>
<dd>Óbitos pela doença dividido pelo total de óbitos por todas as causas, em porcentagem.</dd>
<dt>Coeficiente de incidência</dt>
<dd>Casos novos dividido pela população em risco, no período.</dd>
</dl>
<h4>O essencial</h4>
<p>Cada indicador de mortalidade tem um <strong>denominador</strong> que define a pergunta. A <strong>letalidade</strong> pergunta "de quem tem a doença, quantos morrem dela?": o denominador são os <strong>casos</strong>. Num município com 80 casos de câncer de mama no ano e 4 óbitos por esse câncer, a letalidade é 4 ÷ 80 = <strong>5%</strong>. O tamanho da população e a proporção de mulheres não entram, porque a pergunta é sobre os doentes.</p>
<p>O <strong>coeficiente de mortalidade específico</strong> pergunta "quanto a doença mata na população?": o denominador é a <strong>população exposta</strong>. Com 12.000 habitantes, 4 ÷ 12.000 = 33 por 100 mil; se o indicador é restrito às mulheres, 52% de 12.000 são 6.240, e 4 ÷ 6.240 = 64 por 100 mil mulheres. A <strong>mortalidade proporcional</strong> pergunta "de todos os que morreram, que fração morreu dessa causa?": o denominador é o <strong>total de óbitos</strong>, o que exige saber quantas pessoas morreram no município por todas as causas. O <strong>coeficiente de incidência</strong> pergunta "quantos adoeceram?": 80 ÷ 6.240 = cerca de 1.282 por 100 mil mulheres.</p>
<p>Os erros de prova são trocas de denominador: dividir os óbitos pela população e chamar de letalidade, ou dividir pelos casos e chamar de mortalidade. A letalidade é a medida da <strong>gravidade</strong> e da qualidade da assistência; o coeficiente de mortalidade, do <strong>impacto</strong> na população; a mortalidade proporcional, da <strong>importância relativa</strong> da causa. Uma doença pode ter letalidade alta e mortalidade baixa (raiva), ou letalidade baixa e mortalidade alta (doenças cardiovasculares).</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de calcular, escreva a pergunta e o denominador: "de quem tem" (casos), "na população" (habitantes) ou "de todos os óbitos" (mortes totais). Os números do enunciado que não entram no denominador estão lá para distrair.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Letalidade: óbitos pela doença ÷ casos da doença.</li>
<li>Mortalidade específica: óbitos pela doença ÷ população exposta.</li>
<li>Mortalidade proporcional: óbitos pela doença ÷ total de óbitos.</li>
<li>Letalidade mede gravidade; mortalidade mede impacto; proporcional mede importância relativa.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>80 casos e 4 óbitos por câncer de mama: qual é a letalidade? <details><summary>Resposta</summary>4 dividido por 80: 5%.</details></li>
<li>Que dado faltaria para a mortalidade proporcional por câncer de mama? <details><summary>Resposta</summary>O total de óbitos por todas as causas no município no período.</details></li>
</ol>
`,
"unesp2026#100": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer o caso-controle e seus vieses típicos: seleção e memória.</li>
<li>Associar cada estratégia metodológica ao viés que ela reduz.</li>
<li>Explicar por que registros eletrônicos reduzem o viés de memória.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Viés de memória (recordação)</dt>
<dd>Casos lembram exposições passadas de forma diferente dos controles, em geral com mais cuidado.</dd>
<dt>Viés de seleção</dt>
<dd>Casos e controles escolhidos de modo que a chance de entrar no estudo depende da exposição.</dd>
<dt>Viés do entrevistador</dt>
<dd>O pesquisador pergunta ou registra de forma diferente conforme sabe quem é caso.</dd>
<dt>Cegamento</dt>
<dd>Entrevistador ou avaliador sem saber quem é caso ou controle, quem foi exposto ou tratado.</dd>
</dl>
<h4>O essencial</h4>
<p>O caso-controle começa pelo desfecho e pergunta ao passado. É rápido, barato e o desenho de escolha para doenças raras, mas sua fragilidade está justamente em <strong>como se lembra e se registra a exposição</strong>. Quem tem a doença procura explicações e recorda exposições com mais detalhe (ou as exagera); quem é controle não tem por que lembrar. Esse é o <strong>viés de memória</strong>, e a defesa contra ele é obter a exposição de uma fonte <strong>registrada antes do desfecho</strong>: prontuários e <strong>registros eletrônicos</strong>, bases de dispensação de medicamentos, registros ocupacionais, exames armazenados. Fontes assim são as mesmas para casos e controles e não dependem da lembrança.</p>
<p>Outros vieses têm outras defesas. O <strong>viés de seleção</strong> se combate escolhendo controles da <strong>mesma população-base</strong> dos casos (controles populacionais, de vizinhança ou hospitalares com doenças não relacionadas à exposição), e com critérios de inclusão idênticos. O <strong>viés do entrevistador</strong> se combate com <strong>cegamento</strong> do entrevistador quanto ao status de caso e com questionários padronizados. A <strong>confusão</strong> se combate com pareamento, restrição e análise ajustada. O viés de aferição diferencial se combate medindo a exposição da mesma forma nos dois grupos.</p>
<p>A leitura de um caso-controle exige perguntar: de onde vieram os controles? Como a exposição foi medida e por quem? Os entrevistadores sabiam quem era caso? Que confundidores foram ajustados? A resposta a cada pergunta é uma estratégia com nome, e a prova costuma cobrar a ligação entre estratégia e viés.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Um estudo que liga um medicamento a uma malformação, baseado no que as mães lembram ter tomado na gestação, tem viés de memória embutido; o mesmo estudo com os registros de dispensação da farmácia é outro estudo. Ao ler, procure a fonte da exposição antes de acreditar na razão de chances.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Caso-controle: parte do desfecho; vulnerável a memória e seleção.</li>
<li>Registros eletrônicos e fontes anteriores ao desfecho reduzem o viés de memória.</li>
<li>Controles da mesma população-base reduzem o viés de seleção.</li>
<li>Cegamento do entrevistador reduz o viés do entrevistador; pareamento e ajuste, a confusão.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que registros eletrônicos reduzem o viés de memória? <details><summary>Resposta</summary>Porque a exposição foi registrada antes do desfecho, da mesma forma para casos e controles, sem depender da lembrança.</details></li>
<li>Que estratégia combate o viés do entrevistador? <details><summary>Resposta</summary>O cegamento do entrevistador quanto ao status de caso, com questionário padronizado.</details></li>
</ol>
`,
"einstein2026#61": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Diagnosticar o delirium pelos critérios clínicos e pelo CAM.</li>
<li>Identificar as causas precipitantes, com os anticolinérgicos à frente.</li>
<li>Tratar com medidas não farmacológicas e correção da causa.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Delirium</dt>
<dd>Alteração aguda e flutuante da atenção e da consciência, com pensamento desorganizado, por causa orgânica.</dd>
<dt>CAM (Confusion Assessment Method)</dt>
<dd>Início agudo com flutuação, desatenção e pensamento desorganizado ou alteração da consciência.</dd>
<dt>Carga anticolinérgica</dt>
<dd>Soma dos efeitos anticolinérgicos dos fármacos em uso: difenidramina, amitriptilina, oxibutinina, entre outros.</dd>
<dt>Critérios de Beers</dt>
<dd>Lista de medicamentos potencialmente inapropriados para idosos.</dd>
</dl>
<h4>O essencial</h4>
<p>O delirium é uma emergência geriátrica frequente e subdiagnosticada: começa em <strong>horas a dias</strong>, <strong>flutua</strong> ao longo do dia (pior à noite), e tem como núcleo a <strong>desatenção</strong>, com pensamento desorganizado, alteração do nível de consciência, inversão do ciclo sono-vigília e, às vezes, alucinações. Pode ser hiperativo (agitação), hipoativo (apatia, o mais comum e o mais perdido) ou misto. O CAM operacionaliza o diagnóstico à beira do leito. A demência prévia é o principal fator predisponente; o delirium não é demência, mas a agrava.</p>
<p>A causa é sempre orgânica e muitas vezes múltipla: <strong>medicamentos</strong> (anticolinérgicos, benzodiazepínicos, opioides, corticoides), infecção, desidratação, distúrbios eletrolíticos, <strong>constipação e retenção urinária</strong>, dor, hipóxia, privação de sono, mudança de ambiente. Na idosa em uso de <strong>difenidramina</strong> para dormir, <strong>amitriptilina</strong> para dor e <strong>oxibutinina</strong> para bexiga, a carga anticolinérgica é a explicação mais provável, agravada pela constipação de dias; todos os três estão nos critérios de Beers.</p>
<p>O tratamento é <strong>não farmacológico e etiológico</strong>: <strong>suspender os anticolinérgicos</strong> e revisar cada fármaco, hidratar, tratar a constipação e a retenção, corrigir eletrólitos, tratar infecção se houver, <strong>reorientar</strong> (relógio, calendário, luz do dia, óculos e aparelho auditivo), <strong>mobilizar cedo</strong>, preservar o sono, manter familiares próximos e evitar contenção. Antipsicótico em dose baixa só na agitação que põe em risco o paciente ou o cuidado; benzodiazepínico só na abstinência alcoólica. A reavaliação é em 24 horas, e a família precisa saber que a melhora pode levar dias a semanas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Idoso que "ficou confuso de repente" faz três coisas antes de qualquer exame de imagem: lista de remédios na mão (anticolinérgicos e benzodiazepínicos saem), toque retal e bexiga (constipação e retenção), e glicemia com sódio. A tomografia fica para o déficit focal ou o trauma.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Agudo, flutuante, desatenção, pensamento desorganizado; CAM à beira do leito.</li>
<li>Causas: anticolinérgicos e outros fármacos, infecção, desidratação, constipação, retenção, dor.</li>
<li>Suspender anticolinérgicos, hidratar, tratar a causa, reorientar, mobilizar, preservar sono.</li>
<li>Antipsicótico só na agitação de risco; sem benzodiazepínico (salvo abstinência).</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é o sintoma nuclear do delirium? <details><summary>Resposta</summary>A desatenção, de início agudo e curso flutuante.</details></li>
<li>Quais fármacos suspender na idosa com delirium em uso de difenidramina, amitriptilina e oxibutinina? <details><summary>Resposta</summary>Os três, pela carga anticolinérgica; a oxibutinina pode ser revisada com opção não anticolinérgica.</details></li>
</ol>
`,
"einstein2026#66": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar o modelo de estágios de mudança ao adolescente que quer parar de fumar.</li>
<li>Avaliar a dependência de nicotina com o teste de Fagerström.</li>
<li>Oferecer a abordagem cognitivo-comportamental em grupo, sem farmacoterapia no adolescente.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Estágios de mudança</dt>
<dd>Pré-contemplação, contemplação, preparação, ação, manutenção e recaída (Prochaska e DiClemente).</dd>
<dt>Teste de Fagerström</dt>
<dd>Seis perguntas que graduam a dependência de nicotina de muito baixa a muito elevada.</dd>
<dt>Abordagem intensiva</dt>
<dd>Sessões estruturadas, individuais ou em grupo, com técnicas cognitivo-comportamentais, no SUS.</dd>
<dt>Autonomia do adolescente</dt>
<dd>Direito de ser atendido sozinho e de ter sigilo, salvo risco de vida.</dd>
</dl>
<h4>O essencial</h4>
<p>O adolescente que procura a unidade sozinho para parar de fumar, motivado por um evento na família, está no estágio de <strong>preparação</strong> (ou contemplação avançada): reconhece o problema e quer agir. O modelo de estágios de mudança orienta a resposta: em pré-contemplação, informa-se e semeia-se dúvida; em contemplação, trabalha-se a ambivalência; em <strong>preparação</strong>, <strong>aproveita-se a janela</strong> para planejar a parada com data, estratégias e apoio; em ação e manutenção, previne-se a recaída. Perder a janela é o erro mais caro.</p>
<p>O primeiro passo clínico é <strong>avaliar a dependência</strong> com o teste de Fagerström (tempo até o primeiro cigarro, número por dia, dificuldade em ambientes proibidos) e a história de tentativas anteriores. Quem fuma desde os 12 anos pode ter dependência moderada a alta, com fissura e sintomas de abstinência, o que muda o plano de enfrentamento.</p>
<p>O tratamento no SUS é a <strong>abordagem cognitivo-comportamental</strong>, breve na consulta e <strong>intensiva em grupo</strong> (quatro sessões semanais estruturadas, depois quinzenais e mensais), com material do INCA. A <strong>farmacoterapia</strong> (reposição de nicotina, bupropiona, vareniclina) é indicada para adultos com dependência moderada a alta; em <strong>menores de 18 anos não é recomendada</strong> nos protocolos brasileiros, por falta de evidência, e por isso o adolescente recebe o aconselhamento e o grupo, com envolvimento da família quando ele consentir. O atendimento é sigiloso e sem exigência de acompanhante.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>A frase "vou marcar com você para a semana que vem, quando seus pais puderem vir" devolve o adolescente à rua com o cigarro. Atenda hoje, aplique o Fagerström, marque a data de parada e a primeira sessão do grupo; os pais entram se ele quiser.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Estágios de mudança: identificar o estágio e agir na janela de preparação.</li>
<li>Avaliar a dependência com Fagerström e as tentativas anteriores.</li>
<li>Abordagem cognitivo-comportamental em grupo no SUS.</li>
<li>Sem farmacoterapia em menores de 18 anos; atendimento sigiloso e sem acompanhante.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Em que estágio está o adolescente que procura ajuda sozinho para parar? <details><summary>Resposta</summary>Preparação: reconhece o problema e quer agir; a conduta é planejar a parada agora.</details></li>
<li>Adolescente de 16 anos com Fagerström alto recebe bupropiona? <details><summary>Resposta</summary>Não; a farmacoterapia não é recomendada abaixo de 18 anos; oferece-se a abordagem em grupo.</details></li>
</ol>
`,
"einstein2026#69": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Diagnosticar a fibromialgia pelos critérios clínicos, sem exames confirmatórios.</li>
<li>Hierarquizar o tratamento: exercício, educação e psicoterapia antes do fármaco.</li>
<li>Escolher fármacos adjuvantes com segurança no idoso com função renal reduzida.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Fibromialgia</dt>
<dd>Dor difusa crônica com fadiga, sono não reparador e sintomas cognitivos, por sensibilização central.</dd>
<dt>Sensibilização central</dt>
<dd>Amplificação do processamento da dor no sistema nervoso, sem lesão tecidual.</dd>
<dt>Exercício supervisionado</dt>
<dd>Aeróbico de baixo impacto e fortalecimento progressivos; a intervenção com melhor evidência.</dd>
<dt>Fármaco adjuvante</dt>
<dd>Amitriptilina, duloxetina, pregabalina ou ciclobenzaprina, em dose baixa, associados ao plano não farmacológico.</dd>
</dl>
<h4>O essencial</h4>
<p>A fibromialgia é um quadro de <strong>dor musculoesquelética difusa</strong> há mais de 3 meses, com <strong>fadiga</strong>, <strong>sono não reparador</strong>, dificuldade de concentração e humor deprimido, em paciente com exame e exames normais. O diagnóstico é clínico (critérios do ACR de 2010/2016, com índice de dor generalizada e escala de gravidade de sintomas), sem pontos dolorosos obrigatórios e sem marcador; hemograma, VHS, TSH e CK servem para afastar diferenciais (hipotireoidismo, polimialgia reumática, miopatia). A dor é real e tem base em sensibilização central, não em inflamação.</p>
<p>As recomendações da EULAR e da Sociedade Brasileira de Reumatologia hierarquizam: a <strong>base é não farmacológica</strong>: <strong>educação</strong> sobre a doença (nomear, explicar que não é destrutiva, envolver na decisão), <strong>exercício físico supervisionado</strong> e progressivo (aeróbico de baixo impacto, fortalecimento, aquático, tai chi), <strong>terapia cognitivo-comportamental</strong>, higiene do sono e tratamento das comorbidades psiquiátricas. Os <strong>fármacos são adjuvantes</strong>, com efeito modesto: amitriptilina em dose baixa à noite, duloxetina, pregabalina ou ciclobenzaprina, escolhidos pelo sintoma dominante e pelo perfil do paciente.</p>
<p>Na idosa com função renal reduzida, viúva, isolada, com 14 meses de dor sem plano estruturado, o próximo passo é <strong>fortalecer o plano multiprofissional</strong> (exercício em grupo, psicoterapia, educação), com fármaco adjuvante cauteloso: amitriptilina em dose baixa exige atenção a queda, arritmia e retenção; a pregabalina precisa de ajuste renal; a duloxetina é opção com a pressão controlada.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Trocar de analgésico a cada consulta é o caminho da polifarmácia sem alívio. A consulta que muda a fibromialgia é a que explica a doença, prescreve a caminhada supervisionada, encaminha à psicologia e marca o retorno, com o fármaco em dose baixa como coadjuvante, não como protagonista.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Dor difusa crônica com fadiga, sono ruim e sintomas cognitivos; diagnóstico clínico.</li>
<li>Base: educação, exercício supervisionado, terapia cognitivo-comportamental.</li>
<li>Fármacos adjuvantes em dose baixa: amitriptilina, duloxetina, pregabalina, ciclobenzaprina.</li>
<li>No idoso: cautela com anticolinérgicos, ajuste renal da pregabalina, sem opioide.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a base do tratamento da fibromialgia? <details><summary>Resposta</summary>Educação, exercício físico supervisionado e psicoterapia; os fármacos são adjuvantes.</details></li>
<li>Que cuidado exige a pregabalina na idosa com TFG de 55? <details><summary>Resposta</summary>Ajuste de dose pela função renal e atenção a sonolência e quedas.</details></li>
</ol>
`,
"einstein2026#70": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Interpretar a prova tuberculínica no contato de bacilífero com o corte de 5 mm.</li>
<li>Indicar o esquema 3HP (rifapentina e isoniazida semanais por 12 semanas) como primeira escolha.</li>
<li>Reconhecer o contexto de moradia coletiva como fator de risco e de intervenção.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Infecção latente (ILTB)</dt>
<dd>Bacilo presente sem doença: sem sintomas, radiografia normal, prova ou IGRA positivos.</dd>
<dt>3HP</dt>
<dd>Rifapentina mais isoniazida, uma dose semanal por 12 semanas: esquema curto preferencial desde 2021.</dd>
<dt>Corte de 5 mm</dt>
<dd>Prova tuberculínica positiva em contatos, pessoas com HIV e imunossuprimidos.</dd>
<dt>Moradia coletiva</dt>
<dd>Aglomeração e ventilação ruim; alto risco de transmissão e alvo de busca ativa.</dd>
</dl>
<h4>O essencial</h4>
<p>O contato adulto de um caso bacilífero é avaliado para <strong>doença</strong> (sintomas, radiografia de tórax e, se houver tosse, escarro ou teste molecular) e, afastada a doença, para <strong>infecção latente</strong> com prova tuberculínica ou IGRA. No <strong>contato</strong>, a prova é positiva a partir de <strong>5 mm</strong>, independentemente da BCG; 10 mm é o corte para as demais situações. Prova negativa é repetida em 8 semanas. A infecção latente confirmada é tratada porque o risco de adoecer é maior nos dois primeiros anos após o contato, e ainda mais em quem vive aglomerado, é migrante recente de país de alta carga ou tem comorbidades.</p>
<p>O <strong>Protocolo de vigilância da ILTB</strong> de 2022 coloca como <strong>primeira escolha o esquema 3HP</strong>: <strong>rifapentina e isoniazida em dose semanal, por 12 semanas</strong> (12 doses), supervisionado ou não, para adultos e crianças a partir de 2 anos, inclusive pessoas com HIV sem interação com os antirretrovirais em uso. As opções: rifampicina diária por 4 meses (120 doses) e isoniazida diária por 6 a 9 meses (180 a 270 doses). O 3HP tem melhor adesão e menor hepatotoxicidade; a hipersensibilidade sistêmica é o evento adverso a vigiar. Gestantes preferem isoniazida ou rifampicina, e contatos de casos resistentes têm decisão em referência.</p>
<p>A moradia coletiva de dez trabalhadores é, por si, motivo de <strong>busca ativa</strong> de todos os moradores, avaliação de ventilação e articulação com a vigilância e a saúde do trabalhador; o migrante recente tem direito ao SUS integralmente. A notificação da ILTB é obrigatória e o seguimento mensal acompanha adesão e efeitos adversos.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Contato assintomático, radiografia normal, prova de 5 mm: não é "reação da BCG", é infecção latente a tratar. Prescreva o 3HP, explique as 12 semanas e marque o retorno mensal; e mande a equipe ao alojamento, porque há outros nove a avaliar.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Contato: afastar doença; prova tuberculínica positiva a partir de 5 mm.</li>
<li>ILTB: tratar; primeira escolha 3HP (rifapentina e isoniazida semanais, 12 semanas).</li>
<li>Opções: rifampicina 4 meses, isoniazida 6 a 9 meses.</li>
<li>Moradia coletiva: busca ativa de todos, ventilação, vigilância.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é o corte da prova tuberculínica no contato de bacilífero? <details><summary>Resposta</summary>5 mm, independentemente da vacinação BCG.</details></li>
<li>Qual é o esquema preferencial para a infecção latente desde 2021? <details><summary>Resposta</summary>3HP: rifapentina e isoniazida em dose semanal por 12 semanas.</details></li>
</ol>
`,
"einstein2026#71": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a insegurança alimentar como determinante da obesidade em contextos de pobreza.</li>
<li>Priorizar a ação intersetorial e as mudanças graduais sobre a prescrição de dietas e fármacos.</li>
<li>Aplicar o Guia Alimentar e a Política Nacional de Alimentação e Nutrição na atenção primária.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Insegurança alimentar</dt>
<dd>Acesso irregular ou insuficiente a alimentos em quantidade e qualidade, por falta de recursos.</dd>
<dt>Dupla carga</dt>
<dd>Coexistência de obesidade e deficiências nutricionais na mesma pessoa ou família pobre.</dd>
<dt>Determinantes sociais</dt>
<dd>Renda, trabalho, moradia, escolaridade, gênero e raça que moldam a alimentação e o adoecimento.</dd>
<dt>Intersetorialidade</dt>
<dd>Articulação da saúde com assistência social, programas de transferência de renda, educação e agricultura familiar.</dd>
</dl>
<h4>O essencial</h4>
<p>A obesidade nas populações pobres não é resultado de escolhas erradas, mas de um ambiente em que os alimentos mais baratos, acessíveis e duráveis são os ultraprocessados, e em que a comida acaba antes do fim do mês. A <strong>insegurança alimentar</strong> produz ciclos de restrição e compensação, preferência por alimentos densos em energia, ansiedade e sono ruim, e coexiste com anemia e outras carências: a <strong>dupla carga</strong>.</p>
<p>Diante desse quadro, prescrever dieta hipocalórica detalhada ou iniciar fármaco antiobesidade ignora a causa e produz culpa e abandono. A conduta com sentido é a que a atenção primária e o Guia Alimentar propõem: <strong>mudanças graduais e possíveis</strong> no padrão alimentar (comida de verdade, feita em casa, feijão e arroz, o que a região produz; menos ultraprocessados quando há escolha), sem metas irreais; e <strong>articulação com os programas sociais locais</strong>: cadastro único e benefícios, CRAS, restaurante popular, cozinhas comunitárias, banco de alimentos, agricultura familiar e o Programa de Aquisição de Alimentos. O impacto clínico imediato é limitado, e mesmo assim essa é a prioridade, porque sem comida regular não há dieta possível.</p>
<p>A avaliação da insegurança alimentar (escala EBIA ou o rastreio de duas perguntas) deve fazer parte da consulta; o cuidado inclui rastreamento de anemia e de carências, atenção à saúde mental e ao sono, e seguimento com vínculo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>A pergunta "nos últimos três meses, os alimentos acabaram antes de você ter dinheiro para comprar mais?" muda a consulta. Se a resposta é sim, o plano começa pelo CRAS e pela cozinha comunitária, e a orientação alimentar respeita o prato que existe, não o que a diretriz idealiza.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Insegurança alimentar é determinante da obesidade e coexiste com carências.</li>
<li>Prioridade: mudanças graduais e articulação com programas sociais, mesmo com impacto inicial limitado.</li>
<li>Guia Alimentar: comida de verdade, feita em casa, o que a região produz.</li>
<li>Rastrear insegurança alimentar, anemia, saúde mental; fármaco e cirurgia pelos critérios habituais.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a dieta hipocalórica detalhada não é a resposta na insegurança alimentar? <details><summary>Resposta</summary>Porque a causa é a falta de acesso regular a alimentos; a prescrição ignora o determinante e gera culpa e abandono.</details></li>
<li>Que ações intersetoriais o médico de família pode acionar? <details><summary>Resposta</summary>CRAS e cadastro único, cozinhas comunitárias, banco de alimentos, agricultura familiar, creche e escola integral.</details></li>
</ol>
`,
"einstein2026#75": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir teleinterconsulta e as outras modalidades de telemedicina do CFM.</li>
<li>Explicar a responsabilidade solidária dos médicos envolvidos.</li>
<li>Conhecer os deveres de registro, consentimento e sigilo.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Teleinterconsulta</dt>
<dd>Troca de informações e opiniões entre médicos, com ou sem o paciente, para auxílio diagnóstico ou terapêutico.</dd>
<dt>Teleconsulta</dt>
<dd>Consulta a distância entre médico e paciente, mediada por tecnologia.</dd>
<dt>Responsabilidade solidária</dt>
<dd>Cada médico responde pela qualidade do atendimento dentro de sua esfera de atuação.</dd>
<dt>Registro em prontuário</dt>
<dd>Dever de documentar a teleinterconsulta, com identificação dos médicos e conteúdo das orientações.</dd>
</dl>
<h4>O essencial</h4>
<p>A Resolução CFM 2.314/2022 e a Lei 14.510/2022 consolidaram a telemedicina no Brasil e definiram suas modalidades: <strong>teleconsulta</strong> (médico e paciente), <strong>teleinterconsulta</strong> (médico e médico, com ou sem a presença do paciente), telediagnóstico (laudo a distância), telecirurgia, teletriagem, telemonitoramento e teleconsultoria. Na teleinterconsulta, o médico assistente que está com o paciente pede a opinião de outro, em geral especialista, e recebe orientações para a conduta.</p>
<p>A responsabilidade nessa relação é <strong>compartilhada e solidária</strong>: o médico que <strong>assiste</strong> o paciente continua responsável pela decisão clínica, pela execução e pelo cuidado presencial; o médico <strong>consultado</strong> responde pelas orientações que deu, com base nas informações que recebeu. Nenhum dos dois transfere ao outro a totalidade da responsabilidade: o plantonista não pode dizer "só segui o cardiologista", nem o cardiologista "não estava lá". <strong>Cada um responde dentro de sua esfera de atuação</strong>, e a qualidade da informação trocada é dever dos dois.</p>
<p>Daí decorrem os deveres práticos: <strong>registrar em prontuário</strong> a teleinterconsulta, com data, hora, identificação e CRM do médico consultado e as orientações recebidas; obter o <strong>consentimento</strong> do paciente quando sua identificação ou imagem forem compartilhadas; garantir <strong>sigilo</strong> e segurança dos dados (plataforma adequada, não conversas informais em aplicativos sem registro); e manter a possibilidade de atendimento presencial quando necessário. A teleinterconsulta é instrumento de qualificação da rede, com telerregulação e apoio a municípios do interior, e não substitui a transferência quando indicada.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na suspeita de infarto no interior, ligue para a referência, mas escreva no prontuário quem atendeu, o que orientou e a hora; a orientação recebida é sua para executar e do consultor para responder. Áudio de aplicativo sem registro não protege o paciente nem os dois médicos.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Teleinterconsulta: médico consulta médico, com ou sem o paciente (CFM 2.314/2022).</li>
<li>Responsabilidade solidária: assistente decide e executa; consultado responde pelas orientações.</li>
<li>Registrar em prontuário com identificação, CRM e conteúdo; consentimento e sigilo.</li>
<li>Não substitui transferência quando indicada.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quem responde pela conduta numa teleinterconsulta? <details><summary>Resposta</summary>Ambos, de forma solidária: o assistente pela decisão e execução, o consultado pelas orientações, cada um em sua esfera.</details></li>
<li>O que deve constar no prontuário? <details><summary>Resposta</summary>Data, hora, identificação e CRM do médico consultado e as orientações recebidas.</details></li>
</ol>
`,
"einstein2025#61": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer os sinais de alarme da dengue e classificar o paciente em grupos A, B, C e D.</li>
<li>Iniciar a reposição volêmica intravenosa do grupo C na própria unidade.</li>
<li>Conhecer o fluxo: hidratação, hematócrito, transferência e retorno.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Sinais de alarme</dt>
<dd>Dor abdominal intensa, vômitos persistentes, acúmulo de líquidos, sangramento de mucosas, letargia, hepatomegalia, aumento do hematócrito com queda de plaquetas.</dd>
<dt>Fase crítica</dt>
<dd>Do 3º ao 7º dia, quando a febre cede e o extravasamento plasmático pode levar ao choque.</dd>
<dt>Grupo C</dt>
<dd>Dengue com sinal de alarme, sem choque: hidratação venosa imediata e observação em leito.</dd>
<dt>Grupo D</dt>
<dd>Dengue grave: choque, sangramento grave ou disfunção de órgão; terapia intensiva.</dd>
</dl>
<h4>O essencial</h4>
<p>O manejo da dengue é guiado pela <strong>classificação de risco</strong> e não pelo diagnóstico laboratorial. <strong>Grupo A</strong>: sem sinais de alarme, sem comorbidade ou risco social; hidratação oral em casa, com orientação dos sinais de alarme e retorno. <strong>Grupo B</strong>: sem sinais de alarme, mas com sangramento de pele ou condição especial (gestante, extremos de idade, comorbidades); hidratação oral supervisionada na unidade e hemograma. <strong>Grupo C</strong>: <strong>sinal de alarme presente</strong>; <strong>reposição venosa imediata</strong>, 10 mL/kg de soro fisiológico ou Ringer na primeira hora, repetida até três vezes conforme a resposta, hematócrito antes e depois, e <strong>internação em leito de observação por ao menos 48 horas</strong>. <strong>Grupo D</strong>: choque ou gravidade; 20 mL/kg em 20 minutos, repetido, e terapia intensiva.</p>
<p>Os sinais de alarme marcam o início do <strong>extravasamento plasmático</strong> da fase crítica, quando a febre cede: <strong>dor abdominal intensa e contínua</strong>, vômitos persistentes, acúmulo de líquidos (ascite, derrame pleural), sangramento de mucosas, letargia ou irritabilidade, hipotensão postural, hepatomegalia e aumento progressivo do hematócrito. Um só sinal já define o grupo C.</p>
<p>A regra que salva vidas é que o <strong>grupo C começa o soro venoso onde está</strong>, inclusive na unidade básica, e só depois é transferido para a unidade de referência com leito e laboratório, com o acesso venoso e a hidratação em curso. Esperar a transferência para hidratar é o erro que leva ao choque. Anti-inflamatórios e ácido acetilsalicílico são contraindicados; a analgesia é com dipirona ou paracetamol. Notificação compulsória.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Febre há 4 dias, manchas na pele e dor abdominal intensa que começou quando a febre baixou: não é "melhora", é a fase crítica. Puncione, corra 10 mL/kg de soro na primeira hora, colha o hematócrito e chame a transferência com o soro correndo.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>A: sem alarme, oral em casa; B: risco especial, oral na unidade com hemograma.</li>
<li>C: sinal de alarme, soro venoso 10 mL/kg/h imediato, hematócrito, leito por 48 horas.</li>
<li>D: choque, 20 mL/kg em 20 minutos, terapia intensiva.</li>
<li>Grupo C inicia a hidratação venosa na unidade antes de transferir; sem anti-inflamatório.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que sinais definem o grupo C? <details><summary>Resposta</summary>Qualquer sinal de alarme: dor abdominal intensa, vômitos persistentes, acúmulo de líquidos, sangramento de mucosas, letargia, hepatomegalia ou hematócrito em ascensão.</details></li>
<li>Onde começa a hidratação venosa do grupo C? <details><summary>Resposta</summary>Na unidade onde o paciente está, antes da transferência, com 10 mL/kg na primeira hora.</details></li>
</ol>
`,
"einstein2025#62": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer a Política Nacional para a População em Situação de Rua e o Consultório na Rua.</li>
<li>Garantir o vínculo com a unidade básica do território sem exigências que excluem.</li>
<li>Articular assistência social e sociedade civil para o pré-natal da gestante em situação de rua.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>População em situação de rua</dt>
<dd>Grupo heterogêneo em pobreza extrema, com vínculos familiares fragilizados, que usa logradouros públicos como moradia.</dd>
<dt>Consultório na Rua</dt>
<dd>Equipe multiprofissional itinerante da atenção primária que atende no local onde as pessoas vivem.</dd>
<dt>Cadastro sem endereço</dt>
<dd>O cadastro na unidade básica não exige comprovante de residência; usa-se o endereço de referência.</dd>
<dt>Redução de danos</dt>
<dd>Estratégia de cuidado que não condiciona o atendimento à abstinência.</dd>
</dl>
<h4>O essencial</h4>
<p>O Decreto 7.053/2009 instituiu a Política Nacional para a População em Situação de Rua com os princípios de dignidade, universalidade e <strong>acesso sem exigências</strong>; a Portaria 122/2011 criou as equipes de <strong>Consultório na Rua</strong>, que fazem busca ativa, acolhimento e cuidado no território, com redução de danos, e que são parte da atenção primária, vinculadas a uma unidade básica. O cadastro no SUS e na unidade <strong>não exige comprovante de residência</strong> nem documento: registra-se o endereço de referência (o viaduto, a praça, o serviço de acolhimento).</p>
<p>Uma gestante de 18 anos vivendo sob um viaduto tem direito ao <strong>pré-natal completo</strong>, e a conduta é <strong>cadastrá-la na unidade básica mais próxima do lugar onde dorme</strong>, garantindo que as consultas, os exames e as vacinas aconteçam ali ou pela equipe de rua, com a caderneta em mãos; <strong>acionar a assistência social</strong> (CREAS, Centro POP, serviços de acolhimento para gestantes e mães, cadastro único e benefícios); e <strong>buscar parcerias</strong> com organizações da sociedade civil, abrigos, casas de passagem e a maternidade de referência para sustentar a adesão.</p>
<p>O que expulsa: exigir documento, endereço fixo, acompanhante, horário rígido, abstinência ou "passar antes" por outro serviço. O vínculo com uma equipe, o horário flexível, a busca ativa quando falta e a articulação com a maternidade são o que faz a gestante em situação de rua chegar ao parto acompanhada e com o bebê protegido.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na visita sob o viaduto, o pré-natal começa ali: cartão da gestante, exames colhidos no local ou agendados com a equipe de rua, vacinas, e o combinado de onde ela pode encontrar a equipe. A pergunta "você tem documento?" vem depois, e a resposta "não" não muda nada.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Política Nacional (2009) e Consultório na Rua (2011): acesso sem exigências, cuidado no território.</li>
<li>Cadastro na unidade básica do local onde dorme, sem comprovante de residência.</li>
<li>Assistência social e sociedade civil para sustentar a adesão ao pré-natal.</li>
<li>Redução de danos; nada de condicionar o cuidado a documento, endereço ou abstinência.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O cadastro da gestante em situação de rua exige comprovante de residência? <details><summary>Resposta</summary>Não; registra-se o endereço de referência do local onde ela vive.</details></li>
<li>Quais parceiros sustentam a adesão ao pré-natal? <details><summary>Resposta</summary>Assistência social (Centro POP, CREAS, acolhimento), sociedade civil, a maternidade de referência e a equipe de Consultório na Rua.</details></li>
</ol>
`,
"einstein2025#63": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a violência patrimonial entre as formas de violência doméstica da Lei Maria da Penha.</li>
<li>Adotar a postura do profissional: nomear, informar direitos e planejar com a mulher.</li>
<li>Evitar minimizar, delegar ou decidir pela paciente.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Violência patrimonial</dt>
<dd>Reter, subtrair ou destruir bens, documentos, salário ou recursos da mulher, ou controlar seu dinheiro.</dd>
<dt>Formas de violência (art. 7º)</dt>
<dd>Física, psicológica, sexual, patrimonial e moral, pela Lei 11.340/2006.</dd>
<dt>Medidas protetivas de urgência</dt>
<dd>Determinações judiciais como afastamento do agressor e restituição de bens, solicitadas na delegacia ou no juizado.</dd>
<dt>Plano de segurança</dt>
<dd>Estratégias combinadas com a mulher para reduzir riscos, no ritmo dela.</dd>
</dl>
<h4>O essencial</h4>
<p>A Lei Maria da Penha define cinco formas de violência doméstica e familiar contra a mulher, e a <strong>patrimonial</strong> é a menos reconhecida: reter o salário, controlar o dinheiro, impedir de trabalhar, destruir objetos, esconder documentos, contrair dívidas em nome dela. Costuma vir junto da psicológica (humilhação, ameaça, isolamento) e antecede a física. Uma mulher que trabalha, mas cujo salário é retido pelo marido e que precisa pedir dinheiro para necessidades básicas, vive violência patrimonial, ainda que não haja agressão.</p>
<p>Quando a mulher revela, a postura do profissional tem três movimentos. <strong>Nomear</strong>: dizer que aquilo é violência patrimonial, prevista em lei, e que não é normal nem culpa dela; muitas nunca ouviram esse nome e o reconhecimento é terapêutico. <strong>Informar direitos</strong>: a Lei Maria da Penha, as medidas protetivas (inclusive restituição de bens e proibição de atos que prejudiquem o patrimônio), a Defensoria Pública, os centros de referência, a delegacia especializada, a rede de assistência social. <strong>Planejar junto</strong>: perguntar o que ela quer, avaliar risco (escalada, ameaças, armas), construir um plano de segurança e marcar retorno, respeitando o tempo dela. A <strong>notificação</strong> ao SINAN é obrigatória e sigilosa, e não depende da vontade da paciente de denunciar.</p>
<p>O que não fazer: minimizar ("problema de casal"), delegar ("procure a delegacia" e encerrar), pressionar por denúncia, prescrever ansiolítico como resposta, ou tratar apenas a dor nas costas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>A frase "o que você descreve tem nome: é violência patrimonial, e a lei protege você" costuma ser a primeira vez que a mulher ouve que não está exagerando. Depois dela vêm os contatos escritos da rede, a pergunta sobre risco e o retorno em duas semanas.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Violência patrimonial: reter salário, controlar dinheiro, destruir bens, esconder documentos.</li>
<li>Nomear, informar direitos (Maria da Penha, medidas protetivas, Defensoria, rede), planejar junto.</li>
<li>Notificar ao SINAN; avaliar risco; respeitar o tempo da mulher.</li>
<li>Não minimizar, não delegar, não decidir por ela, não medicalizar.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Reter o salário da esposa é que forma de violência pela Lei Maria da Penha? <details><summary>Resposta</summary>Violência patrimonial, prevista no artigo 7º.</details></li>
<li>Qual é a postura do profissional diante da revelação? <details><summary>Resposta</summary>Nomear a violência, informar os direitos e a rede, e planejar com a mulher, com notificação e avaliação de risco.</details></li>
</ol>
`,
"einstein2025#66": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Indicar a profilaxia pré-exposição ao HIV no adolescente a partir de 15 anos e 35 kg.</li>
<li>Distinguir PrEP de PEP: janela, duração e indicações.</li>
<li>Respeitar a autonomia e o sigilo do adolescente na prevenção combinada.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PrEP</dt>
<dd>Profilaxia pré-exposição: tenofovir com entricitabina diário (ou sob demanda em homens cis) para quem tem risco continuado.</dd>
<dt>PEP</dt>
<dd>Profilaxia pós-exposição: antirretrovirais por 28 dias, iniciados em até 72 horas da exposição.</dd>
<dt>Prevenção combinada</dt>
<dd>Preservativo, testagem regular, PrEP, PEP, tratamento como prevenção, vacinas e redução de danos.</dd>
<dt>Autonomia do adolescente</dt>
<dd>Direito a atendimento sem acompanhante e a sigilo, previsto no ECA e nos protocolos do Ministério.</dd>
</dl>
<h4>O essencial</h4>
<p>O protocolo brasileiro de <strong>PrEP</strong> (2022) indica a profilaxia a pessoas com risco continuado de infecção pelo HIV: homens que fazem sexo com homens, pessoas trans, trabalhadores do sexo, parcerias sorodiferentes e qualquer pessoa com práticas de risco frequentes, uso irregular de preservativo, infecções sexualmente transmissíveis recentes ou uso repetido de PEP. A idade mínima é <strong>15 anos</strong>, com <strong>peso de 35 kg ou mais</strong>, e o adolescente pode iniciar sem autorização dos responsáveis, com sigilo garantido. Antes da primeira dose: teste de HIV negativo, creatinina, sorologias de hepatites e sífilis; depois, retorno em 30 dias e a cada 3 meses com testagem. A PrEP diária protege após 7 dias de uso; a PrEP sob demanda (2+1+1) é opção para homens cisgênero.</p>
<p>A <strong>PEP</strong> é para a exposição que já aconteceu: iniciada em até <strong>72 horas</strong> (quanto antes, melhor), por <strong>28 dias</strong>, com tenofovir, lamivudina e dolutegravir. Quem precisa de PEP repetidamente é candidato à PrEP. Nenhuma das duas substitui o preservativo, que protege das outras infecções, nem a testagem regular; a <strong>prevenção combinada</strong> soma tudo, incluindo vacinas (hepatite B, HPV, meningocócica quando indicada) e tratamento das parcerias.</p>
<p>O adolescente de 16 anos, homoafetivo, sexualmente ativo, que pede orientação, tem indicação de PrEP e direito de recebê-la naquela consulta, com aconselhamento, preservativos e testagem, sem exigir a presença dos pais e sem condicionar a prevenção à abstinência.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Adolescente que procura sozinho orientação sobre HIV recebe teste, preservativo e PrEP no mesmo dia, com sigilo, e sai com o retorno de 30 dias marcado. Mandar chamar os pais ou "voltar aos 18" é perder a única consulta em que ele veio.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>PrEP: risco continuado; a partir de 15 anos e 35 kg; teste negativo antes; retorno trimestral.</li>
<li>PEP: até 72 horas, 28 dias; uso repetido indica PrEP.</li>
<li>Prevenção combinada: preservativo, testagem, PrEP, PEP, vacinas.</li>
<li>Adolescente: atendimento sem acompanhante e com sigilo.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os critérios de idade e peso para a PrEP? <details><summary>Resposta</summary>15 anos ou mais e 35 kg ou mais.</details></li>
<li>Qual é a janela e a duração da PEP? <details><summary>Resposta</summary>Início em até 72 horas da exposição e 28 dias de antirretrovirais.</details></li>
</ol>
`,
"einstein2025#68": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Graduar a síndrome de abstinência alcoólica e reconhecer os sinais de gravidade.</li>
<li>Tratar a abstinência leve a moderada no CAPS com benzodiazepínico e tiamina.</li>
<li>Saber o que o CAPS faz: acolhe e trata, sem exigir encaminhamento prévio.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Síndrome de abstinência alcoólica</dt>
<dd>Tremor, sudorese, ansiedade, insônia, náuseas e taquicardia de 6 a 24 horas após reduzir ou parar o álcool.</dd>
<dt>Delirium tremens</dt>
<dd>Forma grave, de 48 a 72 horas: confusão, alucinações, agitação, febre, instabilidade; risco de morte.</dd>
<dt>Tiamina</dt>
<dd>Vitamina B1, dada antes da glicose, para prevenir a encefalopatia de Wernicke.</dd>
<dt>CAPS AD</dt>
<dd>Centro de Atenção Psicossocial para álcool e outras drogas, porta aberta e cuidado no território.</dd>
</dl>
<h4>O essencial</h4>
<p>A abstinência alcoólica surge de 6 a 24 horas após a última dose, com tremor, sudorese, taquicardia, ansiedade, insônia e náuseas; pode evoluir para convulsões (24 a 48 horas) e para o <strong>delirium tremens</strong> (48 a 72 horas). A gravidade se gradua pela clínica e por escalas como a CIWA-Ar: <strong>leve a moderada</strong> (sinais autonômicos sem confusão, sem convulsão, sem comorbidade descompensada) pode ser tratada <strong>ambulatorialmente</strong>, com observação por algumas horas e rede de apoio; grave, com história de delirium ou convulsão, comorbidade clínica, gestação ou ausência de suporte, exige internação.</p>
<p>O tratamento da abstinência leve a moderada é <strong>benzodiazepínico</strong> (diazepam 10 mg até de 8 em 8 horas, com redução ao longo de uma semana; lorazepam se hepatopatia), <strong>tiamina 100 mg</strong> intramuscular por 5 dias (antes de qualquer glicose, para não precipitar Wernicke), hidratação e correção de eletrólitos, e <strong>orientação dos sinais de alarme</strong> (confusão, alucinações, febre, convulsão) com <strong>retorno breve</strong>, em 24 a 48 horas.</p>
<p>O <strong>CAPS AD</strong> é um serviço de <strong>porta aberta</strong> da Rede de Atenção Psicossocial: acolhe quem chega, faz a avaliação, trata a abstinência que não exige internação e constrói o projeto terapêutico singular, com a atenção primária como parceira. Não é preciso passar antes pela unidade básica nem pelo pronto-socorro; quem precisa de leito vai ao hospital geral ou ao CAPS III com acolhimento noturno. A mulher desempregada, mãe, que bebe desde os 16 anos e pede ajuda, é acolhida ali e sai com tratamento, tiamina, rede de apoio mapeada e retorno marcado.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quem chega ao CAPS pedindo para parar de beber não ouve "volte com encaminhamento". Observe algumas horas, meça a gravidade, dê a tiamina antes do soro glicosado, prescreva o diazepam com esquema de redução e marque a volta em dois dias. A janela de motivação é curta.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Abstinência: 6 a 24 horas; convulsões 24 a 48; delirium tremens 48 a 72.</li>
<li>Leve a moderada: diazepam até 10 mg de 8/8 horas com redução, tiamina 100 mg IM por 5 dias, retorno breve.</li>
<li>Internar: grave, história de delirium ou convulsão, comorbidade, gestação, sem suporte.</li>
<li>CAPS AD é porta aberta: acolhe e trata sem encaminhamento prévio.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a tiamina vem antes da glicose? <details><summary>Resposta</summary>Para não precipitar a encefalopatia de Wernicke em quem tem deficiência de B1.</details></li>
<li>O CAPS pode tratar a abstinência leve sem encaminhamento da unidade básica? <details><summary>Resposta</summary>Sim; é serviço de porta aberta que acolhe, avalia e trata, com a atenção primária como parceira.</details></li>
</ol>
`,
"einstein2025#69": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Listar as características de um ensaio clínico randomizado bem conduzido.</li>
<li>Explicar o que a randomização entrega e como o sigilo da alocação e o cegamento a protegem.</li>
<li>Entender a análise por intenção de tratar e as perdas de seguimento.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Randomização</dt>
<dd>Alocação por sorteio, que distribui confundidores conhecidos e desconhecidos entre os grupos.</dd>
<dt>Sigilo da alocação</dt>
<dd>Quem inclui o paciente não sabe a que grupo ele irá; evita seleção manipulada.</dd>
<dt>Cegamento</dt>
<dd>Paciente, equipe e avaliador sem saber o tratamento; evita vieses de desempenho e de aferição.</dd>
<dt>Intenção de tratar</dt>
<dd>Analisar cada paciente no grupo em que foi sorteado, mesmo que não tenha seguido o tratamento.</dd>
</dl>
<h4>O essencial</h4>
<p>O ensaio clínico randomizado é o padrão para avaliar tratamentos porque a <strong>randomização</strong> produz grupos <strong>comparáveis no ponto de partida</strong>: se o sorteio funcionou, as características basais (idade, gravidade, comorbidades, tudo o que se mede e o que não se mede) ficam distribuídas de forma semelhante, e a única diferença sistemática entre os grupos é o tratamento. A tabela 1 de todo ensaio existe para mostrar isso; grupos basais parecidos são a evidência de que a randomização foi bem feita e de que a comparação é justa.</p>
<p>A randomização precisa ser protegida. O <strong>sigilo da alocação</strong> (envelopes opacos, central telefônica ou eletrônica) impede que quem recruta escolha, consciente ou não, quem vai para cada braço. O <strong>cegamento</strong> de pacientes, equipe e avaliadores de desfecho impede que expectativas mudem o cuidado ou a medida do resultado, sobretudo em desfechos subjetivos. O <strong>seguimento completo</strong>, com perdas pequenas e semelhantes entre os grupos, evita que as perdas desfaçam o equilíbrio inicial. A <strong>análise por intenção de tratar</strong> mantém cada paciente no grupo sorteado, ainda que tenha trocado ou abandonado o tratamento, porque analisar só quem aderiu reintroduz a seleção que a randomização eliminou. Somam-se o registro prévio do protocolo, o tamanho de amostra calculado, o desfecho primário definido de antemão e o relato pelo CONSORT.</p>
<p>Os sinais de má condução: diferenças basais importantes, alocação por dia da semana ou prontuário, sem cegamento quando era possível, perdas grandes ou desiguais, análise por protocolo apresentada como principal, desfechos trocados após ver os dados e término precoce por benefício sem regra prévia.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao ler um ensaio, vá primeiro à tabela 1 e ao fluxograma: grupos parecidos no início e poucos perdidos no fim dizem mais sobre a confiabilidade do que o valor de p. Depois, pergunte se a análise foi por intenção de tratar.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Randomização entrega grupos comparáveis no início; a tabela 1 comprova.</li>
<li>Sigilo da alocação e cegamento protegem contra seleção e aferição enviesadas.</li>
<li>Seguimento completo e análise por intenção de tratar preservam o equilíbrio.</li>
<li>Protocolo registrado, desfecho primário prévio, relato CONSORT.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que indica que a randomização funcionou? <details><summary>Resposta</summary>Grupos semelhantes nas características basais no início do estudo.</details></li>
<li>Por que analisar por intenção de tratar? <details><summary>Resposta</summary>Para manter a comparabilidade criada pelo sorteio; analisar só quem aderiu reintroduz seleção.</details></li>
</ol>
`,
"einstein2025#70": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Distinguir revisão sistemática de meta-análise e de revisão narrativa.</li>
<li>Explicar a ponderação dos estudos pela precisão na estimativa sumária.</li>
<li>Interpretar heterogeneidade, modelos de efeito e viés de publicação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Revisão sistemática</dt>
<dd>Síntese com pergunta definida, busca exaustiva, critérios explícitos e avaliação do risco de viés dos estudos.</dd>
<dt>Meta-análise</dt>
<dd>Combinação estatística dos resultados dos estudos numa estimativa única, ponderada.</dd>
<dt>Heterogeneidade (I²)</dt>
<dd>Variação entre os estudos além do acaso; alta quando I² passa de 50 a 75%.</dd>
<dt>Gráfico de funil</dt>
<dd>Dispersão dos estudos por precisão; assimetria sugere viés de publicação.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>revisão sistemática</strong> é um método: pergunta estruturada (PICO), protocolo registrado, busca em várias bases sem restrição de idioma, seleção por dois revisores, extração padronizada e avaliação do risco de viés de cada estudo; o relato segue o PRISMA. Ela pode ou não terminar em <strong>meta-análise</strong>, que é a etapa estatística: combinar os resultados numa <strong>estimativa sumária</strong>. Uma revisão narrativa, sem busca sistemática nem critérios explícitos, não é nenhuma das duas. Uma meta-análise de estudos com alto risco de viés produz uma estimativa precisa e enviesada.</p>
<p>Na meta-análise, os estudos não contam igual: cada um recebe um <strong>peso proporcional à sua precisão</strong>, em geral o inverso da variância, de modo que estudos maiores, com intervalos de confiança estreitos, pesam mais, e estudos pequenos pesam menos. O gráfico de floresta mostra cada estudo com seu peso e a estimativa combinada em losango. O <strong>modelo de efeito fixo</strong> assume um único efeito verdadeiro; o de <strong>efeitos aleatórios</strong> admite que o efeito varia entre estudos e é preferido quando há heterogeneidade. A <strong>heterogeneidade</strong> se mede pelo I² e pelo teste Q, e se explora por análises de subgrupo e meta-regressão; heterogeneidade alta não impede a meta-análise, mas exige explicação.</p>
<p>O <strong>viés de publicação</strong> (estudos negativos não publicados) é avaliado pelo gráfico de funil e por testes de assimetria, e é reduzido pela busca em registros de ensaios e na literatura cinzenta. A qualidade do conjunto da evidência é graduada pelo GRADE. Em resumo: a revisão sistemática responde "o que existe e quão confiável é"; a meta-análise responde "qual é o efeito combinado, com que precisão".</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>No gráfico de floresta, olhe o tamanho dos quadrados antes do losango: o estudo grande que domina o peso pode ser o que decide o resultado. Depois olhe o I²; um losango estreito com I² de 90% é uma média de estudos que não concordam entre si.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Revisão sistemática: método explícito e reprodutível; meta-análise: síntese estatística.</li>
<li>Cada estudo pesa conforme a sua precisão (inverso da variância).</li>
<li>Efeitos aleatórios com heterogeneidade; I² mede; subgrupos exploram.</li>
<li>Gráfico de funil para viés de publicação; GRADE para a qualidade da evidência.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Como a meta-análise combina os estudos? <details><summary>Resposta</summary>Ponderando cada estudo pela sua precisão, com maior peso para os maiores e mais precisos.</details></li>
<li>Toda revisão sistemática tem meta-análise? <details><summary>Resposta</summary>Não; a meta-análise é a etapa estatística opcional, feita quando os estudos são combináveis.</details></li>
</ol>
`,

/* --- Volume 2 · Preventiva · Sírio-Libanês 2026 (prev51–prev65) --------------------------- */
"sirio2026#81": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Situar a Declaração de Alma-Ata no tempo e no seu conteúdo central.</li>
<li>Distinguir Alma-Ata dos relatórios Flexner, Lalonde e Black e da Carta de Ottawa.</li>
<li>Reconhecer a herança de Alma-Ata na Constituição de 1988 e na Estratégia Saúde da Família.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Alma-Ata (1978)</dt>
<dd>Conferência da OMS e do UNICEF que definiu os cuidados primários de saúde como estratégia para "Saúde para Todos no Ano 2000".</dd>
<dt>Relatório Flexner (1910)</dt>
<dd>Reforma do ensino médico norte-americano centrada no hospital e nas ciências básicas; símbolo do modelo biomédico.</dd>
<dt>Relatório Lalonde (1974)</dt>
<dd>Documento canadense que criou o "campo da saúde" (biologia, ambiente, estilo de vida, serviços) e inaugurou a promoção da saúde.</dd>
<dt>Relatório Black (1980)</dt>
<dd>Estudo britânico que documentou as desigualdades sociais em saúde e sua persistência apesar do NHS.</dd>
<dt>Carta de Ottawa (1986)</dt>
<dd>Primeira conferência internacional de promoção da saúde: cinco campos de ação, da política pública saudável à reorientação dos serviços.</dd>
</dl>
<h4>O essencial</h4>
<p>Em setembro de 1978, em Alma-Ata, então União Soviética, 134 países assinaram a declaração que afirmou a saúde como <strong>direito humano fundamental</strong>, denunciou a desigualdade entre países e dentro deles como inaceitável e propôs os <strong>cuidados primários de saúde</strong> como a estratégia para alcançar "Saúde para Todos no Ano 2000".</p>
<p>O contexto explica o alcance. Flexner (1910) havia moldado uma medicina hospitalar e especializada que, nos anos 1970, se mostrava cara e incapaz de reduzir as desigualdades. Lalonde (1974) mostrou que o gasto assistencial comprava pouca saúde diante do estilo de vida e do ambiente. Alma-Ata propôs inverter a pirâmide: investir na base, nos cuidados primários, e organizar o sistema a partir dela.</p>
<p>Depois vieram o Relatório Black (1980), sobre desigualdades mesmo com acesso universal, e a Carta de Ottawa (1986), que deslocou o foco para a promoção da saúde: políticas públicas saudáveis, ambientes favoráveis, ação comunitária, habilidades pessoais e reorientação dos serviços.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na prova, cada documento tem uma palavra-chave: Alma-Ata é "cuidados primários" e "Saúde para Todos"; Flexner é "ensino médico" e "hospital"; Lalonde é "campo da saúde" e "estilo de vida"; Black é "desigualdades"; Ottawa é "promoção da saúde". A OMS nasceu em 1948 com a definição de saúde como bem-estar completo, não com a APS.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Alma-Ata (1978): saúde como direito, cuidados primários como estratégia, meta Saúde para Todos no Ano 2000.</li>
<li>Flexner (1910) é o modelo biomédico; Lalonde (1974), o campo da saúde; Black (1980), as desigualdades; Ottawa (1986), a promoção.</li>
<li>APS abrangente versus seletiva: o debate que nasceu logo depois de Alma-Ata.</li>
<li>No Brasil, a 8ª Conferência, a Constituição de 1988 e a ESF descendem de Alma-Ata.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que documento criou o conceito de "campo da saúde" e inaugurou a promoção da saúde? <details><summary>Resposta</summary>O Relatório Lalonde, do Canadá, em 1974.</details></li>
<li>Qual é o lema associado à Declaração de Alma-Ata? <details><summary>Resposta</summary>"Saúde para Todos no Ano 2000", a ser alcançada pelos cuidados primários de saúde.</details></li>
<li>O que diferencia a APS abrangente da APS seletiva? <details><summary>Resposta</summary>A abrangente organiza todo o sistema a partir do primeiro nível, com participação e intersetorialidade; a seletiva oferece pacotes mínimos e verticais de intervenções.</details></li>
</ol>
`,

"sirio2026#82": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever os principais modelos explicativos do processo saúde-doença.</li>
<li>Reconhecer a tríade ecológica e a história natural da doença de Leavell e Clark.</li>
<li>Identificar o modelo em uso a partir das pistas de um caso clínico.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Modelo biomédico</dt>
<dd>A doença é lesão ou agente etiológico no corpo; o foco é o diagnóstico e o tratamento individual.</dd>
<dt>Tríade ecológica</dt>
<dd>Agente, hospedeiro e ambiente em interação; a doença resulta do desequilíbrio entre os três.</dd>
<dt>História natural da doença</dt>
<dd>Curso da doença sem intervenção, do período pré-patogênico ao desfecho, base dos níveis de prevenção de Leavell e Clark.</dd>
<dt>Determinação social</dt>
<dd>Modelo em que a estrutura da sociedade (classe, trabalho, renda) produz os perfis de saúde e doença dos grupos.</dd>
</dl>
<h4>O essencial</h4>
<p>Cada época e cada grupo explicam a doença de um modo, e a Saúde Coletiva organiza essas explicações em <strong>modelos</strong>. O <strong>mágico-religioso</strong> atribui o adoecimento a forças sobrenaturais e castigos. O <strong>miasmático</strong>, dominante até o século XIX, culpava os ares e as emanações pútridas, e fundou o sanitarismo urbano. O <strong>biomédico</strong>, que nasceu com a bacteriologia de Pasteur e Koch e se consolidou com Flexner, vê a doença como lesão causada por um agente específico, e é ainda o modelo hegemônico da clínica.</p>
<p>O <strong>modelo ecológico</strong>, sistematizado por Leavell e Clark nos anos 1960, amplia o biomédico sem romper com ele: a doença é o resultado da interação de um <strong>agente</strong> (biológico, físico, químico), um <strong>hospedeiro</strong> suscetível (idade, nutrição, imunidade, hábitos) e um <strong>ambiente</strong> (físico, biológico e social). O equilíbrio entre os três é a saúde; o desequilíbrio, a doença. Esse modelo gerou a <strong>história natural da doença</strong>, com o período pré-patogênico e o patogênico, e os <strong>níveis de prevenção</strong>: primária (promoção e proteção específica), secundária (diagnóstico precoce e limitação do dano) e terciária (reabilitação).</p>
<p>O <strong>modelo da determinação social</strong>, da medicina social latino-americana (Laurell, Breilh), e o dos <strong>determinantes sociais</strong> (Dahlgren e Whitehead, Comissão da OMS) deslocam a causa para a estrutura social: classe, trabalho, renda, moradia, gênero e raça produzem os perfis de adoecimento. O <strong>histórico-cultural</strong> enfatiza que a própria noção de doença varia com a cultura e a época. Na prática, os modelos coexistem: a equipe trata a pneumonia (biomédico), avalia agente, criança e casa (ecológico) e aciona a assistência social para a moradia (social).</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na prova, "agente, hospedeiro e ambiente" é ecológico; "classe, trabalho, renda" é social; "lesão e agente etiológico" é biomédico; "varia com a cultura" é histórico-cultural. A presença de fatores sociais dentro do "ambiente" não transforma o modelo em social: o que define o modelo é a lógica da explicação, não a lista de fatores.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Modelos: mágico-religioso, miasmático, biomédico, ecológico, social, histórico-cultural.</li>
<li>Ecológico (Leavell e Clark): tríade agente-hospedeiro-ambiente, história natural da doença, níveis de prevenção.</li>
<li>Social: a estrutura da sociedade determina os perfis de saúde e doença dos grupos.</li>
<li>Os modelos coexistem na prática; a prova pede o que melhor descreve o raciocínio do caso.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que modelo originou os níveis de prevenção primária, secundária e terciária? <details><summary>Resposta</summary>O modelo ecológico da história natural da doença, de Leavell e Clark.</details></li>
<li>Uma equipe explica a tuberculose de um bairro pela precarização do trabalho e pela renda das famílias. Que modelo usa? <details><summary>Resposta</summary>O modelo da determinação social da saúde.</details></li>
</ol>
`,

"sirio2026#83": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever as medidas de barreira para água de consumo contaminada.</li>
<li>Diferenciar vigilância ambiental da água, saneamento e vigilância epidemiológica da diarreia.</li>
<li>Saber o que é a Monitorização das Doenças Diarreicas Agudas e quando a diarreia se notifica.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Coliformes fecais (termotolerantes)</dt>
<dd>Bactérias indicadoras de contaminação fecal recente da água; a <em>Escherichia coli</em> é o marcador principal.</dd>
<dt>Vigiagua</dt>
<dd>Programa nacional de vigilância da qualidade da água para consumo humano, parte da vigilância em saúde ambiental.</dd>
<dt>MDDA</dt>
<dd>Monitorização das Doenças Diarreicas Agudas: registro agregado semanal dos casos atendidos nas unidades sentinela, para detectar surtos.</dd>
<dt>Desinfecção domiciliar</dt>
<dd>Fervura por 1 a 5 minutos (o enunciado da banca aceita 5 a 10) ou hipoclorito de sódio a 2,5%, duas gotas por litro, com 30 minutos de espera.</dd>
</dl>
<h4>O essencial</h4>
<p>A diarreia aguda infantil ligada a água sem tratamento é um problema de <strong>saneamento</strong>, e a vigilância em saúde ambiental cuida da interface entre ambiente e saúde: qualidade da água (Vigiagua), solo contaminado, ar, desastres e vetores. Quando a investigação encontra <strong>coliformes fecais</strong> na água de uso comum e famílias que a bebem sem tratar, a cadeia está exposta: fonte (fezes humanas ou animais no rio), veículo (água) e suscetíveis (crianças pequenas). A ação de proteção imediata é cortar o veículo no ponto de consumo.</p>
<p>As medidas se ordenam no tempo. <strong>Imediatas</strong> e individuais: ferver a água de beber e de cozinhar, ou desinfetar com hipoclorito de sódio a 2,5% (duas gotas por litro, aguardar 30 minutos), guardar em recipiente limpo e tampado, lavar as mãos. <strong>Intermediárias</strong>: distribuição de hipoclorito pela UBS e pelos agentes comunitários, educação em higiene e preparo de alimentos, soro de reidratação oral e zinco para os casos. <strong>Estruturais</strong>: abastecimento tratado, esgotamento sanitário, proteção da nascente, com prefeitura, companhia de saneamento e Ministério Público. Clorar o rio não é medida: a cloração se faz na água captada e armazenada, não no curso d'água.</p>
<p>No registro, a diarreia aguda individual não é agravo de notificação compulsória; os casos entram na <strong>MDDA</strong>, planilha semanal por faixa etária e plano de tratamento, cuja análise detecta o aumento inesperado. O que se notifica de imediato é o <strong>surto</strong> de doença diarreica aguda, e certas etiologias específicas, como cólera, febre tifoide e rotavírus em surto. Investigar o surto, coletar amostras clínicas e de água e devolver os resultados à comunidade fecham o ciclo da vigilância.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na consulta da criança com diarreia, a pergunta "de onde vem a água de casa?" vale tanto quanto o plano de hidratação. Água de poço, rio ou cisterna sem tratamento é indicação de orientar fervura ou hipoclorito na mesma consulta e de acionar o agente comunitário para o restante da microárea.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Água com coliformes e famílias que a bebem sem tratar: cortar o veículo no ponto de consumo, já.</li>
<li>Ferver ou hipoclorito a 2,5% (duas gotas por litro, 30 minutos) são as medidas provisórias; saneamento é a solução definitiva.</li>
<li>Não se clora o rio; clora-se a água captada e armazenada.</li>
<li>Diarreia individual vai à MDDA; surto de diarreia é notificação imediata.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Como se desinfeta água de beber em casa quando não é possível ferver? <details><summary>Resposta</summary>Hipoclorito de sódio a 2,5%, duas gotas por litro, aguardando 30 minutos antes de consumir.</details></li>
<li>A diarreia aguda de uma criança atendida na UBS é notificada no SINAN? <details><summary>Resposta</summary>Não; ela é registrada na MDDA. Notifica-se o surto de doença diarreica aguda e etiologias específicas, como cólera.</details></li>
</ol>
`,

"sirio2026#84": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir promoção da saúde segundo a Carta de Ottawa e a PNPS.</li>
<li>Distinguir promoção de prevenção primária, secundária e terciária.</li>
<li>Aplicar a distinção ao controle da dengue no território.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Promoção da saúde</dt>
<dd>Processo de capacitar pessoas e comunidades para aumentar o controle sobre os determinantes da sua saúde (Ottawa, 1986).</dd>
<dt>Proteção específica</dt>
<dd>Prevenção primária dirigida a um agravo: vacina, preservativo, tela na janela, caixa d'água vedada.</dd>
<dt>Prevenção secundária</dt>
<dd>Diagnóstico precoce e tratamento oportuno para limitar o dano: rastreamento, teste rápido, classificação de risco.</dd>
<dt>LIRAa</dt>
<dd>Levantamento Rápido de Índices para <em>Aedes aegypti</em>: amostragem de imóveis que estima a infestação e orienta as ações no território.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>promoção da saúde</strong> age sobre os determinantes e sobre a capacidade das pessoas de agir: não é dirigida a uma doença, mas à autonomia, às condições de vida e ao ambiente. A Carta de Ottawa lista cinco campos: políticas públicas saudáveis, ambientes favoráveis, reforço da ação comunitária, desenvolvimento de habilidades pessoais e reorientação dos serviços. A Política Nacional de Promoção da Saúde (2006, revista em 2014) traduz isso em temas prioritários: alimentação, atividade física, tabaco e álcool, cultura da paz, mobilidade segura, ambiente sustentável.</p>
<p>A <strong>prevenção</strong>, no modelo de Leavell e Clark, é dirigida à doença. A <strong>primária</strong> evita o aparecimento e inclui a <strong>proteção específica</strong>: vacinar, vedar caixas d'água, eliminar criadouros, telar janelas, usar repelente. A <strong>secundária</strong> detecta e trata cedo: teste rápido, classificação de risco, hidratação precoce que evita o choque. A <strong>terciária</strong> reabilita e limita sequelas.</p>
<p>Na dengue, o controle vetorial é a base: visita domiciliar dos agentes de endemias, eliminação mecânica de criadouros, larvicida onde não se pode eliminar, LIRAa para medir a infestação e dirigir as ações, e bloqueio com inseticida em casos confirmados. A vacina Qdenga, incorporada ao SUS em 2024 para a faixa de 10 a 14 anos em municípios prioritários, é proteção específica. A classificação de risco (grupos A a D) e a hidratação precoce são prevenção secundária, e reduzem a mortalidade mais que qualquer outra medida assistencial.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Para classificar uma ação na prova, pergunte a quem ela se dirige e o que faz: se aumenta a autonomia e age sobre determinantes, é promoção; se bloqueia um agravo específico, é proteção específica; se detecta ou trata cedo, é secundária; se reabilita, é terciária. "Palestra sobre alimentação" é promoção, mas não é promoção <em>relacionada à dengue</em>.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Promoção: autonomia e determinantes, não dirigida a uma doença (Ottawa, PNPS).</li>
<li>Prevenção primária e proteção específica: caixa d'água vedada, criadouros eliminados, vacina, repelente.</li>
<li>Prevenção secundária: teste, classificação de risco e hidratação precoce; terciária: reabilitação.</li>
<li>Dengue: controle vetorial com LIRAa e agentes de endemias, mais vacina Qdenga em grupos prioritários.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Distribuir repelente para gestantes em área de transmissão é promoção ou prevenção? <details><summary>Resposta</summary>Prevenção primária, proteção específica contra a picada do vetor.</details></li>
<li>Quais são os cinco campos de ação da Carta de Ottawa? <details><summary>Resposta</summary>Políticas públicas saudáveis, ambientes favoráveis, ação comunitária, habilidades pessoais e reorientação dos serviços de saúde.</details></li>
</ol>
`,

"sirio2026#85": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Afirmar o direito do migrante, regular ou não, ao SUS integral.</li>
<li>Reconhecer a criança em situação de risco e o dever de comunicar ao Conselho Tutelar.</li>
<li>Articular a Vigilância em Saúde do Trabalhador diante de um ambiente de trabalho insalubre.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Universalidade</dt>
<dd>Acesso de todas as pessoas às ações e serviços de saúde, sem exigência de documento, vínculo ou nacionalidade (CF, art. 196).</dd>
<dt>Lei de Migração (13.445/2017)</dt>
<dd>Garante ao migrante, independentemente da situação migratória, acesso a serviços públicos de saúde e assistência social.</dd>
<dt>Conselho Tutelar</dt>
<dd>Órgão municipal que zela pelos direitos da criança e do adolescente; recebe a comunicação de suspeita de violação de direitos (ECA, art. 13).</dd>
<dt>Trabalho infantil</dt>
<dd>Qualquer trabalho antes dos 14 anos; dos 14 aos 16, só como aprendiz; proibido em atividade insalubre antes dos 18.</dd>
</dl>
<h4>O essencial</h4>
<p>O SUS é <strong>universal</strong>: a Constituição diz "saúde é direito de todos", e a Lei de Migração (2017) acabou com qualquer dúvida sobre o estrangeiro, garantindo acesso aos serviços públicos de saúde "sem discriminação em razão da nacionalidade e da condição migratória". Comprovante de residência, CPF e documento de identidade servem para o cadastro e o Cartão SUS, que pode ser emitido com documentos do país de origem ou mesmo sem documento; nunca são condição para atender.</p>
<p>O caso traz uma criança de 6 anos que passa a jornada numa confecção úmida e empoeirada e adoece por isso. Isso é <strong>situação de risco</strong>: exposição a ambiente insalubre e, se ela ajuda nas tarefas, trabalho infantil. O ECA (art. 13) obriga os profissionais de saúde a comunicar ao <strong>Conselho Tutelar</strong> os casos de suspeita ou confirmação de maus-tratos e violação de direitos, e o Conselho aciona assistência social, educação e, se for o caso, Ministério Público e Justiça.</p>
<p>A confecção é também um <strong>ambiente de trabalho</strong>, frequentemente com migrantes em condições análogas à escravidão. A Vigilância em Saúde do Trabalhador (CEREST e vigilância municipal) inspeciona o local e articula o Ministério do Trabalho e o Ministério Público do Trabalho. A equipe de saúde da família faz a sua parte: trata a criança, notifica, articula e mantém o vínculo, explicando à família o que está fazendo e por quê.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Diante de família migrante, pergunte onde a criança passa o dia, se frequenta escola, onde os pais trabalham e quantas horas. Garanta vacinação, acompanhamento e medicação como a qualquer criança, e acione o Conselho Tutelar e a assistência social com a família informada: a notificação é dever profissional e não depende do consentimento dos pais.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Migrante irregular tem acesso integral ao SUS; documento é para cadastro, não para atender.</li>
<li>Criança em ambiente insalubre ou em trabalho é situação de risco: comunicar ao Conselho Tutelar (ECA, art. 13).</li>
<li>Ambiente de trabalho insalubre: Vigilância em Saúde do Trabalhador e articulação intersetorial.</li>
<li>Explicar à família e manter o vínculo; omitir a notificação deixa a criança no risco.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Uma UBS pode exigir CPF ou comprovante de residência para atender uma criança estrangeira? <details><summary>Resposta</summary>Não. Esses documentos servem ao cadastro; o atendimento é garantido pela universalidade e pela Lei de Migração.</details></li>
<li>A quem a equipe comunica a suspeita de que uma criança está em situação de risco? <details><summary>Resposta</summary>Ao Conselho Tutelar do município, por dever legal do ECA, com a família informada.</details></li>
</ol>
`,

"sirio2026#87": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Explicar o que a Lei 8.080 entende por participação complementar da iniciativa privada.</li>
<li>Distinguir setor complementar de setor suplementar.</li>
<li>Reconhecer as regras do contrato: direito público, preferência aos filantrópicos, gratuidade ao usuário.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Participação complementar</dt>
<dd>Contratação de serviços privados pelo SUS quando a rede pública é insuficiente, sob normas do SUS e sem cobrança ao usuário (Lei 8.080, art. 24).</dd>
<dt>Setor suplementar</dt>
<dd>Planos e seguros privados e o desembolso direto, regulados pela ANS, que o cidadão compra por conta própria.</dd>
<dt>Entidade filantrópica</dt>
<dd>Hospital ou serviço sem fins lucrativos com certificação (CEBAS); tem preferência na contratação pelo SUS e isenções tributárias.</dd>
<dt>Contrato de direito público</dt>
<dd>Instrumento que vincula o prestador privado às normas técnicas e administrativas do SUS, com metas e fiscalização.</dd>
</dl>
<h4>O essencial</h4>
<p>A Constituição (art. 199) diz que a assistência à saúde é livre à iniciativa privada e que as instituições privadas <strong>podem participar de forma complementar</strong> do SUS, mediante contrato de direito público ou convênio, com preferência às entidades filantrópicas e sem fins lucrativos.</p>
<p>Daí decorrem as características do setor <strong>complementar</strong>: o serviço é privado na propriedade, mas público no acesso e nas regras. O usuário entra pela regulação do SUS, não paga nada, e o prestador recebe do gestor pela tabela ou por metas. Santas Casas e hospitais filantrópicos respondem por grande parte das internações do SUS no interior; laboratórios e clínicas de diálise, por quase toda a oferta de certos procedimentos.</p>
<p>O setor <strong>suplementar</strong> é outra coisa: planos e seguros de saúde, cooperativas médicas, autogestões e o pagamento direto, que cobrem cerca de um quarto da população e são regulados pela Agência Nacional de Saúde Suplementar. Ele não é "complementar" ao SUS, ainda que seus usuários também tenham direito ao SUS, e o atendimento pelo SUS de um beneficiário de plano gera o ressarcimento da operadora ao sistema público. Os dois setores se misturam em muitos hospitais, que atendem SUS e convênios no mesmo prédio, o que exige fiscalização da dupla porta.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na prova, "complementar" vem sempre com três marcas: insuficiência da rede pública, contrato de direito público e preferência aos filantrópicos. Qualquer frase com "cobrança ao usuário", "maior eficiência do privado", "obrigação de integrar" ou "autorização do Ministério para cobrar" está descrevendo outra coisa ou está errada.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Complementar: o SUS contrata o privado quando a rede pública não basta, sob as regras do SUS e sem custo ao usuário.</li>
<li>Preferência às entidades filantrópicas e sem fins lucrativos; contrato de direito público ou convênio.</li>
<li>Suplementar: planos, seguros e desembolso direto, regulados pela ANS; não é complementar.</li>
<li>Recursos públicos não vão a auxílios para entidades privadas com fins lucrativos.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um hospital filantrópico que atende pelo SUS pode cobrar do paciente uma diferença pelo quarto? <details><summary>Resposta</summary>Não. No atendimento contratado pelo SUS, o acesso é gratuito e segue as normas do sistema público.</details></li>
<li>Qual é a condição legal para o SUS recorrer a serviços privados? <details><summary>Resposta</summary>A insuficiência das disponibilidades da rede pública para garantir a cobertura assistencial da população de uma área.</details></li>
</ol>
`,

"sirio2026#88": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer a Lei 14.737/2023 e o direito da mulher ao acompanhante.</li>
<li>Diferenciar o acompanhante da mulher do acompanhante no parto e da criança internada.</li>
<li>Resolver o conflito entre regra do serviço e direito da paciente.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Lei 14.737/2023</dt>
<dd>Garante à mulher acompanhante de sua escolha em consultas, exames e procedimentos, em serviços públicos e privados; obrigatório se ela estiver sedada ou com consciência alterada.</dd>
<dt>Lei do Acompanhante no parto (11.108/2005)</dt>
<dd>Direito à presença de um acompanhante durante o trabalho de parto, parto e pós-parto imediato no SUS.</dd>
<dt>ECA, art. 12</dt>
<dd>Permanência em tempo integral de um dos pais ou responsável na internação da criança e do adolescente.</dd>
<dt>Autonomia</dt>
<dd>Direito da pessoa de decidir sobre o próprio cuidado, incluindo quem a acompanha, princípio do SUS (Lei 8.080, art. 7º).</dd>
</dl>
<h4>O essencial</h4>
<p>A Lei 14.737, de novembro de 2023, nasceu depois de casos de violência sexual contra mulheres sedadas em ambiente assistencial. Ela inseriu na Lei 8.080 o <strong>direito de toda mulher a um acompanhante de sua livre escolha</strong> em consultas, exames e procedimentos de saúde, em qualquer serviço, público ou privado.</p>
<p>A lei não exige agendamento, aviso prévio, parentesco ou autorização de chefia: a escolha é da mulher, e isso inclui a esposa, a companheira, a amiga ou a mãe. Em caso de limitação real de espaço ou de risco (sala de radiologia durante a exposição, por exemplo), o serviço deve informar e buscar solução, não impedir. Regras internas que contrariem a lei são nulas. O direito também vale para a adolescente, e convive com o direito dela à privacidade e ao sigilo, que ela mesma administra.</p>
<p>Outras leis protegem situações específicas. A Lei 11.108/2005 garante acompanhante no trabalho de parto, parto e pós-parto imediato, e a Rede Cegonha e a Lei 14.737 reforçaram esse direito. O ECA (art. 12) garante a permanência de um dos pais durante a internação da criança, e o Estatuto da Pessoa Idosa (art. 16) o acompanhante do idoso internado. Nos exames ginecológicos e no atendimento à violência sexual, a presença de alguém de confiança é também proteção contra o constrangimento e boa prática desde antes da lei.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>A atitude correta é simples: perguntar à mulher se deseja alguém junto, acolher quem ela escolheu e registrar. Se ela estiver sob sedação e sozinha, uma profissional acompanha o procedimento. Diante de uma regra do serviço que contrarie isso, o profissional segue a lei e informa a gestão para corrigir a rotina.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Lei 14.737/2023: acompanhante de livre escolha em consultas, exames e procedimentos, público e privado, sem aviso prévio.</li>
<li>Sedação ou consciência alterada: acompanhante obrigatório; na falta, um profissional do serviço.</li>
<li>Parto: Lei 11.108/2005; criança internada: ECA, art. 12; idoso internado: Estatuto da Pessoa Idosa.</li>
<li>Regra interna não se sobrepõe à lei; a decisão é da paciente.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Uma mulher será sedada para endoscopia e veio sozinha. O que o serviço deve fazer? <details><summary>Resposta</summary>Designar um profissional de saúde para acompanhá-la durante o procedimento, pois com sedação o acompanhante é obrigatório.</details></li>
<li>A clínica pode exigir que o acompanhante seja parente ou tenha sido agendado antes? <details><summary>Resposta</summary>Não. A lei fala em acompanhante de livre escolha da mulher, sem exigência de parentesco ou aviso prévio.</details></li>
</ol>
`,

"sirio2026#89": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Caracterizar o estudo transversal e os seus produtos.</li>
<li>Distinguir transversal, ecológico, coorte, caso-controle e ensaio clínico pela pergunta e pela unidade de análise.</li>
<li>Reconhecer as limitações do transversal: prevalência, temporalidade, viés de sobrevivência.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Estudo transversal (seccional)</dt>
<dd>Mede exposição e desfecho ao mesmo tempo numa amostra; produz prevalência e razão de prevalências.</dd>
<dt>Estudo ecológico</dt>
<dd>A unidade de análise é o agregado (cidade, país, escola); compara taxas e médias entre grupos.</dd>
<dt>Estudo descritivo</dt>
<dd>Descreve a distribuição do problema por tempo, lugar e pessoa, sem grupo de comparação formal; gera hipóteses.</dd>
<dt>Causalidade reversa</dt>
<dd>Dúvida sobre o que veio antes, exposição ou desfecho, inerente ao corte transversal.</dd>
</dl>
<h4>O essencial</h4>
<p>O <strong>estudo transversal</strong> fotografa a população num instante: seleciona uma amostra, mede exposições e desfechos ao mesmo tempo e descreve como se distribuem. Seus produtos são a <strong>prevalência</strong> (quantos têm o problema), o <strong>perfil</strong> dos afetados (sexo, idade, renda, hábitos) e, quando se comparam expostos e não expostos, a razão de prevalências. É rápido, barato, não tem perdas de seguimento e serve para planejar serviços e <strong>gerar hipóteses</strong> que os estudos analíticos vão testar. Os grandes inquéritos nacionais (PNS, Vigitel, PeNSE) são transversais.</p>
<p>Suas limitações vêm da mesma fotografia. Não mede incidência nem risco, porque não acompanha ninguém. Não estabelece <strong>temporalidade</strong>: se os hipertensos são mais sedentários, não se sabe se o sedentarismo veio antes. Sofre o <strong>viés de sobrevivência</strong> (ou de prevalência): só entram os casos que sobreviveram até o momento do inquérito, e doenças curtas ou letais ficam sub-representadas. Por isso o transversal é descritivo ou, no máximo, analítico fraco.</p>
<p>A escolha do desenho segue a pergunta. "Quantos e quem?" é transversal. "Lugares com mais X têm mais Y?" é ecológico, com o agregado como unidade e a falácia ecológica como risco. "Expostos adoecem mais ao longo do tempo?" é coorte, que mede incidência e risco relativo. "Doentes foram mais expostos no passado?" é caso-controle, que dá odds ratio e serve a doenças raras. "A intervenção funciona?" é ensaio clínico randomizado. A hierarquia de evidência para causalidade vai do ecológico e do transversal, embaixo, ao ensaio clínico, no topo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na prova, "magnitude, características da população e hipóteses" é transversal; "comparar municípios ou países" é ecológico; "acompanhar expostos e não expostos" é coorte; "doentes e não doentes olhando para trás" é caso-controle. O transversal responde "quem são" indivíduo a indivíduo; o ecológico não.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Transversal: corte único, prevalência, perfil e hipóteses; rápido e barato.</li>
<li>Não mede incidência nem temporalidade; sofre viés de sobrevivência.</li>
<li>Ecológico usa agregados; coorte mede incidência; caso-controle, odds ratio; ensaio, intervenção.</li>
<li>Inquéritos nacionais (PNS, Vigitel) são transversais.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que medida de frequência um estudo transversal produz? <details><summary>Resposta</summary>Prevalência (e razão de prevalências), nunca incidência.</details></li>
<li>Por que um transversal não prova que o sedentarismo causa hipertensão? <details><summary>Resposta</summary>Porque mede os dois ao mesmo tempo e não estabelece qual veio antes (causalidade reversa).</details></li>
</ol>
`,

"sirio2026#91": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir território na PNAB e na Estratégia Saúde da Família.</li>
<li>Descrever a territorialização e seus instrumentos.</li>
<li>Relacionar adscrição de clientela e responsabilidade sanitária.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Território vivo</dt>
<dd>Conceito de Milton Santos: espaço usado, em permanente construção pelas relações sociais, econômicas e culturais.</dd>
<dt>Territorialização</dt>
<dd>Processo de reconhecimento do território: cadastro, mapeamento de riscos, recursos e equipamentos sociais, e definição de áreas e microáreas.</dd>
<dt>Adscrição</dt>
<dd>Vínculo formal entre uma população definida e uma equipe, que responde por ela, procure ou não a unidade.</dd>
<dt>Microárea</dt>
<dd>Subdivisão do território da equipe, sob responsabilidade de um agente comunitário de saúde, em geral com até 750 pessoas.</dd>
</dl>
<h4>O essencial</h4>
<p>A PNAB (2017) define a Atenção Básica como ações "desenvolvidas por meio de práticas de cuidado integrado e gestão qualificada, realizadas com equipe multiprofissional e dirigidas à população em <strong>território definido</strong>, sobre o qual as equipes assumem <strong>responsabilidade sanitária</strong>".</p>
<p>A <strong>territorialização</strong> é o processo de conhecer esse espaço: cadastrar as famílias (e-SUS), mapear ruas, equipamentos (escolas, igrejas, associações), áreas de risco (córregos, tráfico, falta de saneamento), identificar lideranças e grupos vulneráveis, e dividir a área em <strong>microáreas</strong> para os agentes comunitários. O produto é o diagnóstico situacional, que orienta o planejamento local: onde há mais idosos acamados, onde a cobertura vacinal é baixa, onde a dengue se concentra.</p>
<p>Da territorialização decorre a <strong>adscrição</strong>: a equipe responde por todos os que vivem na sua área, de 2.000 a 3.500 pessoas por equipe de Saúde da Família, inclusive por quem nunca procurou a unidade. Busca ativa de faltosos, visita domiciliar e vigilância são expressão dessa responsabilidade. A adscrição permite a <strong>longitudinalidade</strong> e o vínculo, atributos essenciais da APS, e dá base a indicadores populacionais (cobertura vacinal, pré-natal, hipertensos acompanhados), que só fazem sentido com um denominador conhecido.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um hipertenso da área não aparece há um ano, ele não "não é paciente da equipe": é um usuário adscrito sob responsabilidade sanitária, e o agente comunitário o procura. O território explica também por que a equipe participa de reuniões de associação de moradores e de ações na escola: a saúde se produz no território, não só na sala de consulta.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Território na PNAB: espaço vivo e dinâmico, com dimensões geográfica, social, econômica, cultural e de saúde.</li>
<li>Territorialização: cadastro, mapeamento de riscos e recursos, microáreas, diagnóstico situacional.</li>
<li>Adscrição: a equipe responde por toda a população da área, inclusive por quem não procura a unidade.</li>
<li>2.000 a 3.500 pessoas por equipe; microárea de até 750 pessoas por agente comunitário.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Uma família mora na área da equipe, mas usa só o plano de saúde. A equipe tem responsabilidade sobre ela? <details><summary>Resposta</summary>Sim. A adscrição é pela residência no território; a responsabilidade sanitária independe de a família procurar a unidade.</details></li>
<li>Qual é a diferença entre área da UBS e território vivo? <details><summary>Resposta</summary>A área é o limite geográfico-administrativo; o território vivo inclui as relações sociais, as condições de vida e os recursos da população que ali vive.</details></li>
</ol>
`,

"sirio2026#92": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir esperança de vida ao nascer e explicar como se calcula.</li>
<li>Interpretar o indicador e as suas variações entre regiões e no tempo.</li>
<li>Distinguir esperança de vida de idade média ao morrer e de esperança de vida saudável.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Esperança de vida ao nascer</dt>
<dd>Número médio de anos que uma coorte hipotética de recém-nascidos viveria sob as taxas de mortalidade por idade do ano de referência.</dd>
<dt>Tábua de vida</dt>
<dd>Tabela que aplica as taxas de mortalidade de cada idade a uma coorte fictícia de 100 mil nascidos e calcula os sobreviventes e os anos vividos.</dd>
<dt>Esperança de vida saudável</dt>
<dd>Anos esperados de vida sem incapacidade; combina mortalidade e morbidade.</dd>
<dt>Idade média ao morrer</dt>
<dd>Média das idades dos óbitos ocorridos; depende da estrutura etária e não é um indicador padronizado.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>esperança de vida ao nascer</strong> é um indicador <strong>hipotético</strong>: pega-se uma coorte imaginária de recém-nascidos e supõe-se que ela enfrente, em cada idade, exatamente as taxas de mortalidade observadas na população no ano de referência. A média de anos vividos por essa coorte é a esperança de vida. Ela não é uma previsão de quanto os nascidos de hoje vão viver, pois as taxas mudam; é um <strong>resumo da mortalidade atual</strong>, de todas as idades, num único número, independente da estrutura etária da população. Por isso serve para comparar lugares e épocas.</p>
<p>O cálculo é a <strong>tábua de vida</strong>: para cada idade, a probabilidade de morrer; a partir dela, os sobreviventes de cada idade e os anos vividos pela coorte; a soma dos anos restantes dividida pelos sobreviventes em cada idade dá a esperança de vida naquela idade. Esperança de vida aos 60 anos, por exemplo, é quantos anos em média ainda viveria quem chegou aos 60.</p>
<p>No Brasil, a esperança de vida ao nascer passou de cerca de 45 anos em 1940 para 76 anos em 2023, com queda de cerca de dois anos em 2021 pela covid-19 e recuperação depois. As mulheres vivem cerca de sete anos mais que os homens, em grande parte pelas causas externas na juventude masculina, e há diferenças de vários anos entre estados e entre bairros da mesma cidade, reflexo das condições de vida.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Erros comuns de prova: confundir esperança de vida com idade média dos óbitos (que depende de quantos jovens e idosos há na população), supor que ela depende da estrutura etária (não depende, por ser calculada por idade) e esquecer que a definição fala de uma coorte submetida às taxas do ano, e não de pessoas reais acompanhadas.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Esperança de vida ao nascer: anos médios de uma coorte hipotética sob as taxas de mortalidade por idade do ano.</li>
<li>Calculada pela tábua de vida; independe da estrutura etária; resume a mortalidade de todas as idades.</li>
<li>A mortalidade infantil é o maior determinante do valor ao nascer.</li>
<li>Brasil: cerca de 76 anos em 2023, mulheres sete anos acima dos homens, grandes diferenças regionais.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a esperança de vida ao nascer pode ser comparada entre um país jovem e um país envelhecido? <details><summary>Resposta</summary>Porque é calculada a partir das taxas de mortalidade específicas por idade, e não depende da proporção de jovens e idosos na população.</details></li>
<li>O que mais contribuiu para o aumento da esperança de vida ao nascer no século XX? <details><summary>Resposta</summary>A queda da mortalidade infantil, que subtraía dezenas de anos potenciais a cada óbito no primeiro ano.</details></li>
</ol>
`,

"sirio2026#95": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar a abordagem sindrômica ao corrimento uretral.</li>
<li>Montar o pacote de prevenção combinada na mesma consulta.</li>
<li>Atender a população LGBT sem discriminação, com sigilo e autonomia.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Abordagem sindrômica</dt>
<dd>Tratar na primeira consulta pelo conjunto de sinais e sintomas, sem esperar o agente, cobrindo as etiologias mais prováveis.</dd>
<dt>Prevenção combinada</dt>
<dd>Soma de preservativo, testagem, PEP, PrEP, tratamento das IST, vacinas e redução de danos, escolhida com a pessoa.</dd>
<dt>PrEP</dt>
<dd>Profilaxia pré-exposição ao HIV com tenofovir e entricitabina, diária ou sob demanda, para pessoas com risco aumentado.</dd>
<dt>Comunicação às parcerias</dt>
<dd>Aviso às parcerias sexuais para que se tratem, feito preferencialmente pelo próprio paciente, com apoio do serviço e sem quebra de sigilo.</dd>
</dl>
<h4>O essencial</h4>
<p>O <strong>corrimento uretral</strong> masculino tem como causas principais <em>Neisseria gonorrhoeae</em> e <em>Chlamydia trachomatis</em>, frequentemente juntas, e ainda <em>Mycoplasma genitalium</em> e <em>Trichomonas</em>. O PCDT de IST manda tratar na primeira consulta pela <strong>abordagem sindrômica</strong>: <strong>ceftriaxona 500 mg IM</strong> em dose única mais <strong>azitromicina 1 g VO</strong> em dose única. Quando houver laboratório, colhe-se material para bacterioscopia ou biologia molecular antes, mas o tratamento não espera o resultado. Persistência após 7 dias com adesão e sem reexposição sugere micoplasma ou tricomonas e muda o esquema.</p>
<p>A consulta por IST é a oportunidade da <strong>prevenção combinada</strong>: testes rápidos para HIV, sífilis, hepatites B e C; vacinas contra hepatite B, hepatite A (disponível para homens que fazem sexo com homens no SUS) e HPV (até 45 anos para alguns grupos); preservativos e gel; orientação sobre <strong>PEP</strong> até 72 horas após exposição e oferta de <strong>PrEP</strong> para quem tem risco continuado, como múltiplas parcerias sem preservativo. As parcerias dos últimos 60 dias devem ser tratadas; a comunicação é feita pelo paciente, com cartão de convocação, ou pelo serviço com o seu consentimento, sempre sem revelar o diagnóstico a terceiros sem autorização.</p>
<p>A Política Nacional de Saúde Integral de LGBT (2011) reconhece a discriminação como determinante de saúde e exige acolhimento sem julgamento, uso do nome social e abordagem da sexualidade na anamnese de forma natural. Perguntar sobre práticas sexuais, parcerias e uso de preservativo não é invasão: é o que permite oferecer o cuidado certo. Tratar "só o biomédico" para não constranger, encaminhar a sexualidade ao serviço social ou envolver a família de um adulto sem pedido são formas de excluir.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Fluxo da consulta: tratar com ceftriaxona e azitromicina; testes rápidos; vacinas; preservativos; conversar sobre PrEP e PEP; orientar comunicação às parcerias e retorno em uma semana. Notificar no SINAN apenas o que é compulsório (HIV, sífilis, hepatites); a uretrite gonocócica não é de notificação individual.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Corrimento uretral: ceftriaxona 500 mg IM + azitromicina 1 g VO na primeira consulta.</li>
<li>Mesma consulta: testes rápidos, vacinas, preservativo, PEP e PrEP conforme o risco.</li>
<li>Parcerias dos últimos 60 dias tratadas; comunicação voluntária e sigilosa.</li>
<li>Acolhimento sem discriminação e sexualidade na anamnese: cuidado, não constrangimento.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é o tratamento sindrômico do corrimento uretral no PCDT? <details><summary>Resposta</summary>Ceftriaxona 500 mg intramuscular em dose única mais azitromicina 1 g oral em dose única.</details></li>
<li>Em que prazo a PEP para HIV deve ser iniciada? <details><summary>Resposta</summary>Idealmente em até 2 horas e no máximo até 72 horas após a exposição.</details></li>
</ol>
`,

"sirio2026#96": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer o calendário da vacina varicela e a idade mínima da vacina atenuada.</li>
<li>Saber quem recebe imunoglobulina antivaricela-zóster após exposição.</li>
<li>Orientar a família de um lactente exposto a varicela ou zóster.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Tetraviral</dt>
<dd>Sarampo, caxumba, rubéola e varicela numa só dose, aos 15 meses, no calendário nacional.</dd>
<dt>Varicela atenuada</dt>
<dd>Vacina de vírus vivo; não se aplica antes dos 12 meses de rotina, nem a imunodeprimidos e gestantes.</dd>
<dt>IGHAVZ</dt>
<dd>Imunoglobulina humana antivaricela-zóster, aplicada até 96 horas após a exposição a suscetíveis de alto risco.</dd>
<dt>Herpes zóster</dt>
<dd>Reativação do vírus varicela-zóster em gânglio sensitivo; transmite varicela pelo contato com as lesões, menos que a varicela.</dd>
</dl>
<h4>O essencial</h4>
<p>No calendário nacional, a <strong>varicela</strong> entra na <strong>tetraviral aos 15 meses</strong> e tem a segunda dose, como varicela isolada, aos <strong>4 anos</strong>. Por ser vacina de vírus vivo atenuado, não é aplicada antes dos <strong>12 meses</strong> fora de situação de surto, em que a SBIm e os CRIE admitem a partir dos 9 meses, sem contar essa dose para o esquema. É contraindicada em imunodeprimidos graves e gestantes. Lactentes menores de um ano não têm, portanto, vacina disponível, e dependem da imunidade materna transferida e, depois, da baixa exposição.</p>
<p>O <strong>herpes zóster</strong> da avó transmite o vírus pelo contato com as vesículas, até que formem crostas, e com menor transmissibilidade que a varicela. Um lactente saudável exposto pode ter varicela, em geral <strong>benigna</strong>: a doença grave concentra-se em imunodeprimidos, gestantes, recém-nascidos de mãe com varicela periparto e adultos.</p>
<p>A conduta para o lactente de 4 meses é orientar: separar a avó enquanto houver lesões abertas, cobrir as lesões, higiene das mãos, e observar por 10 a 21 dias o aparecimento de febre e vesículas; em caso de varicela, antitérmico (nunca ácido acetilsalicílico), higiene das lesões e retorno se houver sinais de complicação. O calendário de rotina dos 6 meses segue normalmente. A avó deve ser orientada sobre a vacina de zóster recombinante, indicada a partir dos 50 anos na rede privada.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando um responsável pergunta "existe vacina para proteger agora?", a resposta é não para o lactente saudável com menos de 12 meses, e a imunoglobulina não é para ele. A pergunta certa a fazer de volta é: a criança é prematura extrema ou tem imunodeficiência? Só então a IGHAVZ entra.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Varicela: tetraviral aos 15 meses e reforço aos 4 anos; atenuada, não antes dos 12 meses de rotina.</li>
<li>Zóster transmite varicela pelo contato com as lesões; em lactente saudável, a varicela é em geral benigna.</li>
<li>IGHAVZ até 96 horas só para imunodeprimidos, gestantes suscetíveis, recém-nascidos de mãe com varicela periparto e prematuros.</li>
<li>Lactente de 4 meses exposto: orientar, observar e manter o calendário.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Em que idade o calendário nacional dá a primeira dose contra varicela e em que vacina? <details><summary>Resposta</summary>Aos 15 meses, na tetraviral (sarampo, caxumba, rubéola e varicela).</details></li>
<li>Recém-nascido a termo cuja mãe teve varicela dois dias antes do parto: que profilaxia recebe? <details><summary>Resposta</summary>Imunoglobulina antivaricela-zóster, pois a varicela materna de 5 dias antes a 2 dias depois do parto é indicação.</details></li>
</ol>
`,

"sirio2026#97": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Caracterizar os modelos Beveridge, Bismarck e de mercado.</li>
<li>Associar cada modelo a países e à sua concepção de saúde.</li>
<li>Situar o SUS e o antigo INAMPS nessa tipologia.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Modelo Beveridge</dt>
<dd>Sistema nacional de saúde financiado por impostos, de acesso universal, com provisão majoritariamente pública (Reino Unido, Suécia, Brasil).</dd>
<dt>Modelo Bismarck</dt>
<dd>Seguro social obrigatório financiado por contribuições de empregados e empregadores, gerido por caixas (Alemanha, França, Japão).</dd>
<dt>Modelo de mercado</dt>
<dd>Seguros privados voluntários e desembolso direto, com programas públicos residuais (Estados Unidos).</dd>
<dt>Cobertura universal</dt>
<dd>Meta da OMS: toda a população com acesso a serviços de qualidade sem sofrer dificuldade financeira, independentemente do modelo.</dd>
</dl>
<h4>O essencial</h4>
<p>A tipologia clássica distingue os sistemas pelo <strong>financiamento</strong> e pela <strong>concepção de saúde</strong>. O modelo <strong>Bismarck</strong> é o mais antigo: em 1883, o chanceler alemão criou o seguro-doença obrigatório para operários, financiado por contribuições de trabalhadores e patrões e gerido por caixas de seguridade. A saúde é <strong>seguro social</strong>, direito ligado ao trabalho e à contribuição, e a provisão é mista. Alemanha, França, Bélgica, Japão e Áustria seguem variantes, hoje com cobertura quase universal por extensão progressiva das caixas.</p>
<p>O modelo <strong>Beveridge</strong> vem do relatório de William Beveridge (1942) e do National Health Service britânico (1948): a saúde é <strong>direito universal de cidadania</strong>, financiada por impostos gerais, com acesso gratuito no ponto de uso e provisão predominantemente pública, organizada a partir do médico generalista. Reino Unido, países nórdicos, Espanha, Itália, Portugal e o <strong>SUS</strong> estão nessa família: a Constituição de 1988 rompeu com o modelo previdenciário do INAMPS, que era bismarckiano e cobria só os contribuintes, e universalizou o direito.</p>
<p>O modelo de <strong>mercado</strong>, cujo exemplo é o dos Estados Unidos, trata a saúde como <strong>bem de consumo</strong>: cada um compra o seguro que pode, em geral pelo empregador, e o Estado cobre grupos residuais (Medicare para idosos, Medicaid para pobres). É o sistema mais caro do mundo, com piores indicadores que os pares e milhões de não segurados, parcialmente corrigidos pelo Affordable Care Act (2010). Na prática, todos os sistemas são mistos: o Brasil tem um SUS beveridgiano convivendo com um setor suplementar de mercado que cobre um quarto da população.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Mnemônico de prova: Beveridge, Bismarck, Mercado = direito, seguro, consumo = imposto, contribuição, bolso = Reino Unido, Alemanha, Estados Unidos. INAMPS era Bismarck; SUS é Beveridge; plano de saúde é mercado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Bismarck (1883): seguro social por contribuição, ligado ao trabalho; Alemanha.</li>
<li>Beveridge (1948): direito universal por impostos, provisão pública; Reino Unido e SUS.</li>
<li>Mercado: bem de consumo por seguros privados, Estado residual; Estados Unidos.</li>
<li>O Brasil passou do INAMPS bismarckiano ao SUS beveridgiano em 1988, mantendo um setor suplementar de mercado.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que modelo o INAMPS representava e por quê? <details><summary>Resposta</summary>O modelo Bismarck, pois cobria apenas os trabalhadores contribuintes da previdência, como um seguro social.</details></li>
<li>Qual é a fonte principal de financiamento no modelo Beveridge? <details><summary>Resposta</summary>Impostos gerais, com acesso universal e gratuito no ponto de uso.</details></li>
</ol>
`,

"sirio2026#99": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar os princípios e as diretrizes da Política Nacional de Humanização.</li>
<li>Reconhecer o acolhimento como postura e não como triagem.</li>
<li>Aplicar a PNH ao cuidado do acompanhante na internação pediátrica.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PNH (HumanizaSUS)</dt>
<dd>Política de 2003 que propõe mudar as práticas de gestão e de cuidado no SUS a partir da valorização dos sujeitos: usuários, trabalhadores e gestores.</dd>
<dt>Acolhimento</dt>
<dd>Postura ética de escuta qualificada e responsabilização, em todo encontro, e não um setor ou uma etapa de triagem.</dd>
<dt>Clínica ampliada</dt>
<dd>Olhar que integra doença, sujeito e contexto, com projeto terapêutico singular construído em equipe e com o usuário.</dd>
<dt>Cogestão</dt>
<dd>Inclusão de usuários e trabalhadores nas decisões, por colegiados e dispositivos como a visita aberta e o acompanhante.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>Política Nacional de Humanização</strong> parte de três princípios: <strong>transversalidade</strong> (atravessa todas as práticas e serviços), <strong>inseparabilidade entre atenção e gestão</strong> (o modo de gerir produz o modo de cuidar) e <strong>protagonismo, corresponsabilidade e autonomia</strong> dos sujeitos. Suas diretrizes incluem acolhimento, clínica ampliada e compartilhada, cogestão, valorização do trabalhador, defesa dos direitos dos usuários, ambiência, visita aberta e direito a acompanhante.</p>
<p>O <strong>acolhimento</strong>, na PNH, é escuta qualificada da necessidade da pessoa, com responsabilização pela resposta, em todos os momentos e por todos os profissionais. A mãe que se sente "invisível" descreve uma equipe que acolhe a criança como objeto de exame e ignora a família como sujeito. Ouvir ativamente, nomear e validar o sofrimento ("é muito cansativo ficar cinco dias aqui") e compartilhar com a equipe, com o consentimento dela, para ajustar a comunicação e a rotina, é a aplicação da diretriz.</p>
<p>A internação pediátrica tem dispositivos próprios. O ECA (art. 12) garante a permanência em tempo integral de um dos pais, e os hospitais devem oferecer condições para isso: poltrona ou leito, alimentação, banho, informação clara e participação no cuidado (a mãe que aspira o nariz e dá a dieta não é visitante, é cuidadora). A <strong>visita aberta</strong> e a <strong>ambiência</strong> (espaço de descanso, luz, ruído) são parte da PNH, e a troca de informações entre a equipe, com a mãe presente na passagem de visita, é o que impede o sentimento de invisibilidade.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ferramentas de escuta que cabem em cinco minutos: perguntar "como você está?", sentar-se na altura dela, resumir o que ouviu, perguntar o que a preocupa mais e combinar o próximo passo. Oferecer, não impor, o descanso; nunca medicar a criança para resolver a exaustão do adulto.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>PNH: transversalidade, inseparabilidade entre atenção e gestão, protagonismo e corresponsabilidade.</li>
<li>Acolhimento é escuta qualificada com responsabilização, em todo encontro; não é triagem.</li>
<li>Clínica ampliada: a família adoece com a criança; a mãe é cuidadora, não visitante.</li>
<li>Acompanhante em tempo integral (ECA, art. 12), visita aberta e ambiência são dispositivos da PNH.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os três princípios da Política Nacional de Humanização? <details><summary>Resposta</summary>Transversalidade, inseparabilidade entre atenção e gestão, e protagonismo, corresponsabilidade e autonomia dos sujeitos.</details></li>
<li>Por que acolhimento não é sinônimo de triagem com classificação de risco? <details><summary>Resposta</summary>Porque é uma postura ética de escuta e responsabilização de todos os profissionais em todos os encontros, e não uma etapa ou um setor do serviço.</details></li>
</ol>
`,

"sirio2026#100": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever o circuito de incorporação de tecnologias no SUS pela Conitec.</li>
<li>Explicar o papel dos Protocolos Clínicos e Diretrizes Terapêuticas.</li>
<li>Distinguir registro sanitário, incorporação e dispensação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Conitec</dt>
<dd>Comissão Nacional de Incorporação de Tecnologias no SUS, criada pela Lei 12.401/2011, que assessora o Ministério sobre incorporar, excluir ou alterar tecnologias e elaborar PCDT.</dd>
<dt>ATS</dt>
<dd>Avaliação de Tecnologias em Saúde: análise de eficácia, segurança, custo-efetividade e impacto orçamentário para decidir sobre a oferta pública.</dd>
<dt>PCDT</dt>
<dd>Protocolo Clínico e Diretrizes Terapêuticas: documento oficial que define critérios de diagnóstico, tratamento, doses, monitoramento e resultados esperados.</dd>
<dt>Componente Especializado</dt>
<dd>Parte da assistência farmacêutica que dispensa medicamentos de alto custo conforme os PCDT, em farmácias estaduais.</dd>
</dl>
<h4>O essencial</h4>
<p>Um medicamento percorre três portas até chegar ao usuário do SUS. A primeira é o <strong>registro na Anvisa</strong>, que atesta qualidade, segurança e eficácia e autoriza a comercialização no país; sem ele, a Lei 8.080 (art. 19-T) proíbe a dispensação no SUS. A segunda é a <strong>incorporação</strong>: a Lei 12.401/2011 criou a <strong>Conitec</strong>, que analisa as demandas de incorporação em até 180 dias (prorrogáveis por 90), com <strong>Avaliação de Tecnologias em Saúde</strong>, consulta pública e recomendação ao secretário de Ciência, Tecnologia e Inovação, que decide.</p>
<p>A incorporação vem acompanhada do <strong>PCDT</strong>, que traduz a evidência em regras de uso: critérios de inclusão e exclusão, esquema, doses, exames de monitoramento, critérios de interrupção. O PCDT protege o paciente e o sistema: garante que a tecnologia seja usada em quem se beneficia e que o gasto seja previsível.</p>
<p>A Conitec também pode <strong>excluir</strong> tecnologias obsoletas e revisar PCDT, e qualquer pessoa pode protocolar uma demanda. Para a saúde suplementar, o processo é outro: a ANS atualiza o Rol de Procedimentos com a sua própria comissão. A judicialização surge quando o paciente pede algo não incorporado; os tribunais exigem, entre outros critérios, que não exista substituto no SUS e que haja evidência de eficácia, e a mora da Conitec em analisar uma demanda pesa a favor do pedido.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Prescrever no SUS é prescrever dentro do PCDT: o formulário do Componente Especializado (LME) exige o CID, os exames e os critérios do protocolo, e a farmácia estadual só dispensa o que se enquadra. Conhecer o PCDT da doença que se trata é parte da competência clínica, não burocracia.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Três portas: registro na Anvisa, incorporação pela Conitec (ATS, 180 dias, consulta pública) e dispensação pela assistência farmacêutica.</li>
<li>PCDT: critérios de uso, doses e monitoramento; a prescrição no SUS segue o protocolo.</li>
<li>Hepatite C: antivirais incorporados após ATS, PCDT ampliado, cura acima de 95%.</li>
<li>ANS e Rol cuidam dos planos privados; a Conitec cuida do SUS.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que lei criou a Conitec e qual é o prazo para analisar uma demanda de incorporação? <details><summary>Resposta</summary>A Lei 12.401/2011; 180 dias, prorrogáveis por mais 90.</details></li>
<li>Registro na Anvisa basta para um medicamento ser dispensado no SUS? <details><summary>Resposta</summary>Não. O registro autoriza a venda no país; a oferta no SUS exige incorporação pela Conitec e uso conforme o PCDT.</details></li>
</ol>
`,

/* --- Volume 2 · Preventiva · Sírio-Libanês 2027 (prev66–prev80) --------------------------- */
"sirio2027#81": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir prevenção quaternária e situá-la entre os níveis de prevenção.</li>
<li>Explicar sobrediagnóstico, sobretratamento e cascata de exames.</li>
<li>Listar os rastreamentos recomendados para uma mulher de 47 anos sem fatores de risco.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Prevenção quaternária</dt>
<dd>Ação que identifica a pessoa em risco de medicalização excessiva e a protege de intervenções sem benefício (Jamoulle).</dd>
<dt>Sobrediagnóstico</dt>
<dd>Diagnóstico correto de uma condição que nunca causaria sintomas ou morte; o paciente só colhe os danos do rótulo e do tratamento.</dd>
<dt>Incidentaloma</dt>
<dd>Achado casual de exame de imagem, em geral benigno, que desencadeia nova investigação.</dd>
<dt>Critérios de Wilson e Jungner</dt>
<dd>Condições para rastrear: doença importante, fase pré-clínica detectável, teste aceitável e tratamento precoce que muda o desfecho.</dd>
</dl>
<h4>O essencial</h4>
<p>Marc Jamoulle propôs em 1986 a <strong>prevenção quaternária</strong> a partir do cruzamento entre o que o médico vê (doença presente ou ausente) e o que a pessoa sente (doente ou não). Quando a pessoa se sente doente e o médico não encontra doença, o risco é a medicalização: exames em cascata, diagnósticos de conveniência, tratamentos sem indicação. A prevenção quaternária é proteger a pessoa desse excesso, com o princípio <em>primum non nocere</em>, e é tarefa especialmente da APS, que vê a pessoa inteira e ao longo do tempo.</p>
<p>O <strong>rastreamento</strong> só faz bem quando cumpre os critérios de Wilson e Jungner e tem evidência de reduzir mortalidade ou morbidade. Fora disso, produz <strong>falsos positivos</strong> (ansiedade, biópsias), <strong>sobrediagnóstico</strong> (cânceres de tireoide e de próstata indolentes, por exemplo) e <strong>sobretratamento</strong>, além de custo e radiação. O ultrassom de tireoide em assintomáticos é o exemplo clássico: a Coreia do Sul multiplicou por quinze o diagnóstico de câncer de tireoide sem mudar a mortalidade.</p>
<p>Para a mulher de 47 anos sem fatores de risco, o que tem recomendação no Brasil é: <strong>citologia cervical</strong> a cada três anos após dois exames anuais normais (ou teste de HPV a cada cinco anos, onde implantado); <strong>mamografia</strong> bienal a partir dos 50 anos pelo Ministério da Saúde (a SBM e a Febrasgo propõem anual a partir dos 40); <strong>pressão arterial</strong> em toda consulta; <strong>glicemia</strong> e <strong>lipídios</strong> conforme o risco cardiovascular; rastreamento de câncer colorretal a partir dos 50 (ou 45, para algumas sociedades); e atenção a tabagismo, álcool, peso e vacinas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Frases que funcionam na consulta: "esse exame, em quem não tem sintomas, encontra mais problemas falsos do que verdadeiros"; "o que a ciência mostra que protege alguém da sua idade é isto, e eu quero fazer isto bem feito". Oferecer o rastreamento certo é tão importante quanto negar o errado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Prevenção quaternária: proteger a pessoa da medicalização e do excesso de intervenção.</li>
<li>Rastrear só o que cumpre Wilson e Jungner e reduz mortalidade; o resto produz sobrediagnóstico.</li>
<li>Mulher de 47 anos sem risco: citologia, pressão, glicemia e lipídios conforme risco, mamografia a partir dos 50 (MS).</li>
<li>Ultrassom de tireoide, vitamina D e imagem de corpo inteiro em assintomáticos não têm indicação.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que é sobrediagnóstico? <details><summary>Resposta</summary>O diagnóstico de uma condição real que nunca causaria sintomas ou morte, de modo que a pessoa só recebe os danos do rótulo e do tratamento.</details></li>
<li>Qual é a recomendação do Ministério da Saúde para mamografia de rastreamento? <details><summary>Resposta</summary>Bienal, dos 50 aos 69 anos, em mulheres sem fatores de risco elevados.</details></li>
</ol>
`,

"sirio2027#82": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Diferenciar igualdade de equidade no SUS.</li>
<li>Definir racismo institucional e reconhecê-lo como determinante social.</li>
<li>Conhecer as diretrizes da Política Nacional de Saúde Integral da População Negra.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Equidade</dt>
<dd>Oferecer mais a quem precisa mais, para reduzir desigualdades injustas; princípio do SUS derivado da igualdade.</dd>
<dt>Racismo institucional</dt>
<dd>Fracasso coletivo das instituições em oferecer serviço adequado às pessoas por sua cor ou origem, produzindo desvantagem sistemática.</dd>
<dt>PNSIPN</dt>
<dd>Política Nacional de Saúde Integral da População Negra (2009), que reconhece o racismo como determinante e orienta ações de equidade.</dd>
<dt>Quesito raça/cor</dt>
<dd>Campo de autodeclaração nos sistemas de informação do SUS, obrigatório desde 2017, que permite medir as desigualdades.</dd>
</dl>
<h4>O essencial</h4>
<p>A Lei 8.080 fala em <strong>igualdade</strong> da assistência, sem preconceitos ou privilégios; a <strong>equidade</strong> é a sua leitura substantiva: como as necessidades são diferentes, tratar igual os desiguais mantém a desigualdade, e o sistema deve oferecer mais a quem tem mais necessidade. Equidade orienta a alocação de recursos (mais equipes onde há mais vulnerabilidade), a organização do acesso (busca ativa, horários estendidos) e as políticas para grupos específicos: população negra, LGBT, pessoas em situação de rua, povos indígenas, população do campo.</p>
<p>A população negra tem mais hipertensão, diabetes, mortalidade materna, mortes por violência e menor acesso a pré-natal adequado e a analgesia no parto. A explicação genética é marginal; o que pesa são os <strong>determinantes sociais</strong> (renda, moradia, trabalho) e o <strong>racismo</strong>, inclusive o <strong>institucional</strong>: o serviço que não oferece o mesmo acolhimento, que demora mais a atender, que subestima a dor da mulher negra, que não registra a cor.</p>
<p>Na APS, a política se traduz em ações concretas: preencher o <strong>quesito raça/cor</strong> em todos os registros, para que a desigualdade seja visível nos indicadores; capacitar a equipe sobre racismo e saúde; atenção à doença falciforme, à hipertensão e ao diabetes com busca ativa; cuidado respeitoso no pré-natal e no parto; espaço para que os usuários relatem discriminação, com resposta institucional. Reconhecer o racismo não é acusar a equipe: é entender por que a mesma oferta produz resultados diferentes e corrigir o processo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Três perguntas para a reunião de equipe: o quesito raça/cor está preenchido nos nossos cadastros? Os indicadores (pré-natal, hipertensão controlada, vacinação) são diferentes por cor? Os usuários negros relatam experiências ruins no acesso? As respostas mostram onde começa a ação de equidade.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Igualdade é o mesmo para todos; equidade é mais para quem precisa mais, para reduzir iniquidades.</li>
<li>Racismo institucional: as instituições funcionam pior para a população negra, e isso é determinante social.</li>
<li>PNSIPN (2009): reconhece o racismo como determinante e prioriza a redução das iniquidades.</li>
<li>Quesito raça/cor preenchido, equipe capacitada, busca ativa e acolhimento sem discriminação.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a equipe deve preencher o quesito raça/cor em todos os cadastros? <details><summary>Resposta</summary>Porque só com ele os indicadores revelam as desigualdades por cor e orientam as ações de equidade.</details></li>
<li>Como a PNSIPN classifica o racismo? <details><summary>Resposta</summary>Como determinante social das condições de saúde, ao lado das desigualdades étnico-raciais e do racismo institucional.</details></li>
</ol>
`,

"sirio2027#83": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar os princípios doutrinários e organizativos do SUS.</li>
<li>Reconhecer, em situações concretas, qual princípio foi violado.</li>
<li>Diferenciar universalidade de equidade e de integralidade.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Universalidade</dt>
<dd>Acesso de todas as pessoas, sem exigir contribuição, vínculo, documento ou residência comprovada.</dd>
<dt>Integralidade</dt>
<dd>Conjunto articulado de ações preventivas e curativas, individuais e coletivas, em todos os níveis de complexidade.</dd>
<dt>Equidade</dt>
<dd>Prioridade a quem tem mais necessidade; a face substantiva da igualdade.</dd>
<dt>Princípios organizativos</dt>
<dd>Descentralização com direção única em cada esfera, regionalização e hierarquização, participação da comunidade.</dd>
</dl>
<h4>O essencial</h4>
<p>Os <strong>princípios doutrinários</strong> do SUS dizem o que ele é: <strong>universalidade</strong> (saúde é direito de todos e dever do Estado, CF art. 196), <strong>integralidade</strong> (cuidado completo, da promoção à reabilitação) e <strong>equidade</strong> (igualdade substantiva, com prioridade a quem mais precisa). Os <strong>princípios organizativos</strong> dizem como ele funciona: <strong>descentralização</strong> com comando único em cada esfera de governo, <strong>regionalização e hierarquização</strong> da rede em níveis de complexidade e <strong>participação da comunidade</strong> por conselhos e conferências.</p>
<p>A <strong>universalidade</strong> foi a ruptura de 1988: antes, o INAMPS atendia só os trabalhadores contribuintes, e os demais dependiam da caridade ou dos poucos serviços de saúde pública. Hoje nenhum documento é condição de acesso. O Cartão SUS e o comprovante de residência servem ao cadastro e à adscrição na APS, mas a PNAB é explícita: a demanda espontânea de quem está no território deve ser acolhida, inclusive de quem não reside na área, com orientação posterior sobre a unidade de referência. Exigir carteira de trabalho é regredir ao modelo previdenciário.</p>
<p>Distinguir os princípios na prova exige olhar o que foi negado. Negar acesso a um cidadão qualquer fere a <strong>universalidade</strong>. Dar o mesmo a todos ignorando necessidades diferentes, ou deixar de priorizar quem precisa mais, fere a <strong>equidade</strong>. Tratar só a queixa sem prevenção, ou não garantir o seguimento no nível seguinte, fere a <strong>integralidade</strong>. Centralizar decisões no Ministério fere a descentralização; não ouvir o conselho fere a participação.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Acolher a demanda espontânea é tarefa de toda a equipe, inclusive da recepção, e a PNAB prevê a classificação de risco já no acolhimento. A pessoa fora da área é atendida e depois orientada sobre a unidade de referência, nunca mandada embora. Síndrome febril aguda em época de arboviroses tem prioridade.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Doutrinários: universalidade, integralidade, equidade; organizativos: descentralização, regionalização e hierarquização, participação.</li>
<li>Universalidade: acesso de todos, sem documento, vínculo ou residência comprovada; ruptura com o INAMPS.</li>
<li>Negar acesso fere a universalidade; não priorizar quem precisa mais fere a equidade; cuidado incompleto fere a integralidade.</li>
<li>Demanda espontânea é acolhida mesmo fora da área; cadastro vem depois.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Uma UBS atende os hipertensos com o mesmo intervalo de consultas, independentemente do controle da pressão. Que princípio está em falta? <details><summary>Resposta</summary>A equidade: quem está descompensado precisa de mais atenção que quem está controlado.</details></li>
<li>Quais são os princípios organizativos do SUS? <details><summary>Resposta</summary>Descentralização com direção única em cada esfera, regionalização e hierarquização, e participação da comunidade.</details></li>
</ol>
`,

"sirio2027#85": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar e interpretar o AUDIT na atenção primária.</li>
<li>Conhecer os limites do CAGE e o papel da intervenção breve.</li>
<li>Reconhecer sinais de dependência e de risco de abstinência.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>AUDIT</dt>
<dd>Dez perguntas da OMS sobre consumo, dependência e problemas; escore de 0 a 40 com quatro zonas de risco e intervenções correspondentes.</dd>
<dt>AUDIT-C</dt>
<dd>As três primeiras perguntas do AUDIT, sobre quantidade e frequência; rastreio rápido, positivo com 4 pontos em homens e 3 em mulheres.</dd>
<dt>CAGE</dt>
<dd>Quatro perguntas (cortar, aborrecer-se, culpa, abrir os olhos bebendo); duas positivas sugerem dependência, sem graduar.</dd>
<dt>Intervenção breve</dt>
<dd>Conversa estruturada de 5 a 15 minutos, com devolutiva do escore, metas e acompanhamento, eficaz no uso de risco e nocivo.</dd>
</dl>
<h4>O essencial</h4>
<p>O álcool é a substância que mais causa dano no Brasil, e a APS é o lugar de identificar o problema antes da dependência. O <strong>AUDIT</strong>, desenvolvido pela OMS para a atenção primária, tem dez perguntas: três sobre <strong>consumo</strong> (frequência, quantidade, episódios de seis ou mais doses), três sobre <strong>dependência</strong> (não conseguir parar, deixar de fazer o esperado, beber de manhã) e quatro sobre <strong>problemas</strong> (culpa, amnésia, ferimentos, preocupação de terceiros). O escore vai de 0 a 40 e define zonas: <strong>0 a 7</strong>, baixo risco, educação; <strong>8 a 15</strong>, uso de risco, orientação simples; <strong>16 a 19</strong>, uso nocivo, intervenção breve e monitoramento; <strong>20 ou mais</strong>, provável dependência, avaliação diagnóstica e encaminhamento ao CAPS-AD ou tratamento especializado.</p>
<p>O <strong>CAGE</strong> é mais antigo e mais curto, e rastreia dependência com boa sensibilidade quando há duas respostas positivas, mas não identifica o uso de risco sem dependência, que é a maioria dos casos na APS, nem gradua a gravidade. O <strong>AUDIT-C</strong> serve como primeira peneira em consultas rápidas. O <strong>MINI</strong> e o <strong>SCID</strong> são entrevistas diagnósticas psiquiátricas estruturadas, para pesquisa ou especialista, e não substituem a história do consumo.</p>
<p>No caso de cinco a seis doses diárias com tremor e ansiedade ao reduzir, o AUDIT provavelmente marcará 20 ou mais, e os sintomas indicam <strong>dependência com risco de abstinência</strong>. Mandar parar de imediato sem plano pode precipitar abstinência grave, com convulsão e delirium tremens. O plano inclui a devolutiva do escore, a avaliação da motivação (entrevista motivacional), tiamina, estratégia de redução ou de desintoxicação assistida com benzodiazepínico quando houver risco, exames (hepatograma, hemograma) e articulação com o CAPS-AD, mantendo o vínculo com a equipe.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Uma dose padrão no Brasil tem cerca de 14 g de etanol: uma lata de cerveja, um copo de vinho de 150 mL ou 45 mL de destilado. Beber cinco ou mais doses numa ocasião é "binge" e já pontua no AUDIT. Tiamina antes de qualquer glicose em quem bebe muito previne a encefalopatia de Wernicke.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>AUDIT: dez perguntas, escore 0 a 40; zonas 0–7, 8–15, 16–19 e 20 ou mais, cada uma com a sua intervenção.</li>
<li>CAGE rastreia dependência, mas não gradua nem detecta o uso de risco; AUDIT-C é a peneira rápida.</li>
<li>Tremor e ansiedade ao reduzir indicam dependência com risco de abstinência: não interromper abruptamente sem plano.</li>
<li>Intervenção breve funciona no uso de risco e nocivo; dependência vai ao CAPS-AD com a APS junto.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um paciente marca 17 pontos no AUDIT. Em que zona está e qual é a conduta? <details><summary>Resposta</summary>Uso nocivo (16 a 19): intervenção breve com acompanhamento.</details></li>
<li>Por que o CAGE não é o melhor instrumento para a APS? <details><summary>Resposta</summary>Porque detecta só a dependência provável e não gradua a gravidade nem identifica o uso de risco, que é o alvo da intervenção breve.</details></li>
</ol>
`,

"sirio2027#86": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enumerar os componentes do Método Clínico Centrado na Pessoa.</li>
<li>Explorar a experiência da doença com as perguntas sobre sentimentos, ideias, função e expectativas.</li>
<li>Construir um plano conjunto adaptado ao contexto da pessoa.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Experiência da doença (illness)</dt>
<dd>O que a pessoa sente, pensa e espera a respeito do seu adoecer, em contraste com a doença (disease) que o médico diagnostica.</dd>
<dt>SIFE</dt>
<dd>Sentimentos, Ideias, Função e Expectativas: as quatro dimensões a explorar na experiência da doença.</dd>
<dt>Terreno comum</dt>
<dd>Acordo entre médico e pessoa sobre os problemas, as metas e os papéis de cada um no plano de cuidado.</dd>
<dt>Pessoa como um todo</dt>
<dd>Compreensão do indivíduo no seu ciclo de vida, família, trabalho, cultura e comunidade.</dd>
</dl>
<h4>O essencial</h4>
<p>O <strong>Método Clínico Centrado na Pessoa</strong>, sistematizado por Moira Stewart e Ian McWhinney na Universidade de Western Ontario, reorganiza a consulta em quatro componentes interligados. O primeiro é <strong>explorar a saúde, a doença e a experiência da doença</strong>: além da história clínica, perguntar o que a pessoa <strong>sente</strong> (medo de cegar), o que <strong>pensa</strong> que está acontecendo (culpa por não seguir a dieta), como a doença afeta a sua <strong>função</strong> (cuidar dos netos) e o que <strong>espera</strong> da consulta. O segundo é <strong>entender a pessoa como um todo</strong>: ciclo de vida, família, trabalho, renda, cultura, espiritualidade.</p>
<p>O terceiro componente é <strong>elaborar um plano conjunto de manejo dos problemas</strong>, o <strong>terreno comum</strong>: definir juntos quais são os problemas, quais as metas e qual o papel de cada um. Metas alimentares factíveis para quem cozinha para os netos e tem pouco dinheiro valem mais que a dieta ideal que não será seguida. O quarto é <strong>intensificar a relação</strong> entre pessoa e médico ao longo do tempo: empatia, confiança, continuidade, consciência das próprias reações. Versões anteriores do método listavam ainda a prevenção e o realismo (tempo e recursos), hoje incorporados aos quatro.</p>
<p>A evidência mostra que o método melhora satisfação, adesão, controle de doenças crônicas e reduz exames e encaminhamentos. Ele não é o oposto da competência técnica: a hemoglobina glicada continua sendo medida, mas a decisão sobre como baixá-la é compartilhada. O erro oposto, a <strong>consulta centrada no médico</strong>, é diretiva, foca a doença, decide pela pessoa e explica por que tantos planos "perfeitos" fracassam. Ferramentas como o genograma e a abordagem familiar complementam o segundo componente; a decisão compartilhada, o terceiro.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quatro perguntas que cabem em qualquer consulta: "O que você acha que está acontecendo?", "O que mais a preocupa nisso?", "Como isso tem atrapalhado o seu dia a dia?", "O que você espera que a gente faça hoje?". As respostas são o material do plano conjunto.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Quatro componentes: explorar doença e experiência da doença; pessoa como um todo; plano conjunto; relação.</li>
<li>Experiência da doença: sentimentos, ideias, função e expectativas (SIFE).</li>
<li>Terreno comum: problemas, metas e papéis acordados, adaptados ao contexto real.</li>
<li>Melhora adesão, satisfação e controle de crônicos; não dispensa a técnica, compartilha a decisão.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que quatro dimensões compõem a experiência da doença no MCCP? <details><summary>Resposta</summary>Sentimentos, ideias, função e expectativas.</details></li>
<li>O que significa "terreno comum"? <details><summary>Resposta</summary>O acordo entre médico e pessoa sobre a definição dos problemas, as metas do tratamento e o papel de cada um.</details></li>
</ol>
`,

"sirio2027#87": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Diagnosticar o episódio depressivo na APS e graduar a sua gravidade.</li>
<li>Escolher e iniciar o antidepressivo de primeira linha, orientando a latência.</li>
<li>Planejar o desmame seguro de um benzodiazepínico de uso crônico.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Episódio depressivo</dt>
<dd>Humor deprimido ou anedonia por pelo menos duas semanas, com sintomas somáticos e cognitivos e prejuízo funcional.</dd>
<dt>ISRS</dt>
<dd>Inibidores seletivos da recaptação de serotonina (sertralina, fluoxetina, escitalopram, citalopram, paroxetina): primeira linha pela eficácia e segurança.</dd>
<dt>Latência</dt>
<dd>Intervalo de duas a quatro semanas entre o início do antidepressivo e a melhora clínica perceptível; resposta plena em seis a oito.</dd>
<dt>Desmame de benzodiazepínico</dt>
<dd>Redução gradual de 10 a 25% da dose a cada duas a quatro semanas, mais lenta no fim, para evitar abstinência e recaída da insônia.</dd>
</dl>
<h4>O essencial</h4>
<p>A depressão é a condição de saúde mental mais frequente na APS, e o diagnóstico é clínico: pelo menos <strong>duas semanas</strong> de humor deprimido ou perda de interesse, acompanhados de alterações de sono e apetite, fadiga, dificuldade de concentração, sentimentos de inutilidade ou culpa, lentificação ou agitação e ideias de morte. O <strong>PHQ-9</strong> ajuda a graduar: leve (5 a 9), moderada (10 a 14), moderadamente grave (15 a 19), grave (20 ou mais).</p>
<p>No episódio leve, a primeira linha é psicoterapia, atividade física e acompanhamento; no <strong>moderado a grave</strong>, antidepressivo, de preferência combinado à psicoterapia. Os <strong>ISRS</strong> são a escolha pela eficácia equivalente aos tricíclicos com muito mais segurança; a <strong>sertralina</strong> (50 mg, até 200 mg) e o escitalopram (10 a 20 mg) são boas opções na APS, e a fluoxetina (20 a 60 mg) está na RENAME.</p>
<p>O <strong>benzodiazepínico crônico</strong> é problema à parte: causa dependência, piora a cognição, aumenta quedas e, em uso prolongado, pode contribuir para a depressão. A retirada é <strong>gradual</strong> e negociada, depois de iniciar o antidepressivo e estabilizar o humor, com reduções de 10 a 25% a cada duas a quatro semanas e higiene do sono; em alguns casos troca-se por diazepam, de meia-vida longa, para facilitar. Nunca se aumenta o benzodiazepínico para "cobrir" a insônia da depressão, e nunca se corta de forma abrupta após uso prolongado, pelo risco de abstinência com insônia rebote, ansiedade e, raramente, convulsão.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Receita de primeira consulta na APS: sertralina 50 mg pela manhã, retorno em 15 dias para adesão e efeitos, PHQ-9 a cada visita, plano de segurança se houver ideação, encaminhamento ao CAPS se risco de suicídio, psicose ou refratariedade. O clonazepam fica na mesma dose até a melhora, e então começa a descer.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Depressão: duas semanas de humor deprimido ou anedonia mais sintomas associados; PHQ-9 gradua; perguntar sobre suicídio.</li>
<li>Moderada a grave: ISRS (sertralina, escitalopram, fluoxetina) e psicoterapia; latência de duas a quatro semanas; manter seis a doze meses.</li>
<li>Benzodiazepínico crônico: desmame gradual após a melhora do humor; nunca aumentar nem cortar de uma vez.</li>
<li>Amitriptilina não é primeira linha; buspirona não trata depressão.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quanto tempo o paciente deve esperar pela melhora após iniciar um ISRS? <details><summary>Resposta</summary>Duas a quatro semanas para a melhora inicial, com resposta plena em seis a oito semanas.</details></li>
<li>Como se retira um benzodiazepínico usado há um ano? <details><summary>Resposta</summary>Gradualmente, reduzindo 10 a 25% da dose a cada duas a quatro semanas, após estabilizar o humor com o antidepressivo.</details></li>
</ol>
`,

"sirio2027#88": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a polifarmácia e os medicamentos potencialmente inadequados no idoso.</li>
<li>Usar os critérios de Beers e a avaliação geriátrica ampla para priorizar a desprescrição.</li>
<li>Planejar a retirada segura de um benzodiazepínico no idoso.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Polifarmácia</dt>
<dd>Uso de cinco ou mais medicamentos; aumenta interações, efeitos adversos, quedas e internações.</dd>
<dt>Critérios de Beers</dt>
<dd>Lista da American Geriatrics Society de medicamentos a evitar em idosos, por classe e por condição.</dd>
<dt>Desprescrição</dt>
<dd>Processo planejado de reduzir ou retirar medicamentos cujos riscos superam os benefícios, com acompanhamento.</dd>
<dt>Escalas de Katz e Lawton</dt>
<dd>Avaliam atividades básicas (banho, vestir, transferência) e instrumentais (compras, finanças, medicação) da vida diária.</dd>
</dl>
<h4>O essencial</h4>
<p>A idosa de 82 anos tem a tríade geriátrica de risco: <strong>quedas</strong>, <strong>confusão intermitente</strong> e <strong>incontinência</strong>, mais dependência funcional (Katz e Lawton alterados) e <strong>sete medicamentos</strong>. Quedas em idosos são multifatoriais, mas os psicotrópicos são o fator modificável mais importante.</p>
<p>A <strong>desprescrição</strong> segue um método: listar tudo o que a pessoa toma, inclusive o que compra por conta própria; identificar a indicação de cada item; avaliar risco e benefício no contexto da expectativa de vida e das metas; priorizar o que tem maior dano e menor benefício; retirar <strong>um de cada vez</strong>, de forma gradual quando há risco de abstinência, e monitorar. Aqui o primeiro alvo é o <strong>alprazolam</strong>, sem indicação definida; o segundo, a <strong>amitriptilina</strong>; depois se reavalia a hipotensão ortostática (queda de 25 mmHg na sistólica ao levantar), reduzindo a hidroclorotiazida ou ajustando o losartana, e se questiona o omeprazol crônico e a estatina numa idosa frágil.</p>
<p>A retirada do benzodiazepínico no idoso é <strong>gradual</strong>: 10 a 25% da dose a cada duas a quatro semanas, com explicação à paciente e à filha de que a insônia inicial é esperada e transitória, e medidas de higiene do sono. A avaliação geriátrica ampla completa o cuidado: rastreio cognitivo, visão e audição, força e marcha, ambiente domiciliar (tapetes, iluminação, barras no banheiro), vitamina D, e a questão de uma idosa dependente morando sozinha em área rural, que exige rede de apoio e assistência social.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Pergunta de triagem em toda consulta de idoso: "caiu nos últimos 12 meses?" Uma queda ou medo de cair já indica revisão da medicação, teste de levantar e andar cronometrado (acima de 12 segundos é risco) e medida da pressão em pé. Benzodiazepínico em idoso que cai é a primeira coisa a sair da receita.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Quedas, confusão e incontinência em idosa polimedicada: pensar em medicamento antes de doença nova.</li>
<li>Beers: benzodiazepínicos e tricíclicos no topo da lista a evitar; alprazolam primeiro, amitriptilina depois.</li>
<li>Desprescrever um medicamento por vez, de forma gradual, com monitoramento; hipotensão ortostática pede revisão do diurético.</li>
<li>Avaliação geriátrica ampla e ambiente seguro completam a prevenção de quedas.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que duas classes de psicotrópicos os critérios de Beers mandam evitar em idosos com quedas? <details><summary>Resposta</summary>Benzodiazepínicos e antidepressivos tricíclicos (além de antipsicóticos e hipnóticos Z).</details></li>
<li>Como se define hipotensão ortostática? <details><summary>Resposta</summary>Queda de 20 mmHg ou mais na sistólica, ou de 10 mmHg na diastólica, em até 3 minutos após levantar.</details></li>
</ol>
`,

"sirio2027#89": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Aplicar a regra ABCDE e o sinal do patinho feio às lesões pigmentadas.</li>
<li>Escolher a biópsia excisional com margens estreitas como passo diagnóstico.</li>
<li>Relacionar o Breslow às margens definitivas e ao linfonodo sentinela.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>ABCDE</dt>
<dd>Assimetria, Bordas irregulares, Cores variadas, Diâmetro acima de 6 mm, Evolução: sinais de suspeita de melanoma.</dd>
<dt>Biópsia excisional</dt>
<dd>Retirada completa da lesão com 1 a 3 mm de margem, para exame histopatológico de toda a espessura.</dd>
<dt>Índice de Breslow</dt>
<dd>Espessura do melanoma em milímetros, da camada granulosa ao ponto mais profundo; principal fator prognóstico e guia das margens.</dd>
<dt>Linfonodo sentinela</dt>
<dd>Primeiro linfonodo de drenagem, pesquisado em melanomas com Breslow acima de 0,8 mm ou com ulceração.</dd>
</dl>
<h4>O essencial</h4>
<p>O melanoma é menos de 5% dos cânceres de pele, mas causa a maioria das mortes, e o prognóstico depende do diagnóstico precoce. Os fatores de risco são exposição solar intermitente e queimaduras, pele clara, muitos nevos, nevos atípicos, história familiar e imunossupressão; trabalhadores ao ar livre, como o da construção civil, acumulam exposição. A regra <strong>ABCDE</strong> (assimetria, bordas irregulares, cores variadas, diâmetro acima de 6 mm, evolução) e o <strong>sinal do patinho feio</strong> (a lesão diferente das demais do paciente) orientam a suspeita; sangramento, prurido e "ferida que não cicatriza" são sinais tardios.</p>
<p>Diante da suspeita, o passo é a <strong>biópsia excisional</strong> com margens estreitas de 1 a 3 mm, incluindo a hipoderme, orientada no sentido da drenagem linfática. Ela permite ao patologista medir o <strong>Breslow</strong>, a ulceração, o índice mitótico e as margens, informações que definem o estádio e a conduta. Biópsia incisional ou por punch só em lesões muito grandes ou em áreas nobres; <em>shaving</em> é proibido, porque corta a lesão e inviabiliza o Breslow. Nunca se destrói uma lesão pigmentada suspeita com crioterapia, eletrocoagulação ou laser.</p>
<p>Com o laudo, decide-se a <strong>ampliação de margens</strong>: 0,5 a 1 cm no melanoma in situ, 1 cm até 1 mm de espessura, 1 a 2 cm entre 1 e 2 mm, e 2 cm acima de 2 mm. A <strong>pesquisa do linfonodo sentinela</strong> é indicada a partir de 0,8 mm de Breslow ou com ulceração, e o estadiamento com imagem para doença mais espessa ou com linfonodos positivos. Na doença avançada, a imunoterapia (anti-PD-1, anti-CTLA-4) e os inibidores de BRAF e MEK mudaram a sobrevida. A prevenção é fotoproteção, autoexame e exame da pele em consultas de rotina, sobretudo em quem trabalha ao sol.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na APS, lesão pigmentada com qualquer item do ABCDE ou que mudou nos últimos meses não espera: encaminhamento prioritário para biópsia excisional, com registro fotográfico. A dermatoscopia aumenta a acurácia em quem é treinado, mas não substitui a histologia quando a suspeita existe.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Suspeita: ABCDE, patinho feio, lesão que muda, sangra ou não cicatriza, em pele exposta ao sol.</li>
<li>Diagnóstico: biópsia excisional com 1 a 3 mm de margem; nunca shaving, crioterapia ou pomada.</li>
<li>Breslow define as margens definitivas (0,5 a 2 cm) e a pesquisa do linfonodo sentinela (a partir de 0,8 mm ou ulceração).</li>
<li>Prevenção: fotoproteção e exame da pele, com atenção aos trabalhadores ao ar livre.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a biópsia excisional inicial usa margens estreitas e não a margem oncológica? <details><summary>Resposta</summary>Porque a margem definitiva depende do Breslow, só conhecido após a histologia, e margens largas prematuras prejudicam o linfonodo sentinela.</details></li>
<li>A partir de que espessura se pesquisa o linfonodo sentinela? <details><summary>Resposta</summary>Breslow de 0,8 mm ou mais, ou qualquer espessura com ulceração.</details></li>
</ol>
`,

"sirio2027#90": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Avaliar a dispneia em cuidados paliativos e identificar a dispneia refratária.</li>
<li>Prescrever opioide em baixa dose para dispneia com segurança.</li>
<li>Situar a sedação paliativa como último recurso, com seus critérios.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Dispneia refratária</dt>
<dd>Falta de ar que persiste apesar do tratamento otimizado da causa e das medidas não farmacológicas.</dd>
<dt>Cuidados paliativos exclusivos</dt>
<dd>Fase em que o tratamento modificador da doença foi suspenso e o objetivo é conforto e qualidade de vida.</dd>
<dt>Morfina em baixa dose</dt>
<dd>2,5 a 5 mg por via oral (ou 1 a 2,5 mg subcutânea) a cada 4 horas, com resgates, titulando pelo alívio.</dd>
<dt>Sedação paliativa</dt>
<dd>Redução deliberada da consciência para aliviar sofrimento refratário na terminalidade, após decisão compartilhada.</dd>
</dl>
<h4>O essencial</h4>
<p>A dispneia é um dos sintomas mais angustiantes no fim da vida, presente em quase todos os pacientes com DPOC avançada e em metade dos com câncer.</p>
<p>Quando a dispneia persiste, o tratamento farmacológico de primeira linha é o <strong>opioide em baixa dose</strong>. A morfina reduz a sensação de falta de ar por ação central, diminui a frequência respiratória e o consumo de oxigênio, e a evidência de ensaios clínicos em DPOC e câncer mostra alívio sem depressão respiratória clinicamente relevante nas doses usadas. Em pacientes virgens de opioide: morfina 2,5 a 5 mg por via oral a cada 4 horas, ou 1 a 2,5 mg subcutânea, com doses de resgate iguais à dose regular, titulando a cada 24 horas; em quem já usa opioide para dor, aumenta-se 25%.</p>
<p>Benzodiazepínicos não tratam a dispneia em si; servem para a ansiedade associada, em segunda linha e em dose baixa. Broncodilatadores e corticoides tratam o componente obstrutivo e já fazem parte do esquema do DPOC; salina hipertônica e furosemida sem indicação são erros. A <strong>sedação paliativa</strong> fica para o sintoma refratário a tudo, inclusive ao opioide bem titulado, na terminalidade, após discussão com o paciente (enquanto lúcido) e com a família, registro em prontuário e, idealmente, avaliação de uma segunda opinião; usa-se midazolam titulado ao conforto, não à inconsciência.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Prescrição domiciliar típica: morfina solução oral 10 mg/mL, 2,5 mg (0,25 mL) a cada 4 horas e 2,5 mg de resgate até de hora em hora se necessário; ventilador portátil; lactulose; metoclopramida se náusea. Reavaliar em 24 a 48 horas e ensinar a família a registrar os resgates: três ou mais por dia indicam subir a dose regular.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Dispneia no fim da vida: tratar o tratável, medidas não farmacológicas (ventilador no rosto, posição, família), oxigênio só se hipoxemia.</li>
<li>Refratária: morfina em baixa dose regular com resgates, titulando; sem depressão respiratória relevante.</li>
<li>Benzodiazepínico só para a ansiedade associada, em segunda linha.</li>
<li>Sedação paliativa é o último recurso, proporcional, com decisão compartilhada e registro.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a dose inicial de morfina para dispneia num paciente que nunca usou opioide? <details><summary>Resposta</summary>2,5 a 5 mg por via oral a cada 4 horas (ou 1 a 2,5 mg subcutânea), com resgates, titulando pelo alívio.</details></li>
<li>Quando a sedação paliativa está indicada? <details><summary>Resposta</summary>Para sofrimento refratário a todas as medidas, inclusive opioide titulado, na terminalidade, após decisão compartilhada e registro.</details></li>
</ol>
`,

"sirio2027#91": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer os direitos da pessoa com deficiência na saúde segundo a Lei Brasileira de Inclusão.</li>
<li>Identificar barreiras arquitetônicas, atitudinais e comunicacionais nos serviços.</li>
<li>Descrever a Rede de Cuidados à Pessoa com Deficiência no SUS.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Lei Brasileira de Inclusão (13.146/2015)</dt>
<dd>Estatuto da Pessoa com Deficiência: igualdade, atendimento prioritário, acessibilidade e proibição de discriminação.</dd>
<dt>Modelo social da deficiência</dt>
<dd>A deficiência resulta da interação entre o impedimento do corpo e as barreiras do ambiente; remover barreiras reduz a deficiência.</dd>
<dt>Barreiras</dt>
<dd>Obstáculos urbanísticos, arquitetônicos, de transporte, comunicacionais, atitudinais e tecnológicos ao exercício de direitos.</dd>
<dt>Rede de Cuidados à Pessoa com Deficiência</dt>
<dd>Componentes de APS, atenção especializada (CER) e hospitalar e de urgência, articulados (Portaria 793/2012).</dd>
</dl>
<h4>O essencial</h4>
<p>Cerca de 8% dos brasileiros têm alguma deficiência. A <strong>Lei Brasileira de Inclusão</strong>, que incorporou a Convenção da ONU, adota o <strong>modelo social</strong>: a deficiência não está só no corpo, mas no encontro do impedimento com um ambiente cheio de barreiras.</p>
<p>Nos serviços de saúde as barreiras são de vários tipos. <strong>Arquitetônicas</strong>: ausência de rampa, sanitário acessível, maca regulável, balança para cadeirante. <strong>Comunicacionais</strong>: falta de intérprete de Libras, de material em braile, de linguagem simples para a deficiência intelectual. <strong>Atitudinais</strong>: falar com o acompanhante em vez de com a pessoa, infantilizar, supor incapacidade de decidir, negar prioridade "porque a fila é igual para todos". A LBI considera discriminação toda distinção que prejudique o exercício de direitos, e o gestor que não adequa a unidade responde por isso.</p>
<p>A <strong>Rede de Cuidados à Pessoa com Deficiência</strong> (2012) organiza a APS como coordenadora, com identificação precoce, acompanhamento e encaminhamento; os <strong>Centros Especializados em Reabilitação</strong> (CER II, III e IV, conforme as modalidades física, auditiva, visual e intelectual) e as oficinas ortopédicas; e a atenção hospitalar e de urgência.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Boas práticas na consulta: dirigir-se à pessoa, não ao acompanhante; perguntar como ela prefere ser transferida para a maca; ter balança e maca acessíveis ou registrar a necessidade; garantir a prioridade na fila e na regulação; e registrar as barreiras encontradas em comunicação formal à gestão, com cópia no prontuário.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>LBI (2015): modelo social, atendimento prioritário, acessibilidade e atenção integral à saúde.</li>
<li>Barreiras arquitetônicas, comunicacionais e atitudinais nos serviços são discriminação a ser removida.</li>
<li>Prioridade na fila e na regulação é direito, não favor; o gestor responde pela adequação da unidade.</li>
<li>Rede de Cuidados à Pessoa com Deficiência: APS coordena, CER reabilita, hospital e urgência completam.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual artigo da LBI garante o atendimento prioritário à pessoa com deficiência? <details><summary>Resposta</summary>O art. 9º, que inclui atendimento em todas as instituições e serviços ao público e tramitação prioritária.</details></li>
<li>O que são barreiras atitudinais? <details><summary>Resposta</summary>Atitudes e comportamentos que impedem a participação da pessoa com deficiência, como falar com o acompanhante em vez de com ela ou presumir incapacidade.</details></li>
</ol>
`,

"sirio2027#92": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar os princípios da Política Nacional de Educação Popular em Saúde.</li>
<li>Distinguir educação popular de educação sanitária tradicional.</li>
<li>Aplicar metodologias participativas no território.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Educação popular em saúde</dt>
<dd>Prática educativa dialógica, inspirada em Paulo Freire, que parte dos saberes e da realidade das pessoas para construir conhecimento e autonomia.</dd>
<dt>PNEPS-SUS</dt>
<dd>Política Nacional de Educação Popular em Saúde no SUS (Portaria 2.761/2013), com seis princípios.</dd>
<dt>Educação bancária</dt>
<dd>Termo de Freire para o ensino que "deposita" conteúdos em quem supostamente nada sabe.</dd>
<dt>Roda de conversa</dt>
<dd>Metodologia em que todos falam e escutam em igualdade, problematizando a realidade e construindo respostas coletivas.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>educação sanitária</strong> tradicional transmite informação técnica de quem sabe para quem não sabe, com palestras e cartilhas, e supõe que o comportamento muda quando a pessoa é informada. Décadas de campanhas mostraram o limite: as pessoas sabem que o mosquito nasce na água parada e as caixas d'água continuam abertas, porque o problema não é só informação, mas condições de vida, prioridades, confiança e sentido.</p>
<p>A <strong>PNEPS-SUS</strong> (2013) tem seis princípios: <strong>diálogo</strong> (encontro de saberes diferentes em igualdade); <strong>amorosidade</strong> (afeto e respeito nas relações); <strong>problematização</strong> (ler criticamente a realidade e suas causas); <strong>construção compartilhada do conhecimento</strong>; <strong>emancipação</strong> (autonomia e superação das opressões); e <strong>compromisso com a construção do projeto democrático e popular</strong>. Seus eixos incluem a participação e o controle social, a formação dos trabalhadores, o cuidado em saúde e a intersetorialidade.</p>
<p>Na prática da APS, a educação popular aparece nas <strong>rodas de conversa</strong>, nos grupos de hipertensos que definem o próprio tema, nas oficinas com agentes comunitários, no mapa falante construído com os moradores, nas práticas integrativas em grupo, no trabalho com lideranças e associações. Na dengue, significa entender com a comunidade por que os criadouros persistem (falta de tampa, água intermitente que obriga a estocar, terreno baldio do vizinho ausente) e agir sobre as causas junto com a prefeitura, em lugar de culpar o morador. O resultado é adesão duradoura porque as soluções são das pessoas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Teste rápido para saber se a atividade é educação popular: quem definiu o tema? quem fala mais? o que a equipe aprendeu? o que mudou no plano a partir do que a comunidade disse? Se as respostas forem "a equipe", "a equipe", "nada" e "nada", foi palestra com cadeiras em círculo.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Educação sanitária transmite; educação popular dialoga, problematiza e constrói com as pessoas (Freire).</li>
<li>PNEPS-SUS (2013): diálogo, amorosidade, problematização, construção compartilhada, emancipação, compromisso democrático.</li>
<li>Vale para qualquer grupo, não só para quem tem pouca escolaridade.</li>
<li>Na dengue: entender com a comunidade por que os criadouros persistem e agir sobre as causas.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os seis princípios da PNEPS-SUS? <details><summary>Resposta</summary>Diálogo, amorosidade, problematização, construção compartilhada do conhecimento, emancipação e compromisso com o projeto democrático e popular.</details></li>
<li>O que Freire chamou de educação bancária? <details><summary>Resposta</summary>O ensino que deposita conteúdos em quem é visto como vazio de saber, sem diálogo nem problematização.</details></li>
</ol>
`,

"sirio2027#94": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir coordenação do cuidado e longitudinalidade como atributos da APS.</li>
<li>Distinguir referência, contrarreferência e cuidado compartilhado.</li>
<li>Delimitar o que a APS assume e o que permanece com o especialista.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Coordenação do cuidado</dt>
<dd>Atributo da APS de integrar as informações e as ações dos vários serviços que a pessoa usa, garantindo continuidade.</dd>
<dt>Longitudinalidade</dt>
<dd>Relação pessoal e duradoura entre a equipe e a pessoa ao longo do tempo, independentemente do problema.</dd>
<dt>Contrarreferência</dt>
<dd>Retorno formal de informação do nível especializado à APS, com diagnóstico, conduta e plano de acompanhamento.</dd>
<dt>Cuidado compartilhado</dt>
<dd>Arranjo em que APS e especialista dividem tarefas definidas no seguimento de uma condição, com comunicação regular.</dd>
</dl>
<h4>O essencial</h4>
<p>Starfield descreveu quatro atributos essenciais da APS: <strong>acesso de primeiro contato</strong>, <strong>longitudinalidade</strong>, <strong>integralidade</strong> e <strong>coordenação</strong>, mais os derivados (orientação familiar, comunitária e competência cultural). A <strong>coordenação do cuidado</strong> é o que faz da APS o centro da rede: ela conhece a pessoa inteira, sabe quem a atende, reúne os resultados e as decisões de cada serviço e evita duplicações, interações e lacunas. Sem coordenação, o paciente com várias doenças tem vários médicos e nenhum cuidado.</p>
<p>O instrumento da coordenação é a <strong>comunicação formal</strong> entre níveis: a <strong>referência</strong>, encaminhamento com motivo, dados e pergunta clara; e a <strong>contrarreferência</strong>, resposta do especialista com diagnóstico, conduta, o que a APS deve monitorar e quando o paciente volta. O caso da artrite reumatoide é o modelo: o reumatologista ajusta o imunossupressor e pede à APS o monitoramento mensal de hemograma e transaminases, com retorno em um ano.</p>
<p>O que fica com o especialista é o que exige a sua expertise: ajustar doses de metotrexato ou de biológico, decidir trocas de esquema. Isso não precisa de "protocolo municipal" para acontecer: pedir hemograma e enzimas é competência ordinária da APS, e condicionar o cuidado a um documento inexistente é recusa disfarçada. Também não se faz do paciente o mensageiro entre guichês. Ferramentas que facilitam: prontuário eletrônico compartilhado, teleinterconsulta (Telessaúde), matriciamento e protocolos de acesso regulado que definem o que cada nível faz em cada condição.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao receber uma contrarreferência, registre o plano no prontuário, agende os exames e a consulta de rotina, defina quais resultados disparam o contato com o especialista (por exemplo, transaminases acima de três vezes o limite ou leucócitos abaixo de 3.000) e combine com a paciente o canal para dúvidas. Isso é coordenação em ato.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Atributos essenciais da APS: primeiro contato, longitudinalidade, integralidade e coordenação (Starfield).</li>
<li>Referência pergunta; contrarreferência responde com conduta e plano; a APS integra e segue.</li>
<li>A APS assume o monitoramento e o cuidado longitudinal; o ajuste de imunossupressores fica com o especialista.</li>
<li>Não se exige protocolo para exames de rotina nem se faz do paciente mensageiro.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os quatro atributos essenciais da APS segundo Starfield? <details><summary>Resposta</summary>Acesso de primeiro contato, longitudinalidade, integralidade e coordenação do cuidado.</details></li>
<li>O que deve conter uma contrarreferência adequada? <details><summary>Resposta</summary>Diagnóstico, conduta adotada, o que a APS deve monitorar e com que frequência, e quando e por que o paciente retorna ao especialista.</details></li>
</ol>
`,

"sirio2027#95": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Classificar a dor lombar aguda e identificar os sinais de alerta.</li>
<li>Conduzir a lombalgia mecânica inespecífica sem exame de imagem.</li>
<li>Reconhecer a dor lombar relacionada ao trabalho e o papel da ergonomia.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Lombalgia mecânica inespecífica</dt>
<dd>Dor lombar sem causa estrutural identificável, relacionada a esforço e postura; 85 a 90% dos casos.</dd>
<dt>Sinais de alerta (red flags)</dt>
<dd>Febre, perda de peso, câncer prévio, trauma, idade acima de 50 ou abaixo de 20, déficit neurológico, alteração esfincteriana, imunossupressão, uso de corticoide.</dd>
<dt>Síndrome da cauda equina</dt>
<dd>Retenção ou incontinência, anestesia em sela e fraqueza bilateral: emergência cirúrgica.</dd>
<dt>Fatores de risco psicossociais (yellow flags)</dt>
<dd>Medo do movimento, catastrofização, insatisfação no trabalho e depressão: predizem cronificação.</dd>
</dl>
<h4>O essencial</h4>
<p>A dor lombar é a principal causa de incapacidade no mundo e uma das queixas mais frequentes na APS. A anamnese e o exame classificam em três grupos: <strong>inespecífica</strong> (85 a 90%), <strong>radicular</strong> (ciatalgia com irradiação abaixo do joelho, Lasègue positivo, déficit no dermátomo) e <strong>causa específica grave</strong> (fratura, infecção, tumor, cauda equina), rastreada pelos <strong>sinais de alerta</strong>.</p>
<p>A conduta da lombalgia inespecífica é <strong>educação e atividade</strong>: explicar que a dor é benigna e autolimitada (a maioria melhora em quatro a seis semanas), que a coluna é forte e que o movimento cura; manter o trabalho e as atividades conforme a tolerância; calor local; <strong>analgesia</strong> com paracetamol ou AINE em dose e tempo curtos se necessário, relaxante muscular por poucos dias em casos selecionados; e <strong>evitar o repouso no leito</strong>, que atrasa a recuperação.</p>
<p>A dor que começa após esforço no trabalho não é, por si, doença ocupacional, mas a lombalgia é a principal causa de afastamento e de <strong>LER/DORT</strong> entre trabalhadores de carga, e o nexo ocupacional pede ação: orientar ergonomia (técnica de levantamento, rodízio, pausas), comunicar o afastamento se necessário, e, quando o quadro é crônico e relacionado ao trabalho, notificar como LER/DORT no SINAN e articular com a Vigilância em Saúde do Trabalhador.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Script de consulta: "Seus exames físicos estão normais e não há nada grave. Essa dor melhora em poucas semanas, e o melhor remédio é continuar ativo. Tome o analgésico quando precisar e evite ficar deitado. Volte se a dor descer para a perna, se fraquejar ou se tiver dificuldade para urinar." Marcar retorno em duas a quatro semanas se não melhorar.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Três grupos: inespecífica (85 a 90%), radicular e causa grave; os sinais de alerta separam a terceira.</li>
<li>Sem sinais de alerta: nenhum exame de imagem; educação, atividade, analgesia curta; sem repouso no leito.</li>
<li>Melhora em quatro a seis semanas; fisioterapia se não melhorar; cirurgia e opioide não entram.</li>
<li>Relacionada ao trabalho: ergonomia, afastamento se preciso, LER/DORT no SINAN quando crônica.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que achados obrigam a investigar a dor lombar com imagem e urgência? <details><summary>Resposta</summary>Sinais de alerta: déficit neurológico progressivo, alteração esfincteriana ou anestesia em sela, febre, perda de peso, câncer prévio, trauma significativo.</details></li>
<li>Qual orientação tem maior impacto na recuperação da lombalgia inespecífica? <details><summary>Resposta</summary>Manter-se ativo e continuar as atividades habituais conforme a tolerância, evitando o repouso no leito.</details></li>
</ol>
`,

"sirio2027#97": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever o papel da ANS na regulação da saúde suplementar.</li>
<li>Explicar o Rol de Procedimentos e Eventos em Saúde e a mudança da Lei 14.454/2022.</li>
<li>Distinguir ANS, Anvisa e Conitec.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>ANS</dt>
<dd>Agência Nacional de Saúde Suplementar (Lei 9.961/2000), autarquia vinculada ao Ministério da Saúde que regula, normatiza e fiscaliza os planos privados.</dd>
<dt>Rol de Procedimentos e Eventos em Saúde</dt>
<dd>Lista da ANS que define a cobertura mínima obrigatória dos planos regulamentados, atualizada continuamente.</dd>
<dt>Lei 9.656/1998</dt>
<dd>Marco legal dos planos de saúde: segmentações, carências, cobertura obrigatória, reajustes, proibição de rescisão unilateral.</dd>
<dt>Ressarcimento ao SUS</dt>
<dd>Cobrança da operadora quando um beneficiário é atendido no SUS por procedimento coberto pelo plano.</dd>
</dl>
<h4>O essencial</h4>
<p>Cerca de um quarto dos brasileiros tem plano de saúde, e o setor movimenta mais que o orçamento federal do SUS. Até 1998 ele era quase sem regras; a <strong>Lei 9.656/1998</strong> definiu segmentações (ambulatorial, hospitalar, obstétrica, odontológica), carências máximas, cobertura mínima e proibiu a exclusão de doenças preexistentes após 24 meses. A <strong>ANS</strong>, criada em 2000, é a agência reguladora: autoriza operadoras, define e atualiza o <strong>Rol</strong>, controla reajustes de planos individuais, fiscaliza e aplica multas, administra o ressarcimento ao SUS e mantém índices de reclamação e qualidade.</p>
<p>O <strong>Rol de Procedimentos e Eventos em Saúde</strong> lista o que todo plano regulamentado deve cobrir, com diretrizes de utilização. Sua atualização passa por uma comissão técnica (COSAÚDE), avaliação de evidências e consulta pública, em ciclos contínuos desde 2021.</p>
<p>Três órgãos se confundem na prova. A <strong>Anvisa</strong> registra e fiscaliza produtos (medicamentos, alimentos, cosméticos) e serviços de saúde quanto ao risco sanitário. A <strong>Conitec</strong> decide o que o <strong>SUS</strong> incorpora e escreve os PCDT. A <strong>ANS</strong> regula os <strong>planos privados</strong> e o seu Rol. Um medicamento pode estar registrado na Anvisa, fora do SUS e fora do Rol, ou qualquer combinação; e a judicialização contra planos segue critérios semelhantes aos do SUS, com a Lei 14.454 como base.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Diante de uma negativa do plano, oriente o paciente a pedir a negativa por escrito com o motivo, verificar se o item está no Rol e nas diretrizes de utilização, registrar reclamação na ANS (que abre a Notificação de Intermediação Preliminar, resolvendo a maioria dos casos em dias) e, se for o caso, recorrer à Justiça com laudo que cite a evidência científica.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Lei 9.656/1998 regula os planos; ANS (2000) normatiza, fiscaliza, define o Rol e cobra o ressarcimento ao SUS.</li>
<li>Rol é a cobertura mínima; desde a Lei 14.454/2022, o plano cobre fora do Rol com evidência científica ou recomendação da Conitec/ATS.</li>
<li>Anvisa registra produtos; Conitec incorpora no SUS; ANS regula planos.</li>
<li>Negativa do plano: pedir por escrito, reclamar na ANS (NIP), judicializar com laudo e evidência.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>O que mudou com a Lei 14.454/2022? <details><summary>Resposta</summary>O Rol da ANS passou a ser referência mínima: o plano deve cobrir tratamentos fora dele quando há comprovação científica de eficácia ou recomendação da Conitec ou de órgão internacional de ATS.</details></li>
<li>Qual órgão incorpora tecnologias no SUS e qual regula os planos privados? <details><summary>Resposta</summary>A Conitec incorpora no SUS; a ANS regula a saúde suplementar.</details></li>
</ol>
`,

"sirio2027#98": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Entender por que a judicialização da saúde cresceu e quais tensões produz.</li>
<li>Conhecer os critérios do STJ (Tema 106) e do STF (Tema 6) para medicamentos não incorporados.</li>
<li>Saber o que o médico deve escrever num laudo para fins judiciais.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Judicialização da saúde</dt>
<dd>Busca do Judiciário para obter medicamentos, procedimentos ou leitos negados administrativamente.</dd>
<dt>Tema 106 do STJ (2018)</dt>
<dd>Requisitos cumulativos para medicamento fora da lista do SUS: laudo fundamentado, incapacidade financeira e registro na Anvisa.</dd>
<dt>Tema 6 do STF (2024)</dt>
<dd>Regra geral de não fornecimento judicial de medicamento não incorporado, com exceções estritas e cumulativas.</dd>
<dt>NatJus</dt>
<dd>Núcleos de apoio técnico do Judiciário que emitem pareceres baseados em evidência para orientar os juízes.</dd>
</dl>
<h4>O essencial</h4>
<p>A judicialização explodiu a partir dos anos 2000, com centenas de milhares de ações por ano e gasto federal de bilhões de reais em medicamentos por decisão judicial, muitos de alto custo e sem incorporação. Ela expressa o direito individual à saúde (CF, art. 196) e corrige falhas reais do sistema (filas, desabastecimento, mora da Conitec), mas também produz iniquidade: beneficia quem tem acesso a advogado e laudo, drena recursos de políticas coletivas e pode impor tratamentos sem evidência. Os tribunais superiores buscaram critérios para equilibrar os dois lados.</p>
<p>O <strong>STJ</strong>, no <strong>Tema 106</strong> (2018), fixou três requisitos cumulativos para medicamento não constante das listas do SUS: laudo médico fundamentado e circunstanciado, que comprove a necessidade e a <strong>ineficácia dos fármacos fornecidos pelo SUS</strong>; <strong>incapacidade financeira</strong> do paciente; e <strong>registro na Anvisa</strong>.</p>
<p>O <strong>médico</strong> tem papel central e responsabilidade. O laudo deve descrever o diagnóstico com CID, os tratamentos do SUS já tentados e por que falharam ou são contraindicados, a evidência que sustenta a prescrição (ensaios, diretrizes), a dose e a duração, e declarar a inexistência de conflito de interesse. Laudos genéricos, prescrição por nome comercial sem justificar e indicação fora da bula sem evidência fragilizam o pedido e expõem o profissional.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Antes de encaminhar o paciente à Justiça, confira: existe PCDT para a doença e o paciente já percorreu as opções nele? O pedido administrativo foi feito e negado por escrito? Há evidência de qualidade para o fármaco pedido? O laudo responde a essas três perguntas. Muitos "casos judiciais" se resolvem na farmácia do Componente Especializado com o LME bem preenchido.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Judicialização: direito individual versus política pública; corrige falhas, mas gera iniquidade e custo.</li>
<li>STJ Tema 106: laudo fundamentado com ineficácia das opções do SUS, incapacidade financeira, registro na Anvisa.</li>
<li>STF Tema 6: regra é não fornecer o não incorporado; exceções cumulativas incluem evidência de eficácia, sem substituto no SUS e mora ou ilegalidade da Conitec.</li>
<li>O laudo médico decide: diagnóstico, opções do SUS tentadas, evidência, dose, sem conflito de interesse.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que três requisitos o STJ fixou no Tema 106? <details><summary>Resposta</summary>Laudo médico fundamentado comprovando a necessidade e a ineficácia dos fármacos do SUS; incapacidade financeira do paciente; e registro do medicamento na Anvisa.</details></li>
<li>Pela tese do STF (Tema 6), medicamento sem registro na Anvisa pode ser concedido judicialmente? <details><summary>Resposta</summary>Não, salvo situações excepcionalíssimas; a regra é o registro sanitário como condição.</details></li>
</ol>
`,

/* --- Volume 2 · Preventiva · UNESP 2025 (prev81–prev90) ----------------------------------- */
"unesp2025#81": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer o esquema básico de tratamento da tuberculose e o esquema encurtado pediátrico.</li>
<li>Aplicar os critérios de tuberculose não grave que permitem os quatro meses.</li>
<li>Organizar a investigação e o tratamento dos contatos domiciliares.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Esquema básico (2RHZE/4RH)</dt>
<dd>Dois meses de rifampicina, isoniazida, pirazinamida e etambutol e quatro de rifampicina e isoniazida: seis meses, para adultos e adolescentes.</dd>
<dt>Esquema encurtado (2RHZE/2RH)</dt>
<dd>Quatro meses, para crianças e adolescentes de 3 meses a menos de 16 anos com tuberculose não grave, baseado no ensaio SHINE.</dd>
<dt>Tuberculose não grave</dt>
<dd>Pulmonar restrita a um lobo, sem cavidade nem padrão miliar, ou linfonodal periférica, com bacteriologia negativa e sem sinais de gravidade.</dd>
<dt>TRM-TB</dt>
<dd>Teste rápido molecular (GeneXpert), que detecta o DNA do bacilo e a resistência à rifampicina em duas horas.</dd>
</dl>
<h4>O essencial</h4>
<p>O Brasil notifica cerca de 80 mil casos de tuberculose por ano, e a APS é responsável pelo diagnóstico, pelo tratamento diretamente observado e pelo controle dos contatos. O <strong>esquema básico</strong> para adultos e adolescentes é 2RHZE/4RH, em comprimidos de dose fixa combinada, com baciloscopias mensais de controle. Para <strong>crianças com menos de 10 anos</strong> o esquema era 2RHZ/4RH (sem etambutol, pela dificuldade de monitorar a visão), com doses por peso. Em todos, a adesão é o maior desafio, e o tratamento diretamente observado reduz o abandono.</p>
<p>O ensaio <strong>SHINE</strong> (2022), com 1.200 crianças na África e na Índia, mostrou que quatro meses não são inferiores a seis na tuberculose não grave, e a OMS o incorporou na diretriz de 2022.</p>
<p>O <strong>controle de contatos</strong> completa o cuidado da família: todos os contatos domiciliares são avaliados com história, exame e radiografia; os sintomáticos fazem TRM-TB e escarro; os assintomáticos fazem prova tuberculínica ou IGRA, e a infecção latente é tratada com rifampicina por quatro meses (ou isoniazida por seis a nove, ou isoniazida e rifapentina semanal por três meses). Crianças menores de 10 anos contatos de bacilífero recebem tratamento da infecção latente mesmo com prova negativa inicial, repetida em oito semanas.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Pergunta de prova e de consultório: "esta criança pode fazer quatro meses?" Responda com uma lista: idade entre 3 meses e 16 anos, radiografia de um lobo sem cavidade nem miliar (ou só linfonodo periférico), TRM e baciloscopia negativos, sintomas leves, sem HIV, sem desnutrição grave. Faltando um item, seis meses.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Esquema básico: 2RHZE/4RH, seis meses, para adultos e adolescentes; tratamento diretamente observado.</li>
<li>Encurtado 2RHZE/2RH (quatro meses): 3 meses a menos de 16 anos, tuberculose não grave, bacteriologia negativa (MS 2024, após o SHINE).</li>
<li>Excluem o encurtamento: escarro ou TRM positivo, cavidade, miliar, formas graves, HIV, desnutrição grave, 16 anos ou mais.</li>
<li>Contatos: avaliar todos; infecção latente tratada com rifampicina por quatro meses.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Adolescente de 15 anos com TRM-TB detectado e cavidade no lobo superior pode fazer o esquema de quatro meses? <details><summary>Resposta</summary>Não. Bacteriologia positiva e cavidade são critérios de gravidade; o esquema é o básico de seis meses.</details></li>
<li>Qual é o tratamento preferencial da infecção latente por tuberculose? <details><summary>Resposta</summary>Rifampicina diária por quatro meses (ou isoniazida e rifapentina semanais por três meses).</details></li>
</ol>
`,

"unesp2025#82": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever a Lista de Doenças Relacionadas ao Trabalho e sua base legal.</li>
<li>Usar a classificação de Schilling para estabelecer o nexo com o trabalho.</li>
<li>Relacionar a lista à notificação, à CAT e à vigilância.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>LDRT</dt>
<dd>Lista de Doenças Relacionadas ao Trabalho do Ministério da Saúde, prevista na Lei 8.080 e atualizada pela Portaria 1.999/2023.</dd>
<dt>Classificação de Schilling</dt>
<dd>Grupo I: o trabalho é causa necessária; Grupo II: fator de risco contributivo; Grupo III: desencadeador ou agravante de doença preexistente.</dd>
<dt>Nexo causal</dt>
<dd>Relação entre a doença e o trabalho, estabelecida por história ocupacional, exposição e evidência epidemiológica.</dd>
<dt>CAT</dt>
<dd>Comunicação de Acidente de Trabalho à Previdência, obrigatória para o empregador, emitida também pelo médico, sindicato ou o próprio trabalhador.</dd>
</dl>
<h4>O essencial</h4>
<p>A Lei 8.080 inclui a saúde do trabalhador no campo do SUS e manda o Ministério da Saúde elaborar e revisar periodicamente a <strong>Lista de Doenças Relacionadas ao Trabalho</strong>. A primeira foi a Portaria 1.339/1999; a <strong>Portaria 1.999/2023</strong> a atualizou, ampliando-a para cerca de 165 grupos de doenças (de 198 para 347 códigos da CID-10), com a entrada da covid-19, de mais transtornos mentais e de cânceres relacionados a agentes ocupacionais.</p>
<p>As <strong>finalidades</strong> declaradas pelo Ministério são orientar o uso clínico-epidemiológico, qualificar a atenção integral ao trabalhador, facilitar o estudo da relação entre adoecimento e trabalho, <strong>adotar procedimentos de diagnóstico</strong>, <strong>elaborar projetos terapêuticos mais acurados</strong> e <strong>orientar as ações de vigilância e promoção da saúde</strong> individual e coletiva. A lista é referência para o SUS, para a Previdência (nexo técnico epidemiológico) e para a Justiça do Trabalho, e serve de base para a notificação dos agravos relacionados ao trabalho no SINAN.</p>
<p>O raciocínio clínico usa a <strong>classificação de Schilling</strong>. No <strong>Grupo I</strong> o trabalho é causa necessária: silicose, saturnismo, intoxicação por agrotóxico, asbestose. No <strong>Grupo II</strong> o trabalho é fator de risco contributivo entre outros: câncer de pulmão no exposto a asbesto, hipertensão no trabalho em turnos, LER/DORT, perda auditiva por ruído. No <strong>Grupo III</strong> o trabalho desencadeia ou agrava doença preexistente: asma agravada por poeira, dermatite atópica piorada por irritantes, transtorno mental agravado por assédio.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Toda anamnese de adulto tem a pergunta "o que você faz e com o que trabalha?". Diante de doença da lista, registre o nexo no prontuário, emita a CAT se houver vínculo formal, notifique no SINAN quando for agravo compulsório (LER/DORT, dermatose ocupacional, PAIR, pneumoconiose, transtorno mental, intoxicação, câncer, acidente grave) e comunique a Vigilância em Saúde do Trabalhador para agir na empresa.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>LDRT: prevista na Lei 8.080, atualizada pela Portaria 1.999/2023, dupla entrada agente-doença.</li>
<li>Finalidades: uso clínico-epidemiológico, diagnóstico, projetos terapêuticos, vigilância e promoção.</li>
<li>Schilling I (causa necessária), II (contributivo), III (desencadeador ou agravante).</li>
<li>História ocupacional estabelece o nexo; dele decorrem CAT, notificação e vigilância do ambiente.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Em que grupo de Schilling está a silicose? <details><summary>Resposta</summary>Grupo I: o trabalho (exposição à sílica) é causa necessária.</details></li>
<li>Quem pode emitir a CAT? <details><summary>Resposta</summary>O empregador tem a obrigação, mas na sua omissão podem emitir o médico assistente, o sindicato, o próprio trabalhador ou qualquer autoridade pública.</details></li>
</ol>
`,

"unesp2025#86": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Caracterizar o estudo ecológico e os seus usos legítimos.</li>
<li>Definir falácia ecológica e falácia atomística.</li>
<li>Distinguir falácia ecológica de viés de seleção, confusão e erro de aferição.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Estudo ecológico</dt>
<dd>Desenho em que a unidade de análise é um grupo (país, município, escola) e as variáveis são taxas ou médias.</dd>
<dt>Falácia ecológica</dt>
<dd>Inferir sobre indivíduos a partir de uma associação observada entre grupos.</dd>
<dt>Falácia atomística</dt>
<dd>O erro inverso: inferir sobre grupos a partir de dados individuais.</dd>
<dt>Confusão</dt>
<dd>Distorção da associação por uma terceira variável ligada à exposição e ao desfecho; residual quando persiste após o ajuste.</dd>
</dl>
<h4>O essencial</h4>
<p>O <strong>estudo ecológico</strong> compara agregados: taxa de doença cardiovascular por país contra consumo médio de frutas; mortalidade por município contra cobertura da ESF; incidência de dengue por bairro contra saneamento. Usa dados secundários, é rápido e barato, e é insubstituível para avaliar <strong>políticas</strong> e <strong>exposições que só existem no nível coletivo</strong> (lei, poluição do ar de uma cidade, fluoretação da água). Também gera hipóteses: foi um estudo ecológico que associou gordura saturada e doença coronariana entre países, antes das coortes.</p>
<p>Seu limite é a <strong>falácia ecológica</strong>: a associação entre as médias dos grupos não garante a associação nas pessoas. Países com mais frutas podem ter menos doença cardiovascular porque são mais ricos, fumam menos e têm melhores sistemas de saúde, e nada se sabe sobre se os indivíduos que comem frutas são os que adoecem menos; a correlação pode até se inverter dentro de cada país. Clássico: Durkheim viu mais suicídio em regiões protestantes e concluiu sobre o indivíduo protestante, quando podiam ser os católicos minoritários que se matavam.</p>
<p>Outros erros têm nomes próprios e não se confundem com ela. <strong>Viés de seleção</strong>: a forma de escolher os participantes distorce a associação (voluntários mais saudáveis, perdas diferenciais). <strong>Erro de aferição ou de informação</strong>: medir mal a exposição ou o desfecho (recordatório alimentar impreciso, diagnóstico desigual entre países).</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Quando ler um estudo, pergunte primeiro: qual é a unidade de análise? Se são países, cidades ou escolas, toda conclusão sobre "indivíduos que..." é suspeita de falácia ecológica, por mais forte que seja a correlação. A pergunta sobre pessoas exige um estudo com pessoas.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Estudo ecológico: unidade de análise é o grupo; bom para políticas, exposições coletivas e hipóteses.</li>
<li>Falácia ecológica: inferir sobre indivíduos a partir de associação entre grupos; atomística é o inverso.</li>
<li>Viés de seleção, erro de aferição e confusão são erros distintos, com mecanismos próprios.</li>
<li>Para saber o que acontece com pessoas, estude pessoas: transversal, caso-controle, coorte, ensaio.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um estudo mostra que municípios com mais cobertura de ESF têm menos internações evitáveis. Pode-se concluir que a família cadastrada na ESF interna menos? <details><summary>Resposta</summary>Não diretamente: a inferência do município para a família é falácia ecológica; a conclusão vale para o nível municipal.</details></li>
<li>O que é confusão residual? <details><summary>Resposta</summary>A confusão que persiste após o ajuste estatístico, porque os confundidores foram mal medidos ou não medidos.</details></li>
</ol>
`,

"unesp2025#87": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Calcular e interpretar o risco relativo numa coorte.</li>
<li>Ler um intervalo de confiança e relacioná-lo à significância estatística.</li>
<li>Distinguir significância estatística de relevância clínica e reconhecer o efeito do tamanho da amostra.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Risco relativo (RR)</dt>
<dd>Razão entre a incidência nos expostos e nos não expostos; 1 é ausência de associação, acima de 1 aumento, abaixo de 1 proteção.</dd>
<dt>Intervalo de confiança de 95%</dt>
<dd>Faixa de valores compatíveis com os dados; se repetíssemos o estudo muitas vezes, 95% dos intervalos conteriam o valor verdadeiro.</dd>
<dt>Valor nulo</dt>
<dd>O valor que significa "nenhum efeito": 1 para razões (RR, OR, HR) e 0 para diferenças (de médias, de riscos).</dd>
<dt>Poder estatístico</dt>
<dd>Probabilidade de detectar um efeito real; depende do tamanho da amostra e da frequência do desfecho.</dd>
</dl>
<h4>O essencial</h4>
<p>Na coorte, calcula-se a <strong>incidência</strong> em cada grupo e o <strong>risco relativo</strong>, razão entre elas. RR de 1,5 significa que o risco nos expostos foi 50% maior; RR de 0,6, que foi 40% menor. Mas a estimativa vem de uma amostra, e o <strong>intervalo de confiança de 95%</strong> expressa a sua precisão: o conjunto de valores do RR compatíveis com os dados. Um intervalo estreito (1,3 a 1,7) indica estimativa precisa; um largo (0,95 a 2,10), imprecisa. A largura depende sobretudo do <strong>tamanho da amostra</strong> e do número de eventos.</p>
<p>A regra de leitura é simples: se o intervalo <strong>inclui o valor nulo</strong> (1 para razões), o resultado <strong>não é estatisticamente significativo</strong> ao nível de 5%, o que equivale a p maior que 0,05; se o intervalo fica inteiro acima ou abaixo de 1, é significativo. No caso, RR de 1,5 com intervalo de 0,95 a 2,10: a estimativa pontual aponta aumento, mas os dados são compatíveis com uma leve redução (0,95) e com mais que o dobro de risco (2,10). Não se pode afastar o acaso, e a conclusão correta é "aumento não significativo", nunca "não há associação": ausência de significância não é prova de ausência de efeito.</p>
<p>O intervalo é mais informativo que o valor de p, porque mostra a magnitude e a precisão. <strong>Significância estatística</strong> não é <strong>relevância clínica</strong>: um RR de 1,05 pode ser significativo numa amostra de milhões e irrelevante; um RR de 2,0 pode ser não significativo numa amostra de 400 e muito relevante se confirmado. O estudo da questão tem poder baixo para o desfecho; um ensaio ou coorte maior estreitaria o intervalo. Para as medidas absolutas, usa-se a diferença de riscos e o número necessário para tratar ou para causar dano, cujo valor nulo é zero.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Três perguntas ao ler um resultado: qual é o valor nulo desta medida (1 ou 0)? O intervalo o inclui? Quão largo é o intervalo? Com isso você responde se o efeito é significativo, em que direção aponta e quanta confiança a amostra permite, sem precisar do valor de p.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>RR = incidência nos expostos / incidência nos não expostos; acima de 1 aumento, abaixo de 1 proteção.</li>
<li>IC 95% que inclui o 1: não significativo (p maior que 0,05); que exclui o 1: significativo.</li>
<li>RR 1,5 (0,95 a 2,10): aumento de risco não significativo, compatível com acaso; amostra pequena.</li>
<li>Significância estatística não é relevância clínica; ausência de significância não é ausência de efeito.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um estudo relata RR de 0,70 com IC 95% de 0,55 a 0,89. Como se interpreta? <details><summary>Resposta</summary>Redução de 30% no risco, estatisticamente significativa, pois o intervalo não inclui o 1.</details></li>
<li>Qual é o valor nulo de uma diferença de médias? <details><summary>Resposta</summary>Zero: o intervalo de confiança que inclui o zero indica resultado não significativo.</details></li>
</ol>
`,

"unesp2025#89": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Conhecer o Decreto 7.508/2011 e os conceitos que ele introduziu.</li>
<li>Identificar as portas de entrada do SUS e o papel ordenador da APS.</li>
<li>Entender regiões de saúde, mapa da saúde, RENASES e COAP.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Decreto 7.508/2011</dt>
<dd>Regulamenta a Lei 8.080: organização do SUS em regiões de saúde, planejamento, assistência e articulação interfederativa.</dd>
<dt>Portas de entrada</dt>
<dd>Atenção primária, urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto.</dd>
<dt>Região de saúde</dt>
<dd>Espaço geográfico contínuo de municípios limítrofes que compartilham a rede, com no mínimo APS, urgência, psicossocial, especializada e vigilância.</dd>
<dt>RENASES</dt>
<dd>Relação Nacional de Ações e Serviços de Saúde: tudo o que o SUS oferece à população.</dd>
</dl>
<h4>O essencial</h4>
<p>Vinte e um anos depois da Lei 8.080, o <strong>Decreto 7.508/2011</strong> deu forma operacional a conceitos que estavam dispersos em portarias. Ele define a <strong>região de saúde</strong> como o espaço de municípios vizinhos que organizam a rede em conjunto, com <strong>comissões intergestores regionais</strong> (CIR) ao lado da bipartite (CIB) e da tripartite (CIT); cria o <strong>mapa da saúde</strong>, descrição da oferta e das necessidades; institui a <strong>RENASES</strong> e consolida a <strong>RENAME</strong>; e prevê o <strong>Contrato Organizativo da Ação Pública da Saúde</strong> (COAP), acordo entre os entes sobre responsabilidades, metas e recursos, que na prática quase não foi assinado.</p>
<p>Sobre o acesso, o decreto é direto. O acesso universal, igualitário e <strong>ordenado</strong> começa pelas <strong>portas de entrada</strong>: atenção primária, atenção de urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto (como os de saúde do trabalhador ou de IST, conforme definição estadual); os demais serviços são referenciados. E diz que o acesso <strong>é ordenado pela Atenção Primária</strong>, que deve ser resolutiva, coordenar o cuidado e referenciar o usuário conforme a necessidade, respeitando os critérios de regulação e a gravidade. A ESF é, assim, o eixo da rede, não um nível "básico" em sentido menor.</p>
<p>Isso se materializa nas <strong>Redes de Atenção à Saúde</strong> (Portaria 4.279/2010): arranjos poliárquicos de serviços de diferentes densidades tecnológicas, integrados por sistemas de apoio (diagnóstico, farmacêutico), logísticos (regulação, prontuário, transporte) e de governança, com a APS no centro. As redes temáticas (Rede Cegonha, de Urgência e Emergência, de Atenção Psicossocial, de Cuidados à Pessoa com Deficiência, de doenças crônicas) seguem esse desenho. Centrais de regulação (como a CROSS em São Paulo) e departamentos regionais são instrumentos; a ordenação é da APS.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na prática, "ordenar o acesso" significa que o médico de família encaminha com critério clínico, prioriza pela gravidade, acompanha o paciente na fila e o recebe de volta com a contrarreferência. O paciente pode entrar pelo pronto-socorro ou pelo CAPS, mas quem coordena o percurso é a equipe de referência dele.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Decreto 7.508/2011: regiões de saúde, CIR, mapa da saúde, RENASES, RENAME, COAP.</li>
<li>Portas de entrada: APS, urgência e emergência, atenção psicossocial, serviços especiais de acesso aberto.</li>
<li>O acesso é ordenado pela Atenção Primária, que coordena e referencia.</li>
<li>Redes de Atenção à Saúde: poliárquicas, com a APS no centro e sistemas de apoio, logísticos e de governança.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são as portas de entrada do SUS segundo o Decreto 7.508? <details><summary>Resposta</summary>Atenção primária, atenção de urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto.</details></li>
<li>O que é a RENASES? <details><summary>Resposta</summary>A Relação Nacional de Ações e Serviços de Saúde, que compreende todas as ações e serviços que o SUS oferece ao usuário.</details></li>
</ol>
`,

"unesp2025#90": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enumerar os requisitos legais do acesso à assistência farmacêutica no SUS.</li>
<li>Descrever a RENAME, as relações complementares e os três componentes da assistência farmacêutica.</li>
<li>Relacionar registro na Anvisa, RENAME e PCDT.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>RENAME</dt>
<dd>Relação Nacional de Medicamentos Essenciais: seleção e padronização dos medicamentos do SUS, atualizada a cada dois anos.</dd>
<dt>REMUME e RESME</dt>
<dd>Relações municipais e estaduais que complementam a RENAME conforme o perfil epidemiológico local.</dd>
<dt>Componentes da assistência farmacêutica</dt>
<dd>Básico (APS), Estratégico (programas como tuberculose, HIV, hanseníase) e Especializado (alto custo, conforme PCDT).</dd>
<dt>Farmácia Popular</dt>
<dd>Programa de copagamento ou gratuidade em farmácias privadas credenciadas para medicamentos de hipertensão, diabetes, asma e outros.</dd>
</dl>
<h4>O essencial</h4>
<p>A assistência farmacêutica integra a integralidade do SUS (Lei 8.080, art. 6º). O Decreto 7.508/2011 (art. 28) fixa os <strong>requisitos</strong> de acesso: estar o usuário <strong>assistido por ações e serviços de saúde do SUS</strong>; ter o medicamento sido <strong>prescrito por profissional de saúde no exercício regular de suas funções no SUS</strong>; estar a prescrição <strong>em conformidade com a RENAME e os PCDT</strong> ou com a <strong>relação específica complementar</strong> estadual, distrital ou municipal; e ter a dispensação ocorrido em unidades indicadas pela direção do SUS.</p>
<p>A <strong>RENAME</strong> é a lista nacional, hoje com cerca de 900 itens, organizada pelos componentes. O <strong>Componente Básico</strong> cobre a APS e é financiado pelas três esferas, com dispensação nas farmácias das UBS; o <strong>Estratégico</strong> é financiado e adquirido pelo Ministério para programas (tuberculose, hanseníase, HIV, malária, vacinas); o <strong>Especializado</strong> dispensa medicamentos de alto custo nas farmácias estaduais, mediante Laudo de Medicamento Especializado (LME) e critérios do PCDT.</p>
<p>A Lei 8.080 (art. 19-T, incluída pela Lei 12.401/2011) <strong>veda</strong> em todas as esferas a dispensação, o pagamento ou o reembolso de medicamento <strong>sem registro na Anvisa</strong>, e de uso experimental ou não autorizado; portanto a RENAME só contém produtos registrados. A exceção são as importações autorizadas pela Anvisa para programas estratégicos.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Ao prescrever no SUS, use a denominação genérica, consulte a REMUME do município (o que a farmácia da UBS realmente tem) e, para alto custo, preencha o LME com CID, exames e critérios do PCDT. Para hipertensão, diabetes e asma, o Farmácia Popular dispensa gratuitamente com receita de qualquer serviço, público ou privado.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Requisitos (Decreto 7.508, art. 28): usuário do SUS, prescritor do SUS, prescrição conforme RENAME e PCDT ou relações complementares, dispensação no SUS.</li>
<li>RENAME nacional; REMUME e RESME complementam, nunca restringem.</li>
<li>Componentes Básico, Estratégico e Especializado; alto custo com LME e PCDT.</li>
<li>Sem registro na Anvisa, nenhuma dispensação no SUS (Lei 8.080, art. 19-T).</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quais são os três componentes da assistência farmacêutica no SUS? <details><summary>Resposta</summary>Básico (APS), Estratégico (programas nacionais) e Especializado (alto custo conforme PCDT).</details></li>
<li>O município pode criar uma lista própria de medicamentos? <details><summary>Resposta</summary>Sim, a REMUME, que complementa a RENAME conforme o perfil local, sem restringir o que a RENAME garante.</details></li>
</ol>
`,

"unesp2025#91": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir Vigilância em Saúde segundo a PNVS e situar suas quatro vigilâncias.</li>
<li>Distinguir vigilância epidemiológica, sanitária, ambiental e em saúde do trabalhador.</li>
<li>Relacionar a vigilância à APS e à notificação compulsória.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PNVS</dt>
<dd>Política Nacional de Vigilância em Saúde (Resolução CNS 588/2018), que define a vigilância como função essencial do SUS, universal e integrada à atenção.</dd>
<dt>Vigilância epidemiológica</dt>
<dd>Conhecer, detectar e prevenir mudanças nos fatores determinantes da saúde, recomendando e adotando medidas de controle (Lei 8.080, art. 6º).</dd>
<dt>Vigilância sanitária</dt>
<dd>Eliminar, diminuir ou prevenir riscos de produtos, serviços e ambientes (Anvisa e visas estaduais e municipais).</dd>
<dt>Vigilância em saúde ambiental</dt>
<dd>Fatores ambientais que interferem na saúde: água, ar, solo, desastres, vetores, contaminantes.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>Vigilância em Saúde</strong> é o conceito integrador que a PNVS (2018) define como "processo contínuo e sistemático de coleta, consolidação, análise de dados e disseminação de informações sobre eventos relacionados à saúde, visando o planejamento e a implementação de medidas de saúde pública, incluindo a regulação, intervenção e atuação em condicionantes e determinantes da saúde, para a proteção e promoção da saúde da população, prevenção e controle de riscos, agravos e doenças".</p>
<p>Ela abrange quatro vigilâncias com histórias distintas. A <strong>epidemiológica</strong>, nascida das campanhas contra doenças transmissíveis, trabalha com notificação, investigação de casos e surtos, imunização e, hoje, também doenças crônicas e violências. A <strong>sanitária</strong>, a mais antiga, controla alimentos, medicamentos, cosméticos, saneantes, serviços de saúde e portos e aeroportos, pela Anvisa e pelas visas locais. A <strong>ambiental</strong> monitora água para consumo (Vigiagua), ar, solo, contaminantes e desastres.</p>
<p>Instrumentos comuns: a <strong>Lista Nacional de Notificação Compulsória</strong> (Portaria 264/2020), com agravos de notificação imediata (24 horas) e semanal, e o SINAN; os sistemas de mortalidade (SIM) e nascimentos (SINASC); a investigação de surtos; a análise de situação de saúde; e a resposta a emergências pelo CIEVS. Integralidade e universalidade são princípios do SUS, não processos de vigilância; e a vigilância epidemiológica é uma parte, não o todo: a definição que fala em "regulação" e em "condicionantes e determinantes" é a da Vigilância em Saúde.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Toda unidade de saúde é unidade notificadora. O médico que atende um caso suspeito de dengue, sífilis em gestante, acidente de trabalho grave ou violência preenche a ficha do SINAN; para os agravos imediatos (sarampo, meningite, febre amarela, epizootia, surto), a notificação é por telefone em 24 horas, antes mesmo da confirmação.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Vigilância em Saúde (PNVS 2018): informação mais ação, incluindo regulação e atuação sobre determinantes.</li>
<li>Quatro vigilâncias: epidemiológica, sanitária, ambiental e em saúde do trabalhador, integradas à APS.</li>
<li>Instrumentos: lista de notificação compulsória, SINAN, SIM, SINASC, investigação de surtos, CIEVS.</li>
<li>Vigilância epidemiológica é parte; integralidade e universalidade são princípios, não vigilância.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que resolução define a Política Nacional de Vigilância em Saúde? <details><summary>Resposta</summary>A Resolução CNS 588/2018.</details></li>
<li>Qual vigilância controla medicamentos, alimentos e serviços de saúde? <details><summary>Resposta</summary>A vigilância sanitária, pela Anvisa e pelas vigilâncias estaduais e municipais.</details></li>
</ol>
`,

"unesp2025#92": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Preencher a parte I e a parte II da Declaração de Óbito com a lógica causal.</li>
<li>Identificar a causa básica e explicar por que ela importa para a estatística.</li>
<li>Saber quem preenche a DO em morte natural, violenta e sem assistência.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Causa básica</dt>
<dd>Doença ou lesão que iniciou a cadeia de eventos que levou à morte, ou a circunstância do acidente ou violência; vai na última linha da parte I.</dd>
<dt>Causa terminal (imediata)</dt>
<dd>O evento final que produziu a morte; vai na linha a da parte I.</dd>
<dt>Parte II</dt>
<dd>Condições significativas que contribuíram para a morte mas não pertencem à cadeia causal da parte I.</dd>
<dt>IML e SVO</dt>
<dd>Instituto Médico Legal, para mortes violentas ou suspeitas; Serviço de Verificação de Óbito, para mortes naturais sem causa definida.</dd>
</dl>
<h4>O essencial</h4>
<p>A Declaração de Óbito é documento legal (permite o sepultamento), epidemiológico (alimenta o SIM) e de direitos (pensões, seguros). O bloco de causas segue o modelo da OMS. A <strong>parte I</strong> tem quatro linhas, lidas de cima para baixo com a expressão "devido a": na linha <strong>a</strong>, a <strong>causa terminal</strong>; nas linhas b e c, as causas intermediárias; na última linha preenchida, a <strong>causa básica</strong>.</p>
<p>A <strong>parte II</strong> recebe as condições que <strong>contribuíram</strong> mas não estão na cadeia: diabetes num óbito por infarto cuja cadeia é choque cardiogênico devido a infarto devido a aterosclerose; anemia falciforme num óbito por trauma. Colocar a condição contribuinte na parte I desloca a causa básica e distorce a estatística: a morte do caso seria contada como doença hematológica, e a <strong>causa externa</strong> (queda de altura em trabalho) desapareceria do SIM e da vigilância de acidentes de trabalho.</p>
<p>Quem preenche depende do tipo de morte. <strong>Morte natural com assistência</strong>: o médico que acompanhava, ou o do serviço, ou o substituto; sem causa definida, o SVO. <strong>Morte violenta ou suspeita</strong> (acidente, suicídio, homicídio, queda, intoxicação), inclusive quando o paciente morre no hospital dias depois do trauma: o corpo vai ao <strong>IML</strong>, que preenche a DO; o médico assistente não a emite. <strong>Morte sem assistência</strong> em local sem SVO: qualquer médico do serviço público ou, na sua falta, duas testemunhas em cartório.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Teste rápido antes de assinar: leia a parte I de baixo para cima como uma história ("ela caiu do prédio, por isso traumatizou o abdome, por isso lacerou o fígado, por isso chocou e morreu"). Se a história faz sentido e a última linha é o que começou tudo, está certo. Se a última linha é uma doença que não causou o evento seguinte, ela pertence à parte II.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Parte I: linha a é a causa terminal; última linha é a causa básica; cada linha "devido a" a de baixo.</li>
<li>Parte II: condições contribuintes fora da cadeia (diabetes, anemia falciforme).</li>
<li>A causa básica é o que entra na estatística; trocar a ordem apaga a causa externa.</li>
<li>Morte violenta vai ao IML, mesmo se ocorrer no hospital dias depois; sem causa definida, SVO.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Paciente com diabetes morre de choque cardiogênico após infarto por aterosclerose coronariana. Onde fica o diabetes? <details><summary>Resposta</summary>Na parte II, como condição contribuinte; a parte I é choque cardiogênico, devido a infarto, devido a aterosclerose coronariana.</details></li>
<li>Vítima de atropelamento morre no hospital após uma semana de internação. Quem emite a DO? <details><summary>Resposta</summary>O IML, pois a morte é de causa externa, ainda que tardia e em ambiente hospitalar.</details></li>
</ol>
`,

"unesp2025#95": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir óbito materno e a razão de mortalidade materna.</li>
<li>Explicar o denominador e a diferença entre razão e coeficiente.</li>
<li>Conhecer a situação brasileira, as causas e a vigilância do óbito materno.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Óbito materno</dt>
<dd>Morte de mulher durante a gravidez ou até 42 dias após o seu término, por causa relacionada ou agravada pela gestação ou por seu manejo, excluídas as acidentais ou incidentais.</dd>
<dt>Óbito materno tardio</dt>
<dd>Morte por causa obstétrica entre 43 dias e um ano após o término da gestação; não entra na razão.</dd>
<dt>Razão de mortalidade materna</dt>
<dd>Óbitos maternos por 100 mil nascidos vivos no mesmo período e lugar.</dd>
<dt>Causas obstétricas diretas e indiretas</dt>
<dd>Diretas: complicações da própria gestação (hipertensão, hemorragia, infecção); indiretas: doenças preexistentes agravadas (cardiopatia, HIV).</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>razão de mortalidade materna</strong> é o indicador mais sensível da qualidade da atenção à saúde da mulher. O numerador são os <strong>óbitos maternos</strong>, definidos pela OMS pelo tempo (gravidez até 42 dias do término, qualquer duração ou localização) e pela causa (obstétrica direta ou indireta), excluídas mortes acidentais ou incidentais, como atropelamento ou homicídio. O denominador ideal seria o número de mulheres grávidas no período, mas ele é desconhecido, porque abortos e perdas precoces não se registram; usam-se os <strong>nascidos vivos</strong> como aproximação.</p>
<p>No Brasil, a razão caiu de cerca de 140 em 1990 para cerca de 55 a 60 por 100 mil em 2019, subiu para mais de 100 em 2021 com a covid-19 e voltou a cerca de 50 a 60 depois; a meta dos Objetivos de Desenvolvimento Sustentável é menos de 30 até 2030, e a OMS considera aceitável abaixo de 20. As principais causas diretas são <strong>hipertensão</strong> (pré-eclâmpsia e eclâmpsia), <strong>hemorragia</strong> e <strong>infecção</strong> puerperal, seguidas do aborto inseguro; as indiretas crescem com a idade e as comorbidades.</p>
<p>A <strong>vigilância do óbito materno</strong> é obrigatória: todo óbito de mulher de 10 a 49 anos é investigado (óbito de mulher em idade fértil), para identificar os maternos sub-registrados e os evitáveis, com <strong>comitês de mortalidade materna</strong> que analisam cada caso e propõem correções. O <strong>fator de correção</strong> da sub-notificação, antes necessário, deixou de ser aplicado quando a investigação cobriu o país.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Denominadores para não confundir na prova: mortalidade materna, nascidos vivos; mortalidade infantil, nascidos vivos; taxa de fecundidade, mulheres de 15 a 49 anos; mortalidade geral, população total; mortalidade proporcional, total de óbitos. Óbito materno de mulher que morre de acidente de carro grávida não entra na razão.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Óbito materno: gravidez até 42 dias, causa obstétrica direta ou indireta, excluídas acidentais.</li>
<li>Razão de mortalidade materna: óbitos maternos por 100 mil nascidos vivos; razão porque o numerador não está no denominador.</li>
<li>Brasil cerca de 50 a 60; meta ODS abaixo de 30; causas: hipertensão, hemorragia, infecção, aborto inseguro.</li>
<li>Todo óbito de mulher de 10 a 49 anos é investigado; comitês de mortalidade materna analisam a evitabilidade.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a mortalidade materna é uma razão e não um coeficiente? <details><summary>Resposta</summary>Porque o numerador (óbitos maternos) não está inteiramente contido no denominador (nascidos vivos), que é só uma aproximação da população exposta.</details></li>
<li>Uma gestante de 30 semanas morre em acidente de trânsito. É óbito materno? <details><summary>Resposta</summary>Não. Causas acidentais ou incidentais são excluídas da definição de óbito materno.</details></li>
</ol>
`,

"unesp2025#98": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Definir ambiente alimentar, deserto e pântano alimentar.</li>
<li>Relacionar o ambiente alimentar aos determinantes sociais e à obesidade.</li>
<li>Propor ações intersetoriais a partir do diagnóstico do território.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Ambiente alimentar</dt>
<dd>Conjunto de condições físicas, econômicas e sociais que determinam o acesso e a escolha dos alimentos num território.</dd>
<dt>Deserto alimentar</dt>
<dd>Área com baixa disponibilidade de alimentos in natura ou minimamente processados, por distância ou preço.</dd>
<dt>Pântano alimentar</dt>
<dd>Área saturada de estabelecimentos que vendem ultraprocessados, lanches e bebidas açucaradas.</dd>
<dt>Classificação NOVA</dt>
<dd>Divide os alimentos em in natura ou minimamente processados, ingredientes culinários, processados e ultraprocessados; base do Guia Alimentar brasileiro.</dd>
</dl>
<h4>O essencial</h4>
<p>O que as pessoas comem depende menos de "força de vontade" e mais do <strong>ambiente alimentar</strong>: o que está disponível perto de casa, a que preço, com que publicidade e em que condições de tempo e renda. O Guia Alimentar para a População Brasileira (2014), baseado na classificação <strong>NOVA</strong>, recomenda alimentos in natura e minimamente processados como base da alimentação, e evita os ultraprocessados; mas essa recomendação só é realizável onde há feira, sacolão, mercado de bairro e tempo e dinheiro para cozinhar.</p>
<p>A Câmara Interministerial de Segurança Alimentar e Nutricional (<strong>CAISAN</strong>) mapeou em 2018 os <strong>desertos alimentares</strong> no Brasil, definidos pela baixa densidade de estabelecimentos que vendem alimentos saudáveis por habitante, e mostrou que eles se concentram em periferias e áreas rurais pobres, onde o alimento fresco é distante ou caro. O conceito de <strong>pântano alimentar</strong> descreve a situação inversa e frequentemente sobreposta: a abundância de lanchonetes, redes de fast food e comércio de ultraprocessados, com publicidade intensa, especialmente perto de escolas.</p>
<p>A APS tem papel duplo. No indivíduo: avaliação do consumo pelos marcadores do <strong>SISVAN</strong>, orientação prática adaptada ao que existe no bairro (feiras, hortas, compra coletiva), e cuidado da obesidade conforme a linha de cuidado.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Na consulta, troque "coma mais verduras" por perguntas: onde você compra comida? Quanto custa? Tem feira perto? Quem cozinha e quando? As respostas mostram se o problema é informação, acesso ou tempo, e orientam uma recomendação possível, como a feira de produtor do bairro vizinho ou o programa de alimentação escolar para os filhos.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Ambiente alimentar determina a alimentação mais que a vontade individual.</li>
<li>Deserto alimentar: falta de alimento in natura acessível; pântano: excesso de ultraprocessados (CAISAN, 2018).</li>
<li>Guia Alimentar e classificação NOVA: base in natura, evitar ultraprocessados.</li>
<li>APS: SISVAN e orientação adaptada ao bairro; no território, ação intersetorial (feiras, hortas, PAA, escolas).</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Qual é a diferença entre deserto e pântano alimentar? <details><summary>Resposta</summary>Deserto é a escassez de alimentos in natura acessíveis; pântano é a saturação de ultraprocessados e fast food, com forte publicidade.</details></li>
<li>Que programa compra da agricultura familiar para abastecer escolas e equipamentos públicos? <details><summary>Resposta</summary>O Programa de Aquisição de Alimentos (PAA) e o Programa Nacional de Alimentação Escolar, que destina ao menos 30% às compras da agricultura familiar.</details></li>
</ol>
`,

/* --- Volume 2 · Preventiva · FAMEMA 2026 (prev91–prev100) --------------------------------- */
"famema2026#65": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer ações de promoção da saúde que acontecem fora da unidade.</li>
<li>Descrever a intersetorialidade e a ação comunitária como eixos da PNPS.</li>
<li>Organizar a participação da equipe em atividades no território.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Intersetorialidade</dt>
<dd>Articulação da saúde com educação, assistência social, trabalho, cultura e organizações da comunidade para agir sobre determinantes.</dd>
<dt>Ação comunitária</dt>
<dd>Campo da Carta de Ottawa: fortalecer a capacidade da comunidade de decidir e agir sobre a sua saúde.</dd>
<dt>Determinantes sociais</dt>
<dd>Condições de vida e trabalho (renda, trabalho, alimentação, moradia, direitos) que produzem saúde e doença.</dd>
<dt>Atividade extramuros</dt>
<dd>Ação da equipe fora da unidade: escolas, associações, feiras, igrejas, domicílios, com planejamento e registro.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>Política Nacional de Promoção da Saúde</strong> (2006, revista em 2014) define promoção como estratégia de produção de saúde articulada às demais políticas, que age sobre os <strong>determinantes</strong> e amplia a autonomia dos sujeitos e das coletividades.</p>
<p>A PNAB manda que a equipe atue <strong>no território</strong>, não só no prédio: visitas domiciliares, atividades em escolas (Programa Saúde na Escola), grupos na comunidade, participação em conselhos locais e em ações intersetoriais. A divisão entre "atividade do setor saúde" e "atividade da comunidade" é o que a promoção da saúde recusa: a saúde se produz onde a vida acontece, e uma associação de mulheres que gera renda, informa sobre direitos e vende comida saudável está produzindo saúde.</p>
<p>Participar exige <strong>organização</strong>, não recusa: escala para o sábado com compensação, planejamento do que levar, registro da atividade coletiva no e-SUS (ficha de atividade coletiva), avaliação com a associação. Convites da comunidade são oportunidades de vínculo, de conhecimento do território e de alcance de quem não vai à unidade, como trabalhadoras domésticas e do comércio, que não conseguem consultar em horário comercial.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Um bom estande de saúde numa feira comunitária cabe numa mesa: pressão arterial e glicemia capilar com orientação, teste rápido de HIV e sífilis, vacinas de rotina e campanha, caderneta da criança, informação sobre direitos (acompanhante, gratuidade, Farmácia Popular) e um caderno para anotar quem precisa de consulta e marcar na segunda-feira. O que não cabe é "não é problema nosso".</p>
</div>
<h4>Resumo</h4>
<ul>
<li>PNPS: agir sobre determinantes e ampliar a autonomia, com equidade, participação e intersetorialidade.</li>
<li>Feira comunitária com renda, direitos e comida saudável é promoção da saúde; a UBS participa.</li>
<li>A PNAB exige ação no território: escolas, associações, domicílios, conselhos.</li>
<li>Participar é organizar escala, planejar, registrar e avaliar, não recusar por horário ou por "não ser saúde".</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Cite três temas prioritários da Política Nacional de Promoção da Saúde. <details><summary>Resposta</summary>Alimentação adequada e saudável, práticas corporais e atividade física, enfrentamento do tabaco e do álcool, cultura da paz, mobilidade segura, desenvolvimento sustentável.</details></li>
<li>Como se registra uma atividade de saúde realizada numa feira comunitária? <details><summary>Resposta</summary>Na ficha de atividade coletiva do e-SUS, com o tipo de ação, o público e os participantes.</details></li>
</ol>
`,

"famema2026#67": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Diferenciar urgência, emergência e pseudocrise hipertensiva.</li>
<li>Listar as emergências hipertensivas e a conduta inicial em cada cenário.</li>
<li>Diagnosticar hipertensão do avental branco e mascarada com MAPA e MRPA.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Urgência hipertensiva</dt>
<dd>Pressão muito elevada (em geral acima de 180/120) sem lesão aguda de órgão-alvo; reduz-se em 24 a 48 horas, por via oral.</dd>
<dt>Emergência hipertensiva</dt>
<dd>Pressão elevada com lesão aguda em curso (encefalopatia, AVE, infarto, edema agudo, dissecção, eclâmpsia); droga venosa e UTI.</dd>
<dt>Pseudocrise</dt>
<dd>Pressão alta por dor, ansiedade ou abandono da medicação, sem lesão de órgão-alvo; trata-se a causa, não a pressão.</dd>
<dt>Hipertensão do avental branco</dt>
<dd>Pressão alta no consultório e normal fora dele (MAPA ou MRPA); a mascarada é o inverso.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>crise hipertensiva</strong> é a elevação acentuada da pressão, em geral acima de 180/120 mmHg, e o que define a conduta não é o número, mas a presença de <strong>lesão aguda de órgão-alvo</strong>. Na <strong>urgência</strong> não há lesão: cefaleia leve, tontura ou nada; reduz-se a pressão gradualmente em 24 a 48 horas com medicação oral (captopril, clonidina, ou retomada do esquema), observação e reavaliação ambulatorial.</p>
<p>As <strong>emergências</strong> são a <strong>encefalopatia hipertensiva</strong>, o <strong>AVE</strong> isquêmico e hemorrágico (com metas de pressão próprias e mais permissivas), a <strong>síndrome coronariana aguda</strong> e o <strong>edema agudo de pulmão</strong>, a <strong>dissecção de aorta</strong> (meta agressiva: sistólica abaixo de 120 e frequência abaixo de 60 em minutos, betabloqueador antes do vasodilatador), a <strong>eclâmpsia</strong> e a pré-eclâmpsia grave, a crise do feocromocitoma e a intoxicação por cocaína ou anfetaminas.</p>
<p>O diagnóstico da hipertensão fora da crise também exige medidas repetidas, mas <strong>fora do consultório</strong>. A <strong>hipertensão do avental branco</strong> (consultório alto, casa normal) afeta até 20% dos hipertensos aparentes e não é descartada por medidas repetidas no consultório: só a <strong>MAPA</strong> de 24 horas ou a <strong>MRPA</strong> (medidas residenciais em 5 dias, três de manhã e três à noite) a identificam. A <strong>hipertensão mascarada</strong> é o inverso e tem risco cardiovascular semelhante ao da hipertensão sustentada. As diretrizes brasileiras de 2020 recomendam MAPA ou MRPA para confirmar o diagnóstico sempre que possível.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Diante de 190/110 na UBS: pergunte sobre dor, ansiedade, sono, remédio esquecido; examine fundo de olho, sinais neurológicos, dor torácica, dispneia; se nada disso, deixe em repouso 30 minutos e remeça. Sem lesão, é urgência ou pseudocrise: trate a causa, ajuste o esquema oral e reavalie em dias. Nunca nifedipina sublingual.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Crise hipertensiva: o que decide é a lesão aguda de órgão-alvo, não o número.</li>
<li>Urgência: oral, 24 a 48 horas; emergência: venoso, UTI, redução controlada; pseudocrise: trate a causa.</li>
<li>Emergências: encefalopatia, AVE, infarto, edema agudo, dissecção, eclâmpsia, feocromocitoma, cocaína; podem ocorrer sem HAS prévia.</li>
<li>Avental branco e mascarada só se diagnosticam com MAPA ou MRPA, não com medidas repetidas no consultório.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que exame diferencia hipertensão do avental branco de hipertensão sustentada? <details><summary>Resposta</summary>MAPA de 24 horas ou MRPA, que medem a pressão fora do consultório.</details></li>
<li>Por que a nifedipina sublingual é proscrita na crise hipertensiva? <details><summary>Resposta</summary>Porque produz queda abrupta e imprevisível da pressão, com risco de isquemia cerebral, coronariana e renal.</details></li>
</ol>
`,

"famema2026#68": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer a dermatite de contato alérgica por esmalte e sua localização palpebral.</li>
<li>Saber quais dermatoses são de notificação compulsória.</li>
<li>Distinguir dermatose ocupacional de dermatose por hábito pessoal.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Dermatite de contato alérgica</dt>
<dd>Hipersensibilidade tardia (tipo IV) a um alérgeno em contato com a pele; eczema pruriginoso 24 a 72 horas após a exposição.</dd>
<dt>Dermatite de contato irritativa</dt>
<dd>Dano direto da pele por substância irritante (detergente, solvente), sem sensibilização; a mais comum no trabalho.</dd>
<dt>Dermatose ocupacional</dt>
<dd>Alteração da pele causada ou agravada pelo trabalho; de notificação compulsória no SINAN.</dd>
<dt>Teste de contato (patch test)</dt>
<dd>Aplicação de alérgenos padronizados no dorso por 48 horas, com leitura em 48 e 96 horas, para identificar o agente.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>dermatite de contato</strong> é a dermatose mais comum na APS e no trabalho. A forma <strong>irritativa</strong> resulta de agressão direta (água e detergentes nas mãos de quem limpa, cimento, solventes) e aparece em quem se expõe o bastante; a <strong>alérgica</strong> exige sensibilização prévia e reaparece a cada contato com o alérgeno, mesmo em pequena quantidade. Os alérgenos mais frequentes são níquel (bijuterias, fivelas), fragrâncias, conservantes de cosméticos, borracha, tinturas de cabelo e a <strong>resina tosilamida-formaldeído</strong> do esmalte.</p>
<p>O diagnóstico é clínico e pela história de exposição, e o <strong>teste de contato</strong> confirma o agente quando há dúvida ou quando a exposição é ocupacional e a identificação define o afastamento. O tratamento é evitar o alérgeno (esmaltes "hipoalergênicos" sem a resina), corticoide tópico de potência baixa nas pálpebras por poucos dias, e emolientes; nas formas extensas, corticoide oral curto. Nas dermatoses das mãos de trabalhadores, a proteção (luvas adequadas, cremes de barreira) e a mudança do processo de trabalho são o tratamento de fundo.</p>
<p>Quanto à vigilância, a Lista Nacional de Notificação Compulsória (Portaria 264/2020) inclui, entre os agravos relacionados ao trabalho, as <strong>dermatoses ocupacionais</strong>, ao lado de acidente de trabalho grave e com material biológico, câncer, LER/DORT, perda auditiva, pneumoconioses, transtornos mentais e intoxicações exógenas relacionadas ao trabalho.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Eczema de pálpebras numa mulher sem cosméticos faciais: pergunte por esmalte, bijuteria, colírio e produtos para cabelo. Oriente suspender o esmalte por quatro semanas antes de qualquer outro passo; a melhora confirma. Se ela for manicure ou cabeleireira, a exposição é ocupacional e muda a notificação e a conduta no trabalho.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Dermatite de contato alérgica: sensibilização prévia, eczema pruriginoso 24 a 72 horas após o contato; esmalte dá lesão ectópica nas pálpebras.</li>
<li>Irritativa é a mais comum no trabalho; o teste de contato identifica o alérgeno na alérgica.</li>
<li>Só as dermatoses ocupacionais são de notificação compulsória (Portaria 264/2020).</li>
<li>A pergunta é "a exposição vem do trabalho?": esmalte por hábito, não; esmalte na manicure, sim.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que a dermatite por esmalte aparece nas pálpebras e não nos dedos? <details><summary>Resposta</summary>Porque a pele das pálpebras é fina e reativa, e as mãos transportam o alérgeno até ela; é a dermatite de contato ectópica.</details></li>
<li>Uma manicure desenvolve eczema nas mãos pelo contato com produtos do trabalho. Notifica-se? <details><summary>Resposta</summary>Sim, como dermatose ocupacional no SINAN, com registro do nexo e comunicação à vigilância em saúde do trabalhador.</details></li>
</ol>
`,

"famema2026#69": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Explicar a toxicocinética do metanol e por que os sintomas são tardios.</li>
<li>Descrever o tratamento: antídotos, bicarbonato, ácido folínico e hemodiálise.</li>
<li>Reconhecer a resposta de saúde pública ao surto de 2025.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Metanol</dt>
<dd>Álcool metílico, usado em solventes e combustíveis; adulterante de bebidas por ser barato e incolor.</dd>
<dt>Ácido fórmico</dt>
<dd>Metabólito tóxico do metanol, via álcool-desidrogenase e formaldeído; causa acidose metabólica e lesão do nervo óptico.</dd>
<dt>Fomepizol</dt>
<dd>Inibidor da álcool-desidrogenase; antídoto de escolha, importado em 2025 pelo Ministério da Saúde.</dd>
<dt>Gap osmolar e ânion gap</dt>
<dd>Pistas laboratoriais: o gap osmolar sobe cedo (metanol circulante) e o ânion gap sobe tarde (ácido fórmico).</dd>
</dl>
<h4>O essencial</h4>
<p>O <strong>metanol</strong> em si causa pouco mais que embriaguez; o dano vem dos metabólitos. A <strong>álcool-desidrogenase</strong> o converte em formaldeído e este em <strong>ácido fórmico</strong>, que inibe a citocromo-oxidase, produz <strong>acidose metabólica</strong> grave com ânion gap elevado e lesa o nervo óptico e os gânglios da base.</p>
<p>O tratamento tem quatro pilares. <strong>Bloquear a álcool-desidrogenase</strong>: <strong>fomepizol</strong> (15 mg/kg de ataque e depois 10 mg/kg a cada 12 horas) ou, na sua falta, <strong>etanol</strong> por via oral ou venosa, mantendo etanolemia de 100 a 150 mg/dL, com monitorização; ambos impedem a formação de ácido fórmico enquanto o metanol é eliminado ou dialisado. <strong>Corrigir a acidose</strong> com bicarbonato. <strong>Acelerar a eliminação do fórmico</strong> com ácido folínico (leucovorina) ou ácido fólico. <strong>Hemodiálise</strong> nos casos com acidose grave, alteração visual, metanol acima de 50 mg/dL ou falência renal, pois remove metanol e fórmico.</p>
<p>No <strong>surto de 2025</strong>, com dezenas de casos e mortes concentrados em São Paulo por bebidas destiladas adulteradas, o Ministério da Saúde emitiu nota técnica de manejo, distribuiu fomepizol importado aos centros de referência e a <strong>Anvisa autorizou o uso emergencial de etanol farmacêutico injetável</strong>, o que a letra correta da prova registra. A vigilância sanitária apreendeu lotes e interditou fabricantes clandestinos, sem suspensão geral de bebidas; a intoxicação exógena é de notificação compulsória, e os centros de informação toxicológica (CIATox, 0800 722 6001) orientam o manejo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Pessoa que bebeu destilado de origem duvidosa e chega com náusea, taquipneia e visão turva horas depois: gasometria (acidose com ânion gap alto), osmolaridade, lactato, função renal; iniciar antídoto antes do nível de metanol, que demora; acionar nefrologia para diálise e o CIATox. Etanol oral (destilado comercial) é opção de ponte na ausência de fomepizol e etanol injetável.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Metanol vira formaldeído e ácido fórmico pela álcool-desidrogenase; latência de 12 a 24 horas, acidose e lesão do nervo óptico.</li>
<li>Tratamento: fomepizol ou etanol (bloqueio da enzima), bicarbonato, ácido folínico, hemodiálise nos graves.</li>
<li>Surto de 2025: fomepizol importado, etanol injetável autorizado pela Anvisa, lotes apreendidos; notificação compulsória.</li>
<li>Diagnóstico difícil: sintomas tardios e inespecíficos; gap osmolar e ânion gap ajudam.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que o etanol funciona como antídoto do metanol? <details><summary>Resposta</summary>Porque compete pela álcool-desidrogenase com afinidade maior, impedindo a conversão do metanol em formaldeído e ácido fórmico.</details></li>
<li>Quais são as indicações de hemodiálise na intoxicação por metanol? <details><summary>Resposta</summary>Acidose metabólica grave, alteração visual, metanol sérico acima de 50 mg/dL ou insuficiência renal.</details></li>
</ol>
`,

"famema2026#70": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Listar os procedimentos previstos para a Atenção Primária.</li>
<li>Indicar e executar com segurança a drenagem de abscesso, a exérese de lipoma e a remoção de cerúmen.</li>
<li>Reconhecer quando o procedimento deve ir ao serviço especializado.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Resolutividade</dt>
<dd>Capacidade da APS de resolver a maior parte dos problemas que recebe (cerca de 85%), sem encaminhar.</dd>
<dt>Pequena cirurgia</dt>
<dd>Procedimento ambulatorial sob anestesia local em sala de procedimentos: suturas, drenagens, exéreses de lesões superficiais, biópsias de pele, cantoplastia.</dd>
<dt>Abscesso cutâneo</dt>
<dd>Coleção purulenta na pele e no subcutâneo, em geral por <em>Staphylococcus aureus</em>; o tratamento é a drenagem.</dd>
<dt>Lipoma</dt>
<dd>Tumor benigno de tecido adiposo, móvel, indolor, de crescimento lento; retira-se por incômodo, crescimento ou dúvida diagnóstica.</dd>
</dl>
<h4>O essencial</h4>
<p>A PNAB lista entre as atribuições do médico da APS "realizar pequenos procedimentos cirúrgicos" e o Caderno de Atenção Primária nº 30 (Procedimentos) detalha o que se espera de uma UBS equipada: suturas, <strong>drenagem de abscessos</strong>, <strong>exérese de lipomas e cistos</strong> pequenos, retirada de nevos e lesões benignas, biópsias de pele, cantoplastia para unha encravada, retirada de corpo estranho, <strong>lavagem auricular</strong>, cauterização química, infiltrações, tamponamento nasal anterior, retirada de pontos e curativos complexos.</p>
<p>Cada procedimento tem a sua técnica e os seus limites. O <strong>abscesso</strong> flutuante se drena com incisão ampla, exploração e lavagem, sem suturar; antibiótico só se houver celulite extensa, imunossupressão, febre ou localização de risco, e em diabéticos acompanha-se a cicatrização de perto, mas o diabetes não contraindica drenar na UBS, ao contrário: atrasar favorece a extensão.</p>
<p>O que limita os procedimentos na APS não é a complexidade, mas a <strong>estrutura</strong> (sala, material estéril, iluminação, anestésico, kit de emergência) e o <strong>treinamento</strong>, que a formação em medicina de família inclui. O reflexo de encaminhar tudo tem custo: filas de meses para drenar um abscesso que piora em dias, usuários que desistem e voltam complicados.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Lista mínima da sala de procedimentos: lidocaína 2% com e sem vasoconstritor, bisturi, pinças, porta-agulha, fios, cureta e seringa de lavagem auricular, nitrato de prata, kit de drenagem, caixa de sutura, material para anafilaxia. Com isso a maioria dos "encaminhamentos para pequena cirurgia" se resolve no mesmo dia.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>A PNAB e o Caderno nº 30 preveem pequenos procedimentos na APS: suturas, drenagens, exéreses, lavagem auricular, cantoplastia.</li>
<li>Abscesso: drenar na UBS, inclusive em diabéticos, com acompanhamento; antibiótico só com critérios.</li>
<li>Lipoma pequeno e superficial se retira na UBS; grande, profundo, em local nobre ou suspeito vai ao especialista.</li>
<li>Resolutividade poupa filas; o que limita é estrutura e treinamento, não a complexidade.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Quando o abscesso drenado precisa de antibiótico? <details><summary>Resposta</summary>Com celulite extensa ao redor, febre ou sinais sistêmicos, imunossupressão, localização de risco ou falha da drenagem.</details></li>
<li>Que características de um lipoma indicam encaminhar em vez de retirar na UBS? <details><summary>Resposta</summary>Tamanho acima de 5 cm, localização profunda ou em face e mão, crescimento rápido, dor ou consistência endurecida.</details></li>
</ol>
`,

"famema2026#73": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever os efeitos diretos e indiretos das mudanças climáticas na saúde.</li>
<li>Identificar os grupos mais vulneráveis e a dimensão da desigualdade.</li>
<li>Conhecer as respostas do setor saúde: vigilância, adaptação e mitigação.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Mudança climática</dt>
<dd>Aquecimento global de origem humana, com ondas de calor, secas, chuvas extremas e mudança na distribuição de vetores.</dd>
<dt>Efeitos diretos</dt>
<dd>Calor extremo, frio, poluição, desastres: mortes cardiovasculares e respiratórias, trauma, afogamento.</dd>
<dt>Efeitos indiretos</dt>
<dd>Dengue, malária e leptospirose em novas áreas, insegurança alimentar, deslocamentos, saúde mental.</dd>
<dt>Justiça climática</dt>
<dd>Reconhecimento de que quem menos emite sofre mais, entre países e dentro deles.</dd>
</dl>
<h4>O essencial</h4>
<p>A OMS chama a mudança climática de maior ameaça à saúde do século. Os <strong>efeitos diretos</strong> vêm das <strong>ondas de calor</strong>, que aumentam as mortes cardiovasculares, renais e respiratórias, especialmente em idosos, cardiopatas e trabalhadores ao ar livre; da <strong>poluição atmosférica</strong>, agravada por incêndios e queimadas, que piora asma, DPOC, pneumonia e infarto; dos <strong>desastres</strong> (enchentes como as do Rio Grande do Sul em 2024, deslizamentos, secas), com trauma, afogamento, leptospirose, diarreia e perda de serviços de saúde.</p>
<p>Os <strong>efeitos indiretos</strong> são tão importantes: a expansão geográfica e sazonal da <strong>dengue</strong> e de outras arboviroses (o Brasil bateu recorde em 2024), a malária e as doenças de veiculação hídrica; a <strong>insegurança alimentar</strong> por quebra de safras e alta de preços; os deslocamentos de população; e o impacto na <strong>saúde mental</strong> (ansiedade, estresse pós-traumático após desastres, luto).</p>
<p>O setor saúde responde em duas frentes. <strong>Adaptação</strong>: vigilância de calor extremo com alertas e planos de contingência (hidratação, salas climatizadas, busca ativa de idosos), monitoramento da qualidade do ar, preparação para desastres, controle vetorial reforçado, mapeamento de vulnerabilidades no território. <strong>Mitigação</strong>: reduzir a pegada de carbono dos serviços (energia, resíduos, anestésicos) e defender políticas de transporte, energia e alimentação que protegem a saúde.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Em onda de calor, a equipe de APS tem uma lista: idosos que moram sozinhos, pessoas com insuficiência cardíaca e renal, gestantes, lactentes, usuários de diuréticos e psicotrópicos, trabalhadores ao ar livre. Ligar, orientar hidratação e sombra, ajustar diuréticos e checar quem não respondeu salvam vidas tanto quanto o pronto-socorro.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Diretos: calor, poluição e desastres, com mortes cardiovasculares e respiratórias; crianças e idosos são os mais vulneráveis.</li>
<li>Indiretos: arboviroses em expansão, insegurança alimentar, deslocamentos, saúde mental.</li>
<li>Desigual: quem é pobre sofre primeiro e mais (justiça climática); ninguém se beneficia.</li>
<li>Saúde responde com adaptação (vigilância, planos de calor, desastres, vetores) e mitigação.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Por que crianças são mais vulneráveis à poluição atmosférica? <details><summary>Resposta</summary>Vias aéreas mais estreitas, maior ventilação por quilo de peso, pulmões em desenvolvimento e mais tempo ao ar livre.</details></li>
<li>Cite dois efeitos indiretos da mudança climática sobre a saúde no Brasil. <details><summary>Resposta</summary>Expansão da dengue e de outras arboviroses, e insegurança alimentar por quebra de safras e alta de preços (também leptospirose após enchentes e impactos na saúde mental).</details></li>
</ol>
`,

"famema2026#74": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Enunciar a definição de Atenção Básica da PNAB 2017.</li>
<li>Reconhecer os princípios e as diretrizes da PNAB e suas palavras exatas.</li>
<li>Identificar as armadilhas de prova: porta de entrada única, residir no território, saberes validados.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PNAB 2017</dt>
<dd>Portaria 2.436/2017, que revisou a política de 2011: definição, princípios, diretrizes, tipos de equipe e financiamento.</dd>
<dt>Porta de entrada preferencial</dt>
<dd>A APS é o primeiro contato preferencial, mas não único: urgência, psicossocial e serviços especiais também são portas.</dd>
<dt>Equipe multiprofissional</dt>
<dd>Médico, enfermeiro, técnico ou auxiliar de enfermagem e agentes comunitários, com saúde bucal e eMulti como complemento.</dd>
<dt>Integração de saberes</dt>
<dd>Diretriz de valorizar as diversas práticas e saberes, inclusive populares e integrativos, na perspectiva da integralidade.</dd>
</dl>
<h4>O essencial</h4>
<p>A PNAB define a Atenção Básica como "o conjunto de ações de saúde individuais, familiares e coletivas que envolvem <strong>promoção, prevenção, proteção, diagnóstico, tratamento, reabilitação, redução de danos, cuidados paliativos e vigilância em saúde</strong>, desenvolvida por meio de práticas de cuidado integrado e gestão qualificada, realizada com <strong>equipe multiprofissional</strong> e dirigida à população em <strong>território definido</strong>, sobre as quais as equipes assumem responsabilidade sanitária".</p>
<p>Os <strong>princípios</strong> da PNAB são universalidade, equidade e integralidade. As <strong>diretrizes</strong>: regionalização e hierarquização; territorialização; população adscrita; cuidado centrado na pessoa; resolutividade; longitudinalidade do cuidado; coordenação do cuidado; ordenação da rede; e participação da comunidade.</p>
<p>As provas exploram palavras únicas. "Porta de entrada <strong>única</strong>" está errado; "preferencial" está certo. "Profissionais devem <strong>residir</strong> no território" está errado para a equipe; para o ACS é desejável, não obrigatório. "Saberes <strong>desde que validados cientificamente</strong>" contradiz a diretriz. "Acesso <strong>universal e contínuo</strong> a serviços resolutivos" é texto da PNAB, mas a frase inteira só está certa se não trouxer a palavra "única". Ler a frase até o fim é a habilidade testada.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Numa UBS, a definição se traduz em agenda: acolhimento à demanda espontânea todos os dias (acesso), consultas programadas de crônicos (longitudinalidade), visitas e grupos (território e promoção), pequenos procedimentos (resolutividade), encaminhamentos regulados com contrarreferência (coordenação) e reunião de equipe com a comunidade (participação).</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Definição da PNAB: promoção, prevenção, proteção, diagnóstico, tratamento, reabilitação, redução de danos, paliativos e vigilância, por equipe multiprofissional em território definido.</li>
<li>Princípios: universalidade, equidade, integralidade; diretrizes: territorialização, adscrição, longitudinalidade, coordenação, ordenação, resolutividade, participação.</li>
<li>Porta de entrada preferencial, não única; residir no território é recomendação só para o ACS.</li>
<li>Valorizar saberes diversos sem condicionar a validação científica.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>A APS é a porta de entrada única do SUS? <details><summary>Resposta</summary>Não. É a porta de entrada preferencial; urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto também são portas.</details></li>
<li>Quais são os princípios da PNAB 2017? <details><summary>Resposta</summary>Universalidade, equidade e integralidade.</details></li>
</ol>
`,

"famema2026#76": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Descrever a Política Nacional de Saúde do Trabalhador e da Trabalhadora e a RENAST.</li>
<li>Reconhecer o papel da APS na vigilância em saúde do trabalhador no território.</li>
<li>Aplicar as regras de notificação do acidente de trabalho no SINAN.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>PNSTT</dt>
<dd>Política Nacional de Saúde do Trabalhador e da Trabalhadora (Portaria 1.823/2012): todos os trabalhadores, formais e informais, como sujeitos da atenção e da vigilância.</dd>
<dt>RENAST e CEREST</dt>
<dd>Rede Nacional de Atenção Integral à Saúde do Trabalhador, com os Centros de Referência em Saúde do Trabalhador como apoio técnico.</dd>
<dt>VISAT</dt>
<dd>Vigilância em Saúde do Trabalhador: intervenção sobre os processos e ambientes de trabalho que produzem adoecimento.</dd>
<dt>Acidente de trabalho grave</dt>
<dd>O que resulta em morte, mutilação, internação ou incapacidade, ou atinge criança ou adolescente; notificação compulsória para qualquer vínculo.</dd>
</dl>
<h4>O essencial</h4>
<p>A <strong>PNSTT</strong> afirma que a saúde do trabalhador é responsabilidade do SUS e que o seu sujeito é <strong>todo trabalhador</strong>, com ou sem carteira, urbano ou rural, formal ou informal, inclusive o desempregado. Sua estratégia central é integrar a vigilância em saúde do trabalhador às demais vigilâncias e à <strong>APS</strong>, porque é no território que se vê o trabalho real: a confecção no fundo da casa, o canteiro de obras, o evento que se monta em três dias com equipe temporária.</p>
<p>A primeira tarefa da APS na saúde do trabalhador é <strong>identificar as atividades produtivas e as situações de risco no território</strong>: perguntar a todos os usuários o que fazem e onde, mapear os processos produtivos da área (inclusive os informais), e reconhecer os riscos físicos, químicos, biológicos, ergonômicos e da <strong>organização do trabalho</strong>, como prazos exíguos, jornadas longas, terceirização e equipes reduzidas, que são determinantes de acidentes tão importantes quanto a altura ou a carga.</p>
<p>A <strong>notificação</strong> segue a Portaria 264/2020: são compulsórios o acidente de trabalho <strong>grave</strong> (morte, mutilação, internação, incapacidade), o <strong>fatal</strong>, o que envolve <strong>crianças e adolescentes</strong> e o acidente com <strong>material biológico</strong>, além das doenças relacionadas ao trabalho.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>No pronto atendimento, três perguntas convertem o "acidente" em caso de saúde do trabalhador: estava trabalhando? fazendo o quê e para quem? com que proteção? Registre no prontuário, notifique no SINAN se grave, emita ou oriente a CAT, e comunique o CEREST para que a investigação alcance o local, porque o próximo trabalhador já está lá.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>PNSTT (2012): todo trabalhador, formal ou informal; RENAST e CEREST apoiam; APS integra a vigilância.</li>
<li>APS identifica atividades produtivas e riscos no território, inclusive da organização do trabalho, e age intersetorialmente.</li>
<li>Notificação compulsória: acidente grave, fatal, em criança ou adolescente, com material biológico; sem exigir vínculo, CAT ou 15 dias.</li>
<li>Assistir o acidentado é necessário; prevenir pela vigilância é o papel principal.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Um trabalhador informal se acidenta gravemente. Notifica-se no SINAN? <details><summary>Resposta</summary>Sim. A notificação do acidente de trabalho grave independe de vínculo formal.</details></li>
<li>O prazo de 15 dias de afastamento tem relação com a notificação? <details><summary>Resposta</summary>Não. É critério previdenciário para o auxílio por incapacidade; a notificação segue a gravidade, não o afastamento.</details></li>
</ol>
`,

"famema2026#78": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Reconhecer os grupos de sintomas do transtorno de estresse pós-traumático.</li>
<li>Distinguir estresse agudo, estresse pós-traumático, pânico e luto normal.</li>
<li>Conduzir o primeiro atendimento e o encaminhamento na APS.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Evento traumático</dt>
<dd>Exposição a morte, ameaça de morte, lesão grave ou violência sexual, vivida, testemunhada ou ocorrida com pessoa próxima.</dd>
<dt>Reexperiência</dt>
<dd>Memórias intrusivas, pesadelos, flashbacks e reações intensas a lembretes do evento.</dd>
<dt>Transtorno de estresse agudo</dt>
<dd>Sintomas semelhantes nos primeiros 3 dias a 1 mês após o trauma.</dd>
<dt>Terapia focada no trauma</dt>
<dd>Terapia cognitivo-comportamental focada no trauma e EMDR: primeira linha de tratamento.</dd>
</dl>
<h4>O essencial</h4>
<p>Depois de um evento traumático, reações de medo, insônia e lembranças são esperadas e, na maioria, passam em dias ou semanas.</p>
<p>O diagnóstico diferencial é clínico. No <strong>transtorno do pânico</strong>, as crises são inesperadas e não ligadas a um evento; no <strong>transtorno de ansiedade generalizada</strong>, a preocupação é difusa; na <strong>depressão</strong>, que frequentemente coexiste, domina o humor deprimido; no <strong>luto</strong>, o foco é a perda. Adolescentes vítimas de violência urbana, mulheres vítimas de violência sexual e doméstica, profissionais de emergência e sobreviventes de desastres são grupos de risco, e a prevalência após assalto à mão armada é alta. Sempre se rastreiam uso de substâncias e risco de suicídio.</p>
<p>A conduta na APS começa pelo <strong>acolhimento</strong> e pela <strong>psicoeducação</strong>: explicar que as reações são compreensíveis, que tendem a melhorar e que há tratamento. A <strong>primeira linha</strong> é a psicoterapia focada no trauma (terapia cognitivo-comportamental focada no trauma, exposição prolongada, EMDR), o que torna correto o encaminhamento à psicologia, e a APS garante o acesso pelo NASF ou eMulti, pelo CAPS infantojuvenil ou pela rede. Antidepressivos ISRS (sertralina, paroxetina) são segunda linha ou associados em quadros graves; benzodiazepínicos não previnem nem tratam o transtorno e podem piorá-lo.</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Perguntas de rastreio em quem passou por um evento grave: "tem sonhado ou revivido o que aconteceu?", "evita lugares ou pensamentos ligados a isso?", "anda em alerta, se assustando fácil, dormindo mal?", "sente culpa ou se afastou das pessoas?" Duas respostas positivas com prejuízo pedem avaliação e encaminhamento, não espera.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Quatro grupos: reexperiência, evitação, cognição e humor negativos, hiperexcitabilidade; mais de um mês e prejuízo.</li>
<li>Primeiro mês: transtorno de estresse agudo; pânico tem crises sem gatilho; depressão coexiste com frequência.</li>
<li>Primeira linha: psicoterapia focada no trauma; ISRS em segunda linha; benzodiazepínico não.</li>
<li>APS acolhe, psicoeduca, rastreia risco e encaminha; violência exige notificação.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Que duração diferencia o transtorno de estresse agudo do pós-traumático? <details><summary>Resposta</summary>Até um mês após o trauma é estresse agudo; acima de um mês, pós-traumático.</details></li>
<li>Qual é o tratamento de primeira linha do transtorno de estresse pós-traumático? <details><summary>Resposta</summary>Psicoterapia focada no trauma (terapia cognitivo-comportamental focada no trauma ou EMDR); ISRS em segunda linha.</details></li>
</ol>
`,

"famema2026#80": `
<h4>Objetivos de aprendizagem</h4>
<ul>
<li>Explicar a vigilância de epizootias em primatas não humanos e seu papel na febre amarela.</li>
<li>Orientar a conduta do cidadão e do serviço diante de um macaco morto.</li>
<li>Rever a transmissão, a vacina e as áreas de recomendação da febre amarela.</li>
</ul>
<h4>Termos-chave</h4>
<dl>
<dt>Epizootia</dt>
<dd>Doença ou morte de animais de uma espécie além do esperado; em primatas não humanos, evento sentinela da febre amarela, de notificação imediata.</dd>
<dt>Ciclo silvestre</dt>
<dd>Vírus circulando entre macacos e mosquitos <em>Haemagogus</em> e <em>Sabethes</em>; o humano se infecta ao entrar na mata.</dd>
<dt>Ciclo urbano</dt>
<dd>Transmissão humano-<em>Aedes aegypti</em>-humano, ausente no Brasil desde 1942, e cuja reintrodução a vigilância teme.</dd>
<dt>Vacina febre amarela</dt>
<dd>Vírus vivo atenuado 17D; dose única a partir dos 9 meses em todo o país, com reforço aos 4 anos para quem recebeu a primeira antes dos 5.</dd>
</dl>
<h4>O essencial</h4>
<p>A febre amarela no Brasil é <strong>silvestre</strong>: o vírus circula entre macacos e mosquitos de copa de árvore, e o humano adoece ao entrar na mata sem vacina. Os <strong>primatas não humanos</strong> são tão suscetíveis quanto nós, e as espécies brasileiras, sobretudo os bugios, morrem em grande número quando o vírus chega: por isso a <strong>morte de macacos é o evento sentinela</strong>, que antecede em semanas os casos humanos.</p>
<p>A <strong>epizootia em primatas não humanos</strong> está na Lista Nacional de Notificação Compulsória como notificação <strong>imediata</strong>, em até 24 horas, por qualquer pessoa ou serviço à vigilância municipal, estadual ou ao Disque Saúde 136. Quem encontra o animal <strong>não toca, não transporta, não enterra</strong>: avisa e protege o local, para que a equipe de zoonoses, com equipamento de proteção, colete amostras (vísceras, sangue, ou o animal inteiro) e as envie ao laboratório de referência.</p>
<p>A <strong>vacina</strong> é a única proteção eficaz: desde 2020 a área com recomendação de vacinação cobre todo o país, em dose única a partir dos <strong>9 meses</strong> (6 meses em situação de surto), com <strong>reforço aos 4 anos</strong> para quem a recebeu antes dos 5 anos; adultos vacinados uma vez estão protegidos. Contraindicações: imunossupressão grave, gestantes e lactantes de menores de 6 meses (avaliar risco), alergia grave ao ovo, e cautela acima dos 60 anos pelos eventos adversos graves raros (doença viscerotrópica).</p>
<div class="ponto">
<h4>Ponto clínico</h4>
<p>Numa UBS de área rural, a notícia de macacos mortos no sítio de um usuário é emergência de vigilância: ligar para a zoonoses no mesmo dia, orientar a família a não tocar no animal, conferir a vacinação de todos na microárea e, se houver suspeita, iniciar busca ativa de não vacinados. Febre e icterícia em quem andou na mata nas últimas duas semanas é febre amarela até prova em contrário.</p>
</div>
<h4>Resumo</h4>
<ul>
<li>Febre amarela silvestre: macacos e mosquitos de mata; a morte de macacos é o alerta que antecede os casos humanos.</li>
<li>Epizootia em primatas não humanos: notificação imediata (24 horas); não tocar, não transportar, não enterrar.</li>
<li>Confirmação dispara vacinação de bloqueio; matar macacos cega a vigilância.</li>
<li>Vacina: dose única aos 9 meses, reforço aos 4 anos, todo o país; contraindicações em imunossuprimidos e gestantes.</li>
</ul>
<h4>Verifique o que aprendeu</h4>
<ol>
<li>Em quanto tempo a epizootia em primatas deve ser notificada e por que é importante? <details><summary>Resposta</summary>Em até 24 horas; é o evento sentinela que antecede os casos humanos de febre amarela e permite a vacinação de bloqueio.</details></li>
<li>Qual é o esquema vacinal atual contra febre amarela no calendário nacional? <details><summary>Resposta</summary>Dose aos 9 meses e reforço aos 4 anos; quem recebe a primeira dose aos 5 anos ou mais fica com dose única.</details></li>
</ol>
`,
};
